#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t N = (size_t)60000 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N + 32);
    unsigned char key[16] = {0};
    unsigned char nonce[12] = {0};
    unsigned char aad[32] = {1};
    memset(pt, 0x41, N);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    int outlen = 0;

    // warmup
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, cipher, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    EVP_EncryptFinal_ex(ctx, ct + outlen, &outlen);
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int iters = 5;
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        int fin = 0;
        EVP_EncryptFinal_ex(ctx, ct + outlen, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double dt = (now() - t0) / iters;
    printf("C EVP time %.4f s  GBps %.2f\n", dt, N / dt / 1e9);

    // reuse: skip set ivlen by resetting differently
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        int fin = 0;
        EVP_EncryptFinal_ex(ctx, ct + outlen, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    dt = (now() - t0) / iters;
    printf("C EVP reinit time %.4f s  GBps %.2f\n", dt, N / dt / 1e9);

    // pipeline
    int np = 4;
    size_t chunk = N / np;
    unsigned char *outs[8], *ins[8];
    unsigned char *ivs_store[8];
    const unsigned char *ivs[8];
    size_t outl[8], inl[8], outsize[8];
    for (int i = 0; i < np; i++) {
        ins[i] = pt + i * chunk;
        outs[i] = ct + i * chunk;
        ivs_store[i] = malloc(12);
        memset(ivs_store[i], i+1, 12);
        ivs[i] = ivs_store[i];
        inl[i] = chunk;
        outsize[i] = chunk + 32;
    }
    int rc = EVP_CipherPipelineEncryptInit(ctx, cipher, key, 16, np, ivs, 12);
    printf("pipeline init %d\n", rc);
    if (rc == 1) {
        t0 = now();
        for (int i = 0; i < iters; i++) {
            EVP_CipherPipelineEncryptInit(ctx, cipher, key, 16, np, ivs, 12);
            rc = EVP_CipherPipelineUpdate(ctx, outs, outl, outsize, (const unsigned char **)ins, inl);
            if (rc != 1) { printf("upd fail\n"); break; }
            unsigned char *fm[8]; unsigned char fbuf[8][16];
            for (int j = 0; j < np; j++) fm[j] = fbuf[j];
            size_t foutl[8]; size_t fos[8];
            for (int j = 0; j < np; j++) fos[j] = 16;
            rc = EVP_CipherPipelineFinal(ctx, fm, foutl, fos);
        }
        dt = (now() - t0) / iters;
        printf("pipeline rc %d time %.4f s GBps %.2f\n", rc, dt, N / dt / 1e9);
    }
    return 0;
}
EOF
