#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/err.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t N = (size_t)60000 * 1024;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N + 64);
    unsigned char key[16] = {0};
    unsigned char nonce[12] = {0};
    memset(pt, 0x41, N);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // try fetched and legacy
    const EVP_CIPHER *ciphers[3];
    ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-128-GCM", "provider=default");
    ciphers[2] = EVP_aes_128_gcm();
    const char *names[] = {"fetch", "fetch-default", "legacy"};
    for (int c = 0; c < 3; c++) {
        printf("cipher %s ptr %p can_pipeline %d\n", names[c], (void*)ciphers[c],
               EVP_CIPHER_can_pipeline(ciphers[c], 1));
        unsigned char *ivs_store[4];
        const unsigned char *ivs[4];
        for (int i = 0; i < 4; i++) { ivs_store[i] = calloc(1,12); ivs_store[i][0]=i; ivs[i]=ivs_store[i]; }
        EVP_CIPHER_CTX *c2 = EVP_CIPHER_CTX_new();
        int rc = EVP_CipherPipelineEncryptInit(c2, ciphers[c], key, 16, 4, ivs, 12);
        printf("  pipeline init rc %d\n", rc);
        if (rc != 1) {
            unsigned long e = ERR_get_error();
            char buf[256];
            ERR_error_string_n(e, buf, sizeof buf);
            printf("  err %s\n", buf);
        }
        EVP_CIPHER_CTX_free(c2);
    }

    // CTR mode speed (no ghash)
    const EVP_CIPHER *ctr = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    int outlen;
    unsigned char iv[16] = {0};
    EVP_EncryptInit_ex(ctx, ctr, NULL, key, iv);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    double t0 = now();
    int iters = 5;
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    }
    double dt = (now()-t0)/iters;
    printf("CTR time %.4f GBps %.2f\n", dt, N/dt/1e9);

    // ECB
    const EVP_CIPHER *ecb = EVP_CIPHER_fetch(NULL, "AES-128-ECB", NULL);
    EVP_EncryptInit_ex(ctx, ecb, NULL, key, NULL);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    }
    dt = (now()-t0)/iters;
    printf("ECB time %.4f GBps %.2f\n", dt, N/dt/1e9);

    // GCM again for reference
    const EVP_CIPHER *gcm = ciphers[0];
    EVP_EncryptInit_ex(ctx, gcm, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)N);
        int fin=0; EVP_EncryptFinal_ex(ctx, ct+outlen, &fin);
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    dt = (now()-t0)/iters;
    printf("GCM time %.4f GBps %.2f\n", dt, N/dt/1e9);

    // chunked update to see overhead
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        size_t off = 0; size_t chunk = 1<<20;
        while (off < N) {
            int l = (int)((N-off) < chunk ? (N-off) : chunk);
            EVP_EncryptUpdate(ctx, ct+off, &outlen, pt+off, l);
            off += l;
        }
        int fin=0; EVP_EncryptFinal_ex(ctx, ct+N, &fin);
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    dt = (now()-t0)/iters;
    printf("GCM chunked 1MB time %.4f GBps %.2f\n", dt, N/dt/1e9);
    return 0;
}
EOF
