#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static EVP_CIPHER_CTX *ctx = NULL;
static const EVP_CIPHER *ciphers[3];

static int ensure(void) {
    if (ctx) return 1;
    ctx = EVP_CIPHER_CTX_new();
    ciphers[0] = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    ciphers[1] = EVP_CIPHER_fetch(NULL, "AES-192-GCM", NULL);
    ciphers[2] = EVP_CIPHER_fetch(NULL, "AES-256-GCM", NULL);
    return ctx && ciphers[0] && ciphers[1] && ciphers[2];
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad;
    if (!PyArg_ParseTuple(args, "y*y*y*y*p", &key, &nonce, &pt, &aad, &has_aad))
        return NULL;
    if (!ensure()) { PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad); return PyErr_NoMemory(); }
    const EVP_CIPHER *cipher = NULL;
    if (key.len == 16) cipher = ciphers[0];
    else if (key.len == 24) cipher = ciphers[1];
    else if (key.len == 32) cipher = ciphers[2];
    else { PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad); PyErr_SetString(PyExc_ValueError, "bad key"); return NULL; }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) goto fail;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL) != 1) goto fail;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) goto fail;

    int outlen = 0;
    if (has_aad && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, aad.buf, (int)aad.len) != 1) goto fail;
    }
    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct) goto fail;
    unsigned char *ctbuf = (unsigned char *)PyBytes_AS_STRING(ct);
    if (pt.len > 0) {
        if (EVP_EncryptUpdate(ctx, ctbuf, &outlen, pt.buf, (int)pt.len) != 1) { Py_DECREF(ct); goto fail; }
    } else outlen = 0;
    int fin = 0;
    if (EVP_EncryptFinal_ex(ctx, ctbuf + outlen, &fin) != 1) { Py_DECREF(ct); goto fail; }
    unsigned char tag[16];
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag) != 1) { Py_DECREF(ct); goto fail; }
    PyObject *tagobj = PyBytes_FromStringAndSize((char *)tag, 16);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    PyObject *res = PyTuple_Pack(2, ct, tagobj);
    Py_DECREF(ct); Py_DECREF(tagobj);
    return res;
fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    PyErr_SetString(PyExc_RuntimeError, "openssl encrypt failed");
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastgcm", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastgcm(void) { return PyModule_Create(&moduledef); }
EOF
