{"command":"export TMPDIR="$HOME/tmp"
cat > "$HOME/tmp/fastgcm2.c" << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <time.h>

static EVP_CIPHER_CTX *ctx = NULL;
static const EVP_CIPHER *cipher128 = NULL;

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static PyObject *bench(PyObject *self, PyObject *args) {
    Py_buffer pt;
    int iters;
    if (!PyArg_ParseTuple(args, "y*i", &pt, &iters)) return NULL;
    if (!ctx) {
        ctx = EVP_CIPHER_CTX_new();
        cipher128 = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    }
    unsigned char key[16] = {0};
    unsigned char nonce[12] = {0};
    unsigned char tag[16];
    int outlen, fin;
    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    unsigned char *ctbuf = (unsigned char *)PyBytes_AS_STRING(ct);

    double t_init=0, t_upd=0, t_fin=0;
    for (int i = 0; i < iters; i++) {
        double t0 = now();
        EVP_EncryptInit_ex(ctx, cipher128, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        double t1 = now();
        EVP_EncryptUpdate(ctx, ctbuf, &outlen, pt.buf, (int)pt.len);
        double t2 = now();
        EVP_EncryptFinal_ex(ctx, ctbuf + outlen, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        double t3 = now();
        t_init += t1-t0; t_upd += t2-t1; t_fin += t3-t2;
    }
    PyBuffer_Release(&pt);
    Py_DECREF(ct);
    return Py_BuildValue("ddd", t_init/iters, t_upd/iters, t_fin/iters);
}

/* encrypt into a caller-provided bytearray to avoid allocation inside timing */
static PyObject *bench_alloc(PyObject *self, PyObject *args) {
    Py_buffer pt;
    int iters;
    if (!PyArg_ParseTuple(args, "y*i", &pt, &iters)) return NULL;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
        Py_DECREF(ct);
    }
    double t1 = now();
    PyBuffer_Release(&pt);
    return Py_BuildValue("d", (t1-t0)/iters);
}

static PyMethodDef methods[] = {
    {"bench", bench, METH_VARARGS, NULL},
    {"bench_alloc", bench_alloc, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastgcm2", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastgcm2(void) { return PyModule_Create(&moduledef); }
EOF
cc -O3 -shared -fPIC -I/Library/Frameworks/Python.framework/Versions/3.11/include/python3.11 -I/usr/local/include -L/usr/local/lib -o "$HOME/tmp/fastgcm2.so" "$HOME/tmp/fastgcm2.c" -lcrypto -undefined dynamic_lookup 2>&1 | grep -v "cache file" | head
