    memset(Htable, 0, sizeof Htable);
    gcm_init_clmul(Htable, H);
    uint8_t Xi[16]; memset(Xi, 0, 16);
    gcm_ghash_clmul(Xi, Htable, buf, sizeof buf);
    hex("Xi v1 (H raw)", Xi, 16);

