    uint8_t Hb[16]; for (int i=0;i<16;i++) Hb[i]=H[15-i];
    memset(Htable, 0, sizeof Htable);
    gcm_init_clmul(Htable, Hb);
    memset(Xi, 0, 16);
    gcm_ghash_clmul(Xi, Htable, buf, sizeof buf);
    hex("Xi v2 (H bswap)", Xi, 16);
    uint8_t Xib[16]; for (int i=0;i<16;i++) Xib[i]=Xi[15-i];
    hex("Xi v2 bswap out", Xib, 16);

    /* try swapped argument order: gcm_init_clmul(H, Htable)? test by checking crash-free and match */
    return 0;
