    for(int i=0;i<16;i++){ unsigned char v=Xi[i], r=0; for(int b=0;b<8;b++){ r=(r<<1)|(v&1); v>>=1; } Xr[i]=r; }
    hex("bswap+bitrev out bitrev",Xr);
    unsigned char X2[16]; for(int i=0;i<16;i++) X2[i]=Xi[15-i]; hex("bswap+bitrev out bswap",X2);
