typedef struct {
    const unsigned char *in; unsigned char *out; size_t len; AES_KEY *key; unsigned char ivec[16];
    int ready; /* chunk produced */
} job_t;

static void *ctr_worker(void *arg){
    job_t *j=(job_t*)arg;
    unsigned char ecount[16]={0}; unsigned int num=0;
    CRYPTO_ctr128_encrypt_ctr32(j->in,j->out,j->len,j->key,j->ivec,ecount,&num,(ctr128_f)aesni_ctr32_encrypt_blocks);
    __atomic_store_n(&j->ready, 1, __ATOMIC_RELEASE);
    return NULL;
}

