        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}

static void ensure_workers(void) {
    if (started) return;
    for (int i = 0; i < NT; i++) {
        pthread_mutex_init(&W[i].mu, NULL);
        pthread_cond_init(&W[i].cv, NULL);
        W[i].go = W[i].stop = W[i].done = 0;
        pthread_create(&W[i].thread, NULL, worker_loop, &W[i]);
    }
    started = 1;
}

static void launch(int i) {
    pthread_mutex_lock(&W[i].mu);
    W[i].done = 0; W[i].go = 1;
    pthread_cond_signal(&W[i].cv);
    pthread_mutex_unlock(&W[i].mu);
}
static void waitw(int i) {
    pthread_mutex_lock(&W[i].mu);
    while (!W[i].done) pthread_cond_wait(&W[i].cv, &W[i].mu);
