extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       const AES_KEY *key, const unsigned char ivec[16], size_t blocks);
extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);

#define NT 3
typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    AES_KEY *key; unsigned char ivec[16];
    pthread_mutex_t mu; pthread_cond_t cv;
    int go, stop, done;
    pthread_t thread;
} worker_t;
static worker_t W[NT];
static int started = 0;
static void *worker_loop(void *arg) {
    worker_t *w = (worker_t *)arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->go && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); return NULL; }
        w->go = 0;
        pthread_mutex_unlock(&w->mu);
        unsigned char ecount[16] = {0};
        unsigned int num = 0;
        CRYPTO_ctr128_encrypt_ctr32(w->in, w->out, w->len, w->key, w->ivec,
                                    ecount, &num, (ctr128_f)aesni_ctr32_encrypt_blocks);
        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}
static void ensure_workers(void) {
    if (started) return;
    for (int i = 0; i < NT; i++) {
        pthread_mutex_init(&W[i].mu, NULL);
        pthread_cond_init(&W[i].cv, NULL);
        W[i].go = W[i].stop = W[i].done = 0;
        pthread_create(&W[i].thread, NULL, worker_loop, &W[i]);
    }
    started = 1;
}
static void launch(int i) { pthread_mutex_lock(&W[i].mu); W[i].done = 0; W[i].go = 1; pthread_cond_signal(&W[i].cv); pthread_mutex_unlock(&W[i].mu); }
static void waitw(int i) { pthread_mutex_lock(&W[i].mu); while (!W[i].done) pthread_cond_wait(&W[i].cv, &W[i].mu); pthread_mutex_unlock(&W[i].mu); }
static void bswap128(unsigned char *d, const unsigned char *s) { for (int i = 0; i < 8; i++) { d[i] = s[7 - i]; d[8 + i] = s[15 - i]; } }
static void put64(unsigned char *p, uint64_t v) { for (int i = 0; i < 8; i++) p[i] = (v >> (56 - 8 * i)) & 0xff; }
static double now(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec * 1e-9; }
static double acc_ctr = 0, acc_ghash = 0; static int ncalls = 0;

static unsigned char cached_key[32]; static int cached_keylen = -1;
static AES_KEY cached_aes; static unsigned char cached_Htable[16 * 16 * 16];
static void setup_key(const unsigned char *key, int keylen) {
    if (cached_keylen == keylen && memcmp(cached_key, key, keylen) == 0) return;
    memcpy(cached_key, key, keylen); cached_keylen = keylen;
    aesni_set_encrypt_key(key, keylen * 8, &cached_aes);
    unsigned char zero[16] = {0}, H[16], Hs[16];
    aesni_encrypt(zero, H, &cached_aes);
    bswap128(Hs, H);
