static PyObject *gcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &pt, &aad)) return NULL;
    ensure_workers();
    setup_key(key.buf, (int)key.len);

    size_t N = (size_t)pt.len;
    unsigned char *ct = (unsigned char *)aligned_alloc(64, (N + 63) & ~(size_t)63);
    const unsigned char *p = (const unsigned char *)pt.buf;
    size_t blocks = N / 16;
    size_t per = blocks / NT;

    double t0 = now();
    Py_BEGIN_ALLOW_THREADS
