        for (int i = 0; i < NT; i++) {
            size_t off = (size_t)i * per;
            size_t b = (i == NT - 1) ? blocks - off : per;
            W[i].in = p + off * 16; W[i].out = ct + off * 16; W[i].len = b * 16; W[i].key = &cached_aes;
            memcpy(W[i].ivec, nonce.buf, 12);
            unsigned int c = 2u + (unsigned)off;
            W[i].ivec[12] = c >> 24; W[i].ivec[13] = c >> 16; W[i].ivec[14] = c >> 8; W[i].ivec[15] = c;
            launch(i);
        }
        for (int i = 0; i < NT; i++) waitw(i);
