        unsigned char iv[16]; memcpy(iv, nonce.buf, 12);
        unsigned int c = 2u + (unsigned)(done / 16);
        iv[12] = c >> 24; iv[13] = c >> 16; iv[14] = c >> 8; iv[15] = c;
        unsigned char ecount[16] = {0}; unsigned int num = 0;
        CRYPTO_ctr128_encrypt_ctr32(p + done, ct + done, N - done, &cached_aes, iv, ecount, &num, (ctr128_f)aesni_ctr32_encrypt_blocks);
    }
    Py_END_ALLOW_THREADS
    acc_ctr += now() - t0;

    double t1 = now();
    unsigned char Xi[16] = {0};
    size_t aadlen = (size_t)aad.len;
    if (aadlen) {
