    pthread_mutex_lock(&GW.mu);
    for (int c = nchunks - NCTR; c < nchunks; c++) { if (c >= 0) GW.produced[c] = 1; }
    pthread_cond_broadcast(&GW.cv);
    while (!GW.done) pthread_cond_wait(&GW.cv, &GW.mu);
    unsigned char Xi[16]; memcpy(Xi, GW.Xi, 16);
    pthread_mutex_unlock(&GW.mu);

    /* fold aad ghash: GHASH is not commutative across the boundary, so AAD must come first.
       We computed AAD separately into Xi_aad. Combine by... we cannot combine two GHASH states
       without extra powers of H. Instead, redo: process AAD before ct within the ghash worker.
       Simpler fix: prepend AAD handling inside ghash worker. For now, recompute properly below
       if aad present. */
    if (aadlen) {
        /* recompute full ghash serially for correctness of AAD ordering: AAD then ct.
           This is only 32 bytes + we already have ct. Re-run ghash over ct starting from Xi_aad. */
        memcpy(Xi, Xi_aad, 16);
        size_t cfull = blocks * 16;
        if (cfull) gcm_ghash_avx(Xi, cached_Htable, ct, cfull);
    }
    size_t done = blocks * 16;
    if (done < N) {
        unsigned char iv[16]; memcpy(iv, nv, 12);
        unsigned int c = 2u + (unsigned)blocks;
        iv[12] = c >> 24; iv[13] = c >> 16; iv[14] = c >> 8; iv[15] = c;
        unsigned char e[16] = {0}; unsigned int num = 0;
        CRYPTO_ctr128_encrypt_ctr32(p + done, ct + done, N - done, &cached_aes, iv, e, &num, (ctr128_f)aesni_ctr32_encrypt_blocks);
        unsigned char pad[16] = {0}; memcpy(pad, ct + done, N - done);
        gcm_ghash_avx(Xi, cached_Htable, pad, 16);
    }
    unsigned char lenb[16] = {0}; put64(lenb, (uint64_t)aadlen * 8ull); put64(lenb + 8, (uint64_t)N * 8ull);
    gcm_ghash_avx(Xi, cached_Htable, lenb, 16);

    unsigned char J0[16]; memcpy(J0, nv, 12); J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;
    unsigned char EK[16]; aesni_encrypt(J0, EK, &cached_aes);
    unsigned char tag[16]; for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EK[i];
    Py_END_ALLOW_THREADS

    PyObject *tagobj = PyBytes_FromStringAndSize((char *)tag, 16);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    PyObject *res = PyTuple_Pack(2, ctobj, tagobj);
    Py_DECREF(ctobj); Py_DECREF(tagobj);
    return res;
}
static PyMethodDef methods[] = {{"encrypt", gcm_encrypt, METH_VARARGS, NULL}, {NULL, NULL, 0, NULL}};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastgcm", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastgcm(void) { return PyModule_Create(&moduledef); }
