#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    size_t n;
    unsigned char *key;
    unsigned char *nonce;
    unsigned char *aad;
    int aadlen;
    EVP_CIPHER *cipher;
    int reps;
} Job;

void *worker(void *arg) {
    Job *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen=0, finlen=0, al=0;
    unsigned char tag[16];
    for (int i = 0; i < j->reps; i++) {
        EVP_EncryptInit_ex(ctx, j->cipher, NULL, j->key, j->nonce);
        if (j->aadlen)
            EVP_EncryptUpdate(ctx, NULL, &al, j->aad, j->aadlen);
        EVP_EncryptUpdate(ctx, j->ct, &outlen, j->pt, (int)j->n);
        EVP_EncryptFinal_ex(ctx, j->ct + outlen, &finlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int threads = 4;
    size_t total = 40000 * 1024;
    size_t chunk = total / threads;
    unsigned char *pt = malloc(total);
    unsigned char *ct = malloc(total + 256);
    unsigned char key[32], nonce[12], aad[32];
    memset(pt, 0x42, total);
    memset(key, 1, 32);
    memset(nonce, 2, 12);
    memset(aad, 3, 32);
    EVP_CIPHER *cipher = EVP_CIPHER_fetch(NULL, "ChaCha20-Poly1305", NULL);

    /* warmup single */
    Job w = {pt, ct, total, key, nonce, aad, 32, cipher, 1};
    worker(&w);

    int reps = 3;
    double t0 = now();
    pthread_t th[8];
    Job jobs[8];
    for (int r = 0; r < reps; r++) {
        for (int t = 0; t < threads; t++) {
            jobs[t].pt = pt + t*chunk;
            jobs[t].ct = ct + t*chunk;
            jobs[t].n = chunk;
            jobs[t].key = key;
            jobs[t].nonce = nonce;
            jobs[t].aad = aad;
            jobs[t].aadlen = 0;
            jobs[t].cipher = cipher;
            jobs[t].reps = 1;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);
    }
    double t1 = now();
    printf("parallel %d threads, %d reps of 40MB split: total %.4f per-rep %.4f\n",
           threads, reps, t1-t0, (t1-t0)/reps);

    /* single thread same */
    t0 = now();
    Job j = {pt, ct, total, key, nonce, aad, 0, cipher, reps};
    worker(&j);
    t1 = now();
    printf("single thread %d reps: total %.4f per %.4f\n", reps, t1-t0, (t1-t0)/reps);
    return 0;
}
