{"command":"cat > ./chacha_aead.c << 'EOF'
/*
 * ChaCha20-Poly1305 AEAD (RFC 8439) using OpenSSL's ChaCha20_ctr32 and Poly1305.
 * Parallelizes the keystream generation across threads.
 *
 * Interface (called from Python via ctypes):
 *   int chacha20_poly1305_encrypt(
 *       const unsigned char *key,          // 32
 *       const unsigned char *nonce,        // 12
 *       const unsigned char *aad, int aad_len,
 *       const unsigned char *pt,  int pt_len,
 *       unsigned char *ct,                 // pt_len
 *       unsigned char *tag);               // 16
 */
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static void write_le64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) { p[i] = (unsigned char)(v & 0xff); v >>= 8; }
}

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} Job;

static void *worker(void *arg) {
    Job *j = (Job *)arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

/* persistent thread pool */
#define MAX_THREADS 8
static pthread_t threads[MAX_THREADS];
static Job jobs[MAX_THREADS];
static pthread_mutex_t start_mu[MAX_THREADS];
static pthread_cond_t start_cv[MAX_THREADS];
static pthread_mutex_t done_mu;
static pthread_cond_t done_cv;
static int go[MAX_THREADS];
static int stop_flag = 0;
static int pool_ready = 0;
static int pool_n = 0;
static int done_count = 0;

static void *pool_worker(void *arg) {
    long id = (long)arg;
    for (;;) {
        pthread_mutex_lock(&start_mu[id]);
        while (!go[id] && !stop_flag)
            pthread_cond_wait(&start_cv[id], &start_mu[id]);
        int stop = stop_flag;
        go[id] = 0;
        pthread_mutex_unlock(&start_mu[id]);
        if (stop) break;
        ChaCha20_ctr32(jobs[id].out, jobs[id].in, jobs[id].len, jobs[id].key, jobs[id].counter);
        pthread_mutex_lock(&done_mu);
        done_count++;
        pthread_cond_signal(&done_cv);
        pthread_mutex_unlock(&done_mu);
    }
    return NULL;
}

static void init_pool(int n) {
    if (pool_ready) return;
    pool_n = n;
    pthread_mutex_init(&done_mu, NULL);
    pthread_cond_init(&done_cv, NULL);
    for (int i = 0; i < n; i++) {
        pthread_mutex_init(&start_mu[i], NULL);
        pthread_cond_init(&start_cv[i], NULL);
        go[i] = 0;
        pthread_create(&threads[i], NULL, pool_worker, (void *)(long)i);
    }
    pool_ready = 1;
}

static void parallel_chacha(unsigned char *out, const unsigned char *in, size_t len,
                            const unsigned int key[8], unsigned int base_counter,
                            const unsigned int nonce_words[3]) {
    int nthreads = pool_n;
    /* split into 64-byte-block aligned chunks */
    size_t blocks = (len + 63) / 64;
    if (blocks < (size_t)nthreads * 4) {
        unsigned int counter[4] = {base_counter, nonce_words[0], nonce_words[1], nonce_words[2]};
        ChaCha20_ctr32(out, in, len, key, counter);
        return;
    }
    size_t blocks_per = (blocks + nthreads - 1) / nthreads;
    /* align so each chunk except last is multiple of blocks */
    pthread_mutex_lock(&done_mu);
    done_count = 0;
    pthread_mutex_unlock(&done_mu);

    int used = 0;
    size_t offset = 0;
    for (int t = 0; t < nthreads && offset < len; t++) {
        size_t this_blocks = blocks_per;
        size_t remain_blocks = (len - offset + 63) / 64;
        if (this_blocks > remain_blocks) this_blocks = remain_blocks;
        size_t this_len = this_blocks * 64;
        if (offset + this_len > len) this_len = len - offset;
        jobs[t].out = out + offset;
        jobs[t].in = in + offset;
        jobs[t].len = this_len;
        memcpy(jobs[t].key, key, 32);
        jobs[t].counter[0] = base_counter + (unsigned int)(offset / 64);
        jobs[t].counter[1] = nonce_words[0];
        jobs[t].counter[2] = nonce_words[1];
        jobs[t].counter[3] = nonce_words[2];
        used++;
        offset += this_len;
    }
    for (int t = 0; t < used; t++) {
        pthread_mutex_lock(&start_mu[t]);
        go[t] = 1;
        pthread_cond_signal(&start_cv[t]);
        pthread_mutex_unlock(&start_mu[t]);
    }
    pthread_mutex_lock(&done_mu);
    while (done_count < used)
        pthread_cond_wait(&done_cv, &done_mu);
    pthread_mutex_unlock(&done_mu);
}

int chacha20_poly1305_encrypt(
    const unsigned char *key,
    const unsigned char *nonce,
    const unsigned char *aad, int aad_len,
    const unsigned char *pt, int pt_len,
    unsigned char *ct,
    unsigned char *tag)
{
    if (!pool_ready) init_pool(6);

    unsigned int key_words[8];
    memcpy(key_words, key, 32);
    unsigned int nonce_words[3];
    memcpy(nonce_words, nonce, 12);

    /* Generate Poly1305 one-time key = first 32 bytes of block 0.
       RFC 8439: counter starts at 1 for payload, block 0 is the poly key. */
    unsigned char block0[64];
    unsigned char zeros[64];
    memset(zeros, 0, 64);
    unsigned int counter0[4] = {0, nonce_words[0], nonce_words[1], nonce_words[2]};
    ChaCha20_ctr32(block0, zeros, 64, key_words, counter0);

    unsigned char poly_key[32];
    memcpy(poly_key, block0, 32);

    /* payload keystream starts at counter = 1 */
    if (pt_len > 0) {
        parallel_chacha(ct, pt, (size_t)pt_len, key_words, 1, nonce_words);
    }

    /* Poly1305 over aad || pad || ct || pad || le64(aad_len) || le64(pt_len) */
    size_t csz = Poly1305_ctx_size();
    /* ctx on heap once, reused via static to avoid malloc per call. Poly1305_Init resets. */
    static unsigned char *pctx = NULL;
    static size_t pctx_sz = 0;
    if (!pctx) { pctx_sz = csz; pctx = malloc(csz); }
    Poly1305_Init(pctx, poly_key);

    if (aad && aad_len > 0) {
        Poly1305_Update(pctx, aad, (size_t)aad_len);
        int rem = aad_len & 15;
        if (rem) {
            unsigned char pad[16] = {0};
            Poly1305_Update(pctx, pad, (size_t)(16 - rem));
        }
    }
    if (pt_len > 0) {
        Poly1305_Update(pctx, ct, (size_t)pt_len);
        int rem = pt_len & 15;
        if (rem) {
            unsigned char pad[16] = {0};
            Poly1305_Update(pctx, pad, (size_t)(16 - rem));
        }
    }
    unsigned char lens[16];
    write_le64(lens, aad_len > 0 ? (uint64_t)aad_len : 0);
    write_le64(lens + 8, (uint64_t)(pt_len > 0 ? pt_len : 0));
    Poly1305_Update(pctx, lens, 16);
    Poly1305_Final(pctx, tag);
    return 1;
}

