#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

/* We use OpenSSL Poly1305 only as an oracle for the final tag.
   For partials we implement our own radix-2^26 Poly1305 that exposes (h, s) so we can combine. */

size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef __uint128_t u128;

typedef struct {
    u128 r;   /* r (clamped) */
    u128 s;   /* r^{nblocks} mod p */
    u128 h;   /* accumulator */
} Partial;

static const u128 P = (((u128)1) << 130) - 5;

static u128 modp(u128 x) {
    /* x < 2*P roughly? we reduce generally */
    /* For safety do a couple reductions. x can be up to ~ p*p during mul. */
    u128 lo = x & ((((u128)1) << 130) - 1);
    u128 hi = x >> 130;
    u128 r = lo + hi * 5;
    if (r >= P) r -= P;
    /* r could still be slightly over if hi large; one more */
    lo = r & ((((u128)1) << 130) - 1);
    hi = r >> 130;
    r = lo + hi * 5;
    if (r >= P) r -= P;
    return r;
}

static u128 mulmod(u128 a, u128 b) {
    /* 130-bit * 130-bit needs 260 bits. Use schoolbook on 64-bit limbs. */
    uint64_t a0 = (uint64_t)a;
    uint64_t a1 = (uint64_t)(a >> 64);
    uint64_t b0 = (uint64_t)b;
    uint64_t b1 = (uint64_t)(b >> 64);
    /* a1, b1 are at most 66 bits (130-64). product fits in... 66+66=132 bits, so need care.
       Use 32-bit limbs instead. */
    uint32_t A[5], B[5];
    for (int i = 0; i < 4; i++) { A[i] = (uint32_t)(a >> (32*i)); B[i] = (uint32_t)(b >> (32*i)); }
    A[4] = (uint32_t)(a >> 128); B[4] = (uint32_t)(b >> 128); /* 2 bits */
    uint64_t C[9] = {0};
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            C[i+j] += (uint64_t)A[i] * B[j];
    /* C[k] fits in 5*2^32*2^32 = 5*2^64, so 67 bits. OK in uint64? 5*(2^32-1)^2 = 5*2^64 - ... > 2^64.
       5 * (2^32)^2 = 5 * 2^64 which does NOT fit in uint64. Use uint128 accumulators. */
    return 0; /* placeholder, rewritten below */
}

/* proper mul */
static u128 mulmod2(u128 a, u128 b) {
    uint32_t A[5], B[5];
    for (int i = 0; i < 4; i++) { A[i] = (uint32_t)(a >> (32*i)); B[i] = (uint32_t)(b >> (32*i)); }
    A[4] = (uint32_t)(a >> 128); B[4] = (uint32_t)(b >> 128);
    u128 acc[9];
    for (int i = 0; i < 9; i++) acc[i] = 0;
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            acc[i+j] += (u128)A[i] * B[j];
    /* carry propagate to make a 288-bit number in 9x32, but we only need mod 2^130-5.
       Fold limbs >= 130 bits: bit position 32*k.
       For k such that 32*k >= 130, those bits contribute * 5 * 2^{32k-130}. */
    /* Convert acc to a flat big integer via carry, then reduce. */
    u128 limbs[9];
    u128 carry = 0;
    for (int i = 0; i < 9; i++) {
        u128 v = acc[i] + carry;
        limbs[i] = v & 0xffffffffu;
        carry = v >> 32;
    }
    /* now limbs[0..8] are 32-bit, carry is extra (should be 0 given bounds: 5*2^32*2^32 = 5<<64, after carry into next) */
    /* Build value mod 2^130-5:
       number = sum limbs[i] << (32*i)
       For bits at position >= 130: bit b contributes 5 * 2^{b-130}.
       Split each limb. */
    u128 lo = 0; /* bits 0..129 */
    u128 hi = 0; /* bits 130.. */
    for (int i = 0; i < 9; i++) {
        int shift = 32 * i;
        u128 limb = limbs[i];
        if (shift >= 130) {
            hi += limb << (shift - 130);
        } else if (shift + 32 <= 130) {
            lo += limb << shift;
        } else {
            int lo_bits = 130 - shift;
            lo += (limb & ((((u128)1) << lo_bits) - 1)) << shift;
            hi += limb >> lo_bits;
        }
    }
    /* result = lo + 5*hi  (mod 2^130-5), hi can be up to ~ 2^(288-130) = 2^158, 5*hi ~ 2^161.
       Reduce hi similarly. */
    u128 r = lo + (hi & ((((u128)1) << 130) - 1)) * 5;
    u128 hi2 = hi >> 130;
    r += hi2 * 25; /* 5*5 */
    /* r now < 2^130 + 5*2^130 + 25*2^{28} roughly. Reduce. */
    u128 rlo = r & ((((u128)1) << 130) - 1);
    u128 rhi = r >> 130;
    r = rlo + rhi * 5;
    rlo = r & ((((u128)1) << 130) - 1);
    rhi = r >> 130;
    r = rlo + rhi * 5;
    if (r >= P) r -= P;
    if (r >= P) r -= P;
    return r;
}

static u128 load16(const unsigned char *p) {
    u128 x = 0;
    for (int i = 0; i < 16; i++) x |= ((u128)p[i]) << (8*i);
    return x;
}

static void store16(unsigned char *p, u128 x) {
    for (int i = 0; i < 16; i++) { p[i] = (unsigned char)(x & 0xff); x >>= 8; }
}

static u128 clamp_r(u128 r) {
    r &= (((u128)1) << 124) - 1; /* clear top 4 bits of the 128 */
    /* actually r is 128 bits; clamp:
       r &= 0x0ffffffc0ffffffc0ffffffc0fffffff */
    const u128 mask = (((u128)0x0ffffffc0ffffffcULL) << 64) | 0x0ffffffc0fffffffULL;
    return r & mask;
}

static Partial poly_blocks(const unsigned char *data, size_t len, u128 r) {
    /* len must be multiple of 16 for partial (except we allow final partial separately) */
    Partial part;
    part.r = r;
    part.h = 0;
    part.s = 1; /* r^0 */
    size_t n = len / 16;
    size_t rem = len % 16;
    for (size_t i = 0; i < n; i++) {
        u128 nblock = load16(data + 16*i);
        nblock += ((u128)1) << 128; /* hibit */
        part.h = mulmod2(part.h + nblock, r);
        part.s = mulmod2(part.s, r);
    }
    if (rem) {
        unsigned char tmp[16] = {0};
        memcpy(tmp, data + 16*n, rem);
        tmp[rem] = 1;
        u128 nblock = load16(tmp);
        part.h = mulmod2(part.h + nblock, r);
        part.s = mulmod2(part.s, r);
    }
    return part;
}

/* combine: h = h1 + h2 * r^{n1}   where s1 = r^{n1} */
static Partial combine(Partial a, Partial b) {
    Partial c;
    c.r = a.r;
    c.h = modp(a.h + mulmod2(b.h, a.s));
    c.s = mulmod2(a.s, b.s);
    return c;
}

static void full_tag(const unsigned char *msg, size_t len, const unsigned char key[32], unsigned char tag[16]) {
    u128 r = clamp_r(load16(key));
    u128 s = load16(key + 16); /* not reduced */
    Partial p = poly_blocks(msg, len, r);
    u128 h = p.h;
    /* final reduction already done; add s mod 2^128 */
    u128 out = (h + s) & ((((u128)1) << 128) - 1);
    /* WAIT: standard poly1305 adds s to fully reduced h (h < p), result mod 2^128.
       h is < p < 2^130, so h+s may need the low 128 bits of (h+s) where h is fully reduced to < 2^130.
       The RFC says: fully reduce h modulo p to a number in 0..p-1, then add s mod 2^128.
       h < p so h fits in 131 bits. h+s fits in ~132. Low 128 bits = (h+s) mod 2^128.
       Yes. */
    store16(tag, (h + s) & ((((u128)1) << 128) - 1));
}

int main() {
    /* test against openssl */
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i*7 + 3);
    size_t N = 1000;
    unsigned char *msg = malloc(N);
    for (size_t i = 0; i < N; i++) msg[i] = (unsigned char)(i*13 + 1);

    unsigned char tag1[16], tag2[16];
    full_tag(msg, N, key, tag1);

    size_t csz = Poly1305_ctx_size();
    void *ctx = malloc(csz);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, msg, N);
    Poly1305_Final(ctx, tag2);
    printf("mine "); for (int i = 0; i < 16; i++) printf("%02x", tag1[i]); printf("\n");
    printf("ossl "); for (int i = 0; i < 16; i++) printf("%02x", tag2[i]); printf("\n");
    printf("match %d\n", memcmp(tag1, tag2, 16) == 0);

    /* also multiple of 16 */
    full_tag(msg, 992, key, tag1);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, msg, 992);
    Poly1305_Final(ctx, tag2);
    printf("aligned match %d\n", memcmp(tag1, tag2, 16) == 0);

    /* combine test */
    u128 r = clamp_r(load16(key));
    Partial a = poly_blocks(msg, 480, r);
    Partial b = poly_blocks(msg+480, 512, r);
    Partial c = combine(a, b);
    Partial d = poly_blocks(msg, 992, r);
    printf("combine h match %d s match %d\n", c.h == d.h, c.s == d.s);

    /* speed of scalar mulmod poly on 40MB (expect slow) */
    size_t BIG = 1<<20; /* 1MB first */
    unsigned char *big = malloc(BIG);
    memset(big, 0x5a, BIG);
    double t0 = now();
    full_tag(big, BIG, key, tag1);
    double t1 = now();
    printf("scalar poly 1MB: %.4f s (%.2f MB/s)\n", t1-t0, BIG/(t1-t0)/1e6);
    return 0;
}
