static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

static void *worker(void *arg) {
    unsigned char **p = arg;
    unsigned char *src = p[0], *dst = p[1];
    size_t n = (size_t)p[2];
    /* read+write */
    memcpy(dst, src, n);
    return NULL;
}

int main() {
    size_t N = 40000UL*1024;
    int reps = 3;
    for (int nt = 1; nt <= 8; nt *= 2) {
        unsigned char **bufs = malloc(sizeof(void*)*nt*2);
        size_t chunk = N/nt;
        for (int t = 0; t < nt; t++) {
            bufs[t*2] = malloc(chunk);
            bufs[t*2+1] = malloc(chunk);
            memset(bufs[t*2], 0x5a, chunk);
        }
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            pthread_t th[16];
            void *args[16][3];
            for (int t = 0; t < nt; t++) {
                args[t][0] = bufs[t*2]; args[t][1] = bufs[t*2+1]; args[t][2] = (void*)chunk;
                pthread_create(&th[t], NULL, worker, args[t]);
            }
            for (int t = 0; t < nt; t++) pthread_join(th[t], NULL);
        }
        double t1 = now();
        double bytes = (double)N * reps; /* read+write would be 2x but report payload */
        printf("%d threads memcpy payload: %.4f s (%.2f GB/s payload)\n", nt, (t1-t0)/reps, bytes/(t1-t0)/1e9);
    }
    return 0;
}
