{"command":"cat > ./bench_pipe2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

#define NT 4

static unsigned char *inbuf, *outbuf;
static size_t total, chunk;
static unsigned int keyw[8], nw[3];
static int job_id = 0;          /* incremented each job */
static int worker_seen[NT];
static int stop_flag = 0;
static pthread_mutex_t mu;
static pthread_cond_t cv_go, cv_done;
static int done_count;

static void *enc_worker(void *arg) {
    long id = (long)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (job_id == seen && !stop_flag) pthread_cond_wait(&cv_go, &mu);
        int stop = stop_flag;
        int myjob = job_id;
        pthread_mutex_unlock(&mu);
        if (stop) break;
        seen = myjob;
        /* each worker handles its slice */
        size_t off = (size_t)id * chunk;
        size_t len = (id == NT-1) ? (total - off) : chunk;
        unsigned int counter[4] = {(unsigned int)(off/64) + 1, nw[0], nw[1], nw[2]};
        ChaCha20_ctr32(outbuf+off, inbuf+off, len, keyw, counter);
        pthread_mutex_lock(&mu);
        done_count++;
        pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

int main() {
    total = 40000UL*1024;
    chunk = (total / NT) & ~((size_t)63);
    inbuf = malloc(total); outbuf = malloc(total);
    memset(inbuf, 0x5a, total);
    for (int i = 0; i < 8; i++) keyw[i] = i+1;
    nw[0]=9; nw[1]=10; nw[2]=11;

    pthread_mutex_init(&mu, NULL);
    pthread_cond_init(&cv_go, NULL);
    pthread_cond_init(&cv_done, NULL);

    pthread_t th[NT];
    for (long i = 0; i < NT; i++) pthread_create(&th[i], NULL, enc_worker, (void*)i);

    size_t csz = Poly1305_ctx_size();
    void *pctx = malloc(csz);
    unsigned char pkey[32]; memset(pkey, 0xab, 32);
    unsigned char mac[16];

    /* warmup */
    pthread_mutex_lock(&mu); done_count = 0; job_id++; pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
    pthread_mutex_lock(&mu); while (done_count < NT) pthread_cond_wait(&cv_done, &mu); pthread_mutex_unlock(&mu);

    int reps = 5;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        pthread_mutex_lock(&mu); done_count = 0; job_id++; pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
        pthread_mutex_lock(&mu); while (done_count < NT) pthread_cond_wait(&cv_done, &mu); pthread_mutex_unlock(&mu);
        Poly1305_Init(pctx, pkey);
        Poly1305_Update(pctx, outbuf, total);
        Poly1305_Final(pctx, mac);
    }
    double t1 = now();
    printf("pool enc then poly: %.4f s (%.2f GB/s)\n", (t1-t0)/reps, (total*reps/(t1-t0))/1e9);

    /* overlap: start enc, do poly of PREVIOUS output while enc runs? can't, same buffer.
       Instead double buffer. */
    unsigned char *out2 = malloc(total);
    double tA = now();
    for (int r = 0; r < reps; r++) {
        unsigned char *cur = (r % 2 == 0) ? outbuf : out2;
        unsigned char *prev = (r % 2 == 0) ? out2 : outbuf;
        /* swap which buffer workers write: we need workers to know. Use global outbuf pointer. */
        pthread_mutex_lock(&mu);
        outbuf = cur;
        done_count = 0; job_id++;
        pthread_cond_broadcast(&cv_go);
        pthread_mutex_unlock(&mu);
        if (r > 0) {
            Poly1305_Init(pctx, pkey);
            Poly1305_Update(pctx, prev, total);
            Poly1305_Final(pctx, mac);
        }
        pthread_mutex_lock(&mu); while (done_count < NT) pthread_cond_wait(&cv_done, &mu); pthread_mutex_unlock(&mu);
    }
    /* final poly */
    Poly1305_Init(pctx, pkey);
    Poly1305_Update(pctx, outbuf, total);
    Poly1305_Final(pctx, mac);
    double tB = now();
    printf("double-buffer overlap enc||poly: %.4f s (%.2f GB/s)\n", (tB-tA)/reps, (total*reps/(tB-tA))/1e9);

    stop_flag = 1;
    pthread_mutex_lock(&mu); pthread_cond_broadcast(&cv_go); pthread_mutex_unlock(&mu);
    for (int i = 0; i < NT; i++) pthread_join(th[i], NULL);
    return 0;
}
