{"command":"mkdir -p src && cat > src/chacha_avx2.h << 'EOF'
/* Public domain. Adapted from D. J. Bernstein's public-domain ChaCha20
   and the common AVX2 8-block interleaved implementation by Romain Dolbeau,
   simplified to a single self-contained function.
   chacha20_xor_avx2(out, in, len, key[8], counter_nonce[4])
   counter_nonce: word0 = block counter, word1..3 = nonce (96-bit).
   len may be any size; processed in 512-byte chunks plus tail. */
#ifndef CHACHA_AVX2_H
#define CHACHA_AVX2_H
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

static inline void chacha20_xor_avx2(uint8_t *out, const uint8_t *in, size_t len,
                                     const uint32_t key[8], const uint32_t counter[4]) {
    uint32_t ctr = counter[0];
    const uint32_t n0 = counter[1], n1 = counter[2], n2 = counter[3];
    const uint32_t k0 = key[0], k1 = key[1], k2 = key[2], k3 = key[3];
    const uint32_t k4 = key[4], k5 = key[5], k6 = key[6], k7 = key[7];

    const __m256i rot16 = _mm256_set_epi8(
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2,
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2);
    const __m256i rot8 = _mm256_set_epi8(
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3,
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3);

#define ROTL(x, n) (_mm256_or_si256(_mm256_slli_epi32((x), (n)), _mm256_srli_epi32((x), 32 - (n))))
#define QR(a,b,c,d) do { \
        a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = _mm256_shuffle_epi8(d, rot16); \
        c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = ROTL(b, 12); \
        a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = _mm256_shuffle_epi8(d, rot8); \
        c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = ROTL(b, 7); \
    } while (0)

    while (len >= 512) {
        __m256i x0 = _mm256_set1_epi32(0x61707865);
        __m256i x1 = _mm256_set1_epi32(0x3320646e);
        __m256i x2 = _mm256_set1_epi32(0x79622d32);
        __m256i x3 = _mm256_set1_epi32(0x6b206574);
        __m256i x4 = _mm256_set1_epi32(k0);
        __m256i x5 = _mm256_set1_epi32(k1);
        __m256i x6 = _mm256_set1_epi32(k2);
        __m256i x7 = _mm256_set1_epi32(k3);
        __m256i x8 = _mm256_set1_epi32(k4);
        __m256i x9 = _mm256_set1_epi32(k5);
        __m256i x10 = _mm256_set1_epi32(k6);
        __m256i x11 = _mm256_set1_epi32(k7);
        __m256i x12 = _mm256_set_epi32(ctr+7, ctr+6, ctr+5, ctr+4, ctr+3, ctr+2, ctr+1, ctr+0);
        __m256i x13 = _mm256_set1_epi32(n0);
        __m256i x14 = _mm256_set1_epi32(n1);
        __m256i x15 = _mm256_set1_epi32(n2);

        __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
        __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

        for (int r = 0; r < 10; r++) {
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
        }
        x0 = _mm256_add_epi32(x0, s0); x1 = _mm256_add_epi32(x1, s1);
        x2 = _mm256_add_epi32(x2, s2); x3 = _mm256_add_epi32(x3, s3);
        x4 = _mm256_add_epi32(x4, s4); x5 = _mm256_add_epi32(x5, s5);
        x6 = _mm256_add_epi32(x6, s6); x7 = _mm256_add_epi32(x7, s7);
        x8 = _mm256_add_epi32(x8, s8); x9 = _mm256_add_epi32(x9, s9);
        x10 = _mm256_add_epi32(x10, s10); x11 = _mm256_add_epi32(x11, s11);
        x12 = _mm256_add_epi32(x12, s12); x13 = _mm256_add_epi32(x13, s13);
        x14 = _mm256_add_epi32(x14, s14); x15 = _mm256_add_epi32(x15, s15);

        /* transpose 8 blocks of 64 bytes: each block is column of the 16 xmm lanes.
           Layout we have: x0..x15 each hold word i of 8 blocks.
           We want for each block b: words 0..15. Store via 8x8 transpose in two halves. */
        uint32_t tmp[128];
        _mm256_storeu_si256((__m256i*)(tmp+0), x0);
        _mm256_storeu_si256((__m256i*)(tmp+8), x1);
        _mm256_storeu_si256((__m256i*)(tmp+16), x2);
        _mm256_storeu_si256((__m256i*)(tmp+24), x3);
        _mm256_storeu_si256((__m256i*)(tmp+32), x4);
        _mm256_storeu_si256((__m256i*)(tmp+40), x5);
        _mm256_storeu_si256((__m256i*)(tmp+48), x6);
        _mm256_storeu_si256((__m256i*)(tmp+56), x7);
        _mm256_storeu_si256((__m256i*)(tmp+64), x8);
        _mm256_storeu_si256((__m256i*)(tmp+72), x9);
        _mm256_storeu_si256((__m256i*)(tmp+80), x10);
        _mm256_storeu_si256((__m256i*)(tmp+88), x11);
        _mm256_storeu_si256((__m256i*)(tmp+96), x12);
        _mm256_storeu_si256((__m256i*)(tmp+104), x13);
        _mm256_storeu_si256((__m256i*)(tmp+112), x14);
        _mm256_storeu_si256((__m256i*)(tmp+120), x15);
        /* tmp[w*8 + b] = word w of block b. We want block b words contiguous. */
        for (int b = 0; b < 8; b++) {
            uint32_t block[16];
            for (int w = 0; w < 16; w++) block[w] = tmp[w*8 + b];
            const uint8_t *src = in ? in + b*64 : NULL;
            uint8_t *dst = out + b*64;
            const uint32_t *ks = block;
            if (src) {
                for (int i = 0; i < 16; i++) {
                    uint32_t v = ks[i] ^ ((uint32_t)src[i*4] | ((uint32_t)src[i*4+1]<<8) |
                                          ((uint32_t)src[i*4+2]<<16) | ((uint32_t)src[i*4+3]<<24));
                    dst[i*4] = (uint8_t)v; dst[i*4+1] = (uint8_t)(v>>8);
                    dst[i*4+2] = (uint8_t)(v>>16); dst[i*4+3] = (uint8_t)(v>>24);
                }
            } else {
                memcpy(dst, block, 64);
            }
        }
        in += 512; out += 512; len -= 512; ctr += 8;
    }
#undef QR
#undef ROTL

    /* tail via scalar */
    while (len > 0) {
        uint32_t s[16] = {
            0x61707865, 0x3320646e, 0x79622d32, 0x6b206574,
            k0,k1,k2,k3,k4,k5,k6,k7, ctr, n0, n1, n2
        };
        uint32_t w[16];
        memcpy(w, s, 64);
        for (int r = 0; r < 10; r++) {
            #define QR4(a,b,c,d) do { \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<16)|(w[d]>>16); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<12)|(w[b]>>20); \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<8)|(w[d]>>24); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<7)|(w[b]>>25); \
            } while(0)
            QR4(0,4,8,12); QR4(1,5,9,13); QR4(2,6,10,14); QR4(3,7,11,15);
            QR4(0,5,10,15); QR4(1,6,11,12); QR4(2,7,8,13); QR4(3,4,9,14);
            #undef QR4
        }
        for (int i = 0; i < 16; i++) w[i] += s[i];
        size_t n = len < 64 ? len : 64;
        for (size_t i = 0; i < n; i++) {
            uint8_t ks = ((uint8_t *)w)[i];
            out[i] = in ? (uint8_t)(in[i] ^ ks) : ks;
        }
        if (in) in += n;
        out += n; len -= n; ctr++;
    }
}
#endif
