typedef struct { uint64_t lo, mid, hi; } fe;

static fe fe_from_bytes(const unsigned char *p, int n) {
    fe r = {0,0,0};
    for (int i = 0; i < n && i < 8; i++) r.lo |= ((uint64_t)p[i]) << (8*i);
    for (int i = 8; i < n && i < 16; i++) r.mid |= ((uint64_t)p[i]) << (8*(i-8));
    for (int i = 16; i < n && i < 24; i++) r.hi |= ((uint64_t)p[i]) << (8*(i-16));
    return r;
}

