   2^130 = bit 130 set = hi bit 2 (since hi bit 0 = bit 128, hi bit 1 = bit 129, hi bit 2 = bit 130).
   So 2^130 - 5: lo = ~4 = 0xfffffffffffffffb, mid = 0xffffffffffffffff, hi = 0x3 (bits 128,129 set) minus borrow?
   2^130 in (lo,mid,hi) = (0, 0, 4) because bit 130 = hi bit 2 = value 4.
   Subtract 5: lo = 0 - 5 (borrow), = 0xfffffffffffffffb, mid borrows, = 0xffffffffffffffff, hi = 4 - 1 = 3.
   Yes p = (0xfffffffffffffffb, 0xffffffffffffffff, 3). */
static const fe P = { 0xfffffffffffffffbULL, 0xffffffffffffffffULL, 3 };

static int fe_ge(fe a, fe b) { /* a >= b, both hi small */
    if (a.hi != b.hi) return a.hi > b.hi;
    if (a.mid != b.mid) return a.mid > b.mid;
    return a.lo >= b.lo;
}

static fe fe_sub(fe a, fe b) {
    fe r;
    uint64_t borrow = 0;
    r.lo = a.lo - b.lo; borrow = a.lo < b.lo;
    r.mid = a.mid - b.mid - borrow; borrow = (a.mid < b.mid) || (borrow && a.mid == b.mid);
    r.hi = a.hi - b.hi - borrow;
    return r;
}

static fe fe_reduce(fe a) {
    /* reduce a (hi may be up to, say, 2^32) mod p. a = lo + mid*2^64 + hi*2^128.
       Split off bits >= 130: bit 130+ are in hi (hi bit 2 and above = hi >> 2). 
       value = low130 + (hi>>2)*2^130, low130 = lo + mid*2^64 + (hi&3)*2^128.
       result = low130 + 5*(hi>>2), repeat. */
    while (a.hi >= 4) {
        uint64_t extra = a.hi >> 2; /* number of 2^130 */
        a.hi &= 3;
        /* add 5*extra to (lo,mid,hi) */
        unsigned __int128 s = (unsigned __int128)a.lo + (unsigned __int128)extra * 5;
