#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

typedef struct { uint64_t lo, mid; uint32_t hi; } fe; /* 130-bit: lo | mid<<64 | hi<<128 */

static fe from_limbs26(const uint32_t *h) {
    /* h0 + h1*2^26 + h2*2^52 + h3*2^78 + h4*2^104 */
    uint32_t h0=h[0], h1=h[1], h2=h[2], h3=h[3], h4=h[4];
    /* build via shifts */
    unsigned __int128 acc = 0;
    /* We'll accumulate into lo, mid, hi carefully. */
    /* bit layout:
       h0: bits 0..25
       h1: bits 26..51
       h2: bits 52..77
       h3: bits 78..103
       h4: bits 104..129 */
    uint64_t lo = 0, mid = 0; uint32_t hi = 0;
    lo = (uint64_t)h0 | ((uint64_t)h1 << 26) | ((uint64_t)(h2 & 0xfff) << 52);
    /* h2 bits 12..25 -> bits 64..77 of the number = mid bits 0..13 */
    mid = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14) | ((uint64_t)(h4 & 0xffffff) << 40);
    /* h3: bits 78..103. mid bit 0 = bit 64, so h3 starts at mid bit (78-64)=14. done above.
       h4: bits 104.. . starts at mid bit (104-64)=40. h4 has up to 26 bits -> bits 104..129.
       bits 104..127 = 24 bits -> mid bits 40..63. bits 128..129 = hi bits 0..1. */
    hi = h4 >> 24; /* bits above 128: h4's top bits. h4 bit 24 = number bit 128. */
    return (fe){lo, mid, hi};
}

static void print_fe(const char *n, fe a) {
    printf("%s hi=%x mid=%016llx lo=%016llx\n", n, a.hi, (unsigned long long)a.mid, (unsigned long long)a.lo);
}

static int ge(fe a, fe b) {
    if (a.hi != b.hi) return a.hi > b.hi;
    if (a.mid != b.mid) return a.mid > b.mid;
    return a.lo >= b.lo;
}
static fe sub(fe a, fe b) {
    uint64_t lo = a.lo - b.lo; int br = a.lo < b.lo;
    uint64_t mid = a.mid - b.mid - br; int br2 = (a.mid < b.mid) || (br && a.mid == b.mid);
    uint32_t hi = a.hi - b.hi - br2;
    return (fe){lo, mid, hi};
}
static fe reduce(fe a) {
    /* p = 2^130 - 5 */
    while (a.hi >= 4) {
        uint64_t extra = a.hi >> 2;
        a.hi &= 3;
        unsigned __int128 s = (unsigned __int128)a.lo + (unsigned __int128)extra * 5;
        a.lo = (uint64_t)s;
        uint64_t c = (uint64_t)(s >> 64);
        s = (unsigned __int128)a.mid + c;
        a.mid = (uint64_t)s;
        a.hi += (uint32_t)(s >> 64);
    }
    fe P = {0xfffffffffffffffbULL, 0xffffffffffffffffULL, 3};
    if (ge(a, P)) a = sub(a, P);
    return a;
}

static fe mul(fe a, fe b) {
    a = reduce(a); b = reduce(b);
    uint32_t A[5], B[5];
    A[0]=(uint32_t)a.lo; A[1]=(uint32_t)(a.lo>>32); A[2]=(uint32_t)a.mid; A[3]=(uint32_t)(a.mid>>32); A[4]=a.hi;
    B[0]=(uint32_t)b.lo; B[1]=(uint32_t)(b.lo>>32); B[2]=(uint32_t)b.mid; B[3]=(uint32_t)(b.mid>>32); B[4]=b.hi;
    unsigned __int128 acc[9]={0};
    for (int i=0;i<5;i++) for (int j=0;j<5;j++) acc[i+j] += (unsigned __int128)A[i]*B[j];
    uint32_t L[9]; uint64_t carry=0;
    for (int i=0;i<9;i++) { unsigned __int128 v = acc[i]+carry; L[i]=(uint32_t)v; carry=(uint64_t)(v>>32); }
    fe lo130={0,0,0}, hip={0,0,0};
    for (int i=0;i<9;i++) {
        int pos = 32*i; uint64_t limb = L[i];
        if (pos >= 130) {
            int sh = pos-130;
            if (sh < 64) {
                unsigned __int128 vv = (unsigned __int128)limb << sh;
                unsigned __int128 s2 = (unsigned __int128)hip.lo + (uint64_t)vv;
                hip.lo = (uint64_t)s2;
                unsigned __int128 s3 = (unsigned __int128)hip.mid + (uint64_t)(vv>>64) + (uint64_t)(s2>>64);
                hip.mid = (uint64_t)s3; hip.hi += (uint32_t)(s3>>64);
            } else {
                unsigned __int128 s3 = (unsigned __int128)hip.mid + ((unsigned __int128)limb << (sh-64));
                hip.mid = (uint64_t)s3; hip.hi += (uint32_t)(s3>>64);
            }
        } else if (pos+32 <= 130) {
            int sh = pos;
            if (sh < 64) {
                unsigned __int128 vv = (unsigned __int128)limb << sh;
                unsigned __int128 s2 = (unsigned __int128)lo130.lo + (uint64_t)vv;
                lo130.lo = (uint64_t)s2;
                unsigned __int128 s3 = (unsigned __int128)lo130.mid + (uint64_t)(vv>>64) + (uint64_t)(s2>>64);
                lo130.mid = (uint64_t)s3; lo130.hi += (uint32_t)(s3>>64);
            } else {
                unsigned __int128 s3 = (unsigned __int128)lo130.mid + ((unsigned __int128)limb << (sh-64));
                lo130.mid = (uint64_t)s3; lo130.hi += (uint32_t)(s3>>64);
            }
        } else {
            int lo_bits = 130-pos;
            uint64_t lowm = limb & (((uint64_t)1<<lo_bits)-1);
            uint64_t highm = limb >> lo_bits;
            unsigned __int128 vv = (unsigned __int128)lowm << pos;
            unsigned __int128 s2 = (unsigned __int128)lo130.lo + (uint64_t)vv;
            lo130.lo = (uint64_t)s2;
            unsigned __int128 s3 = (unsigned __int128)lo130.mid + (uint64_t)(vv>>64) + (uint64_t)(s2>>64);
            lo130.mid = (uint64_t)s3; lo130.hi += (uint32_t)(s3>>64);
            unsigned __int128 s4 = (unsigned __int128)hip.lo + highm;
            hip.lo = (uint64_t)s4; hip.mid += (uint64_t)(s4>>64);
        }
    }
    unsigned __int128 s = (unsigned __int128)hip.lo * 5;
    fe five = {(uint64_t)s, 0, 0}; uint64_t c = (uint64_t)(s>>64);
    s = (unsigned __int128)hip.mid * 5 + c;
    five.mid = (uint64_t)s; c = (uint64_t)(s>>64);
    five.hi = hip.hi * 5 + (uint32_t)c;
    /* add lo130 + five */
    s = (unsigned __int128)lo130.lo + five.lo;
    fe r; r.lo = (uint64_t)s; c = (uint64_t)(s>>64);
    s = (unsigned __int128)lo130.mid + five.mid + c;
    r.mid = (uint64_t)s; c = (uint64_t)(s>>64);
    r.hi = lo130.hi + five.hi + (uint32_t)c;
    return reduce(r);
}

static fe add(fe a, fe b) {
    unsigned __int128 s = (unsigned __int128)a.lo + b.lo;
    fe r; r.lo = (uint64_t)s; uint64_t c = (uint64_t)(s>>64);
    s = (unsigned __int128)a.mid + b.mid + c;
    r.mid = (uint64_t)s; c = (uint64_t)(s>>64);
    r.hi = a.hi + b.hi + (uint32_t)c;
    return reduce(r);
}

static fe get_h(const unsigned char *msg, size_t len, const unsigned char key[32]) {
    size_t csz = Poly1305_ctx_size();
    unsigned char *ctx = calloc(1, csz);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, msg, len);
    fe h = from_limbs26((uint32_t*)ctx);
    free(ctx);
    return reduce(h);
}

int main() {
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i*7 + 3);
    unsigned char msg[4096];
    for (int i = 0; i < 4096; i++) msg[i] = (unsigned char)(i*13 + 1);

    fe h = get_h(msg, 992, key);
