    /* produce tag from h and compare */
    fe s; s.lo = 0; s.mid = 0; s.hi = 0;
    for (int i = 0; i < 8; i++) s.lo |= ((uint64_t)key[16+i]) << (8*i);
    for (int i = 0; i < 8; i++) s.mid |= ((uint64_t)key[24+i]) << (8*i);
    unsigned __int128 sum = (unsigned __int128)h.lo + s.lo;
    uint64_t lo = (uint64_t)sum; uint64_t c = (uint64_t)(sum>>64);
    uint64_t mid = h.mid + s.mid + c;
    unsigned char tag[16], tag2[16];
    for (int i = 0; i < 8; i++) tag[i] = (unsigned char)(lo >> (8*i));
    for (int i = 0; i < 8; i++) tag[8+i] = (unsigned char)(mid >> (8*i));
    size_t csz = Poly1305_ctx_size();
    unsigned char *ctx = calloc(1, csz);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, msg, 992);
    Poly1305_Final(ctx, tag2);
    printf("tag match: %d\n", memcmp(tag, tag2, 16)==0);
    if (memcmp(tag,tag2,16)) {
        printf("mine "); for (int i=0;i<16;i++) printf("%02x",tag[i]); printf("\n");
        printf("ossl "); for (int i=0;i<16;i++) printf("%02x",tag2[i]); printf("\n");
