typedef struct { unsigned __int128 lo; uint64_t hi; } fe; /* 130-bit value: lo has 128 bits, hi has bits 128.. */

static const unsigned __int128 MASK128 = ~(unsigned __int128)0;

static fe fe_reduce(unsigned __int128 lo, unsigned __int128 hi_full) {
    /* value = lo + hi_full*2^128. Reduce mod 2^130-5.
       2^130 ≡ 5, so 2^128 = 2^130/4. Split hi_full into bits.
       value = (lo + (hi_full & 3)*2^128) + (hi_full >> 2)*2^130
             ≡ low130 + 5*(hi_full >> 2)  (mod p)
       low130 may itself be >= 2^130; fold once more. */
    unsigned __int128 low_lo = lo;
    uint64_t low_hi = (uint64_t)(hi_full & 3);
    unsigned __int128 extra = hi_full >> 2; /* coefficient of 2^130, multiply by 5 */
    /* add 5*extra */
    unsigned __int128 e5 = extra * 5;
    unsigned __int128 sum_lo = low_lo + e5;
    uint64_t carry = sum_lo < low_lo;
    uint64_t sum_hi = low_hi + carry;
    /* sum_hi may be >= 4 */
    unsigned __int128 extra2 = sum_hi >> 2;
    sum_hi &= 3;
    unsigned __int128 e5b = extra2 * 5;
    unsigned __int128 sum_lo2 = sum_lo + e5b;
    uint64_t carry2 = sum_lo2 < sum_lo;
    sum_hi += carry2;
    extra2 = sum_hi >> 2; sum_hi &= 3;
    sum_lo2 += extra2 * 5;
    fe r; r.lo = sum_lo2; r.hi = sum_hi;
    /* final conditional subtract p = 2^130 - 5 */
    unsigned __int128 plo = (unsigned __int128)(-5); /* 2^128 - 5 */
    uint64_t phi = 3;
    int ge = (r.hi > phi) || (r.hi == phi && r.lo >= plo);
    if (ge) {
        unsigned __int128 d = r.lo - plo;
        uint64_t br = r.lo < plo;
        r.lo = d; r.hi = r.hi - phi - br;
