    r10 += cf;                  /* adcq $0, %r10 */
    rax = r10;                  /* movq %r10, %rax */
    rcx = r10;                  /* movq %r10, %rcx */
    r10 &= 3;                   /* andq $3, %r10 */
    rax >>= 2;                  /* shrq $2, %rax */
    rcx &= ~4ULL;               /* andq $-4, %rcx */
    rax += rcx;                 /* addq %rcx, %rax */
    cf = (r8 + rax) < r8; r8 += rax;   /* addq %rax, %r8 */
    uint64_t cf2 = (r9 + cf) < r9; r9 += cf; /* adcq $0, %r9 */
    r10 += cf2;                 /* adcq $0, %r10 */
