typedef struct { unsigned __int128 lo; uint64_t hi; } fe; /* 130 bits */

static fe fe_reduce_full(unsigned __int128 lo, unsigned __int128 hi_full) {
    /* value = lo + hi_full*2^128. Reduce mod 2^130-5. */
    for (int iter = 0; iter < 4; iter++) {
        unsigned __int128 extra = hi_full >> 2;       /* multiples of 2^130 */
        uint64_t low_hi = (uint64_t)(hi_full & 3);
        unsigned __int128 add = extra * 5;
