        uint64_t c = new_lo < lo;
        uint64_t new_hi = low_hi + c;
        lo = new_lo;
        hi_full = new_hi;
        if (hi_full < 4) break;
    }
    /* conditional subtract p */
    unsigned __int128 plo = (unsigned __int128)(-5);
    uint64_t phi = 3;
    if (hi_full > phi || (hi_full == phi && lo >= plo)) {
        unsigned __int128 d = lo - plo;
        uint64_t br = lo < plo;
        lo = d; hi_full = hi_full - phi - br;
