new = r'''static fe fe_mul(fe a, fe b) {
    uint64_t a0=(uint64_t)a.lo, a1=(uint64_t)(a.lo>>64), a2=a.hi;
    uint64_t b0=(uint64_t)b.lo, b1=(uint64_t)(b.lo>>64), b2=b.hi;
    unsigned __int128 p0 = (unsigned __int128)a0*b0;
    unsigned __int128 p1 = (unsigned __int128)a0*b1 + (unsigned __int128)a1*b0;
    unsigned __int128 p2 = (unsigned __int128)a0*b2 + (unsigned __int128)a1*b1 + (unsigned __int128)a2*b0;
    unsigned __int128 p3 = (unsigned __int128)a1*b2 + (unsigned __int128)a2*b1;
    unsigned __int128 p4 = (unsigned __int128)a2*b2;
    /* product = p0 + p1*2^64 + p2*2^128 + p3*2^192 + p4*2^256.
       p4 = a2*b2 <= 9, so p4*2^256 = p4*2^126 * 2^130 ≡ p4*2^126 * 5 (mod p).
       Fold p4 into p2's position: 2^256 = 2^126 * 2^130 ≡ 5*2^126, and 2^126 = 2^192 / 2^66.
       Simpler: 2^256 ≡ 5 * 2^126, and 2^126 sits at bit 126, i.e. add 5*p4 << 126. */
    uint64_t r0 = (uint64_t)p0;
    unsigned __int128 mid = (p0 >> 64) + (uint64_t)p1;          /* coefficient of 2^64, may exceed 64 bits */
    uint64_t r1 = (uint64_t)mid;
    /* coefficient of 2^128: */
    unsigned __int128 hi128 = (mid >> 64) + (p1 >> 64) + p2;    /* bits starting at 128 */
    hi128 += p3 << 64;                                          /* p3*2^192 = p3*2^64 * 2^128 */
    /* p4*2^256 = p4*2^126 * 2^130 ≡ 5*p4*2^126. 2^126 is bit 126, which is within the 2^128-aligned region
       shifted down by 2: add (5*p4 << 126) to the value, i.e. to bits starting at 0. */
    unsigned __int128 fold = (unsigned __int128)(uint64_t)p4 * 5;
    fold <<= 126; /* bits 126.. */
    /* add fold into (r0, r1, hi128) */
    unsigned __int128 s0 = (unsigned __int128)r0 + (uint64_t)fold;
    uint64_t c0 = (uint64_t)(s0 >> 64);
    unsigned __int128 s1 = (unsigned __int128)r1 + (uint64_t)(fold >> 64) + c0;
    uint64_t c1 = (uint64_t)(s1 >> 64);
    r0 = (uint64_t)s0; r1 = (uint64_t)s1;
    hi128 += c1;
    return fe_reduce_full(((unsigned __int128)r1 << 64) | r0, hi128);
}

