    uint64_t o2 = r10m + c2;
    uint64_t p0 = o0 + 5; uint64_t c3 = p0 < o0;
    uint64_t p1 = o1 + c3; uint64_t c4 = p1 < o1;
    uint64_t p2 = o2 + c4;
