"""Single-shift QR with deflation, aggressive early deflation style, numba."""
import numpy as np, time, scipy.linalg
from numba import njit

@njit(fastmath=False)
def grot(a, b):
    r = np.hypot(a, b)
    if r == 0.0:
        return 1.0, 0.0
    return a/r, -b/r

@njit(fastmath=False)
def sweep(H, n, ilo, ihi, shift):
    c, s = grot(H[ilo, ilo] - shift, H[ilo+1, ilo])
    for j in range(ilo, n):
        t0 = H[ilo, j]; t1 = H[ilo+1, j]
        H[ilo, j] = c*t0 - s*t1
        H[ilo+1, j] = s*t0 + c*t1
    lim = ilo+2
    if lim > n-1:
        lim = n-1
    for i in range(0, lim+1):
        t0 = H[i, ilo]; t1 = H[i, ilo+1]
        H[i, ilo] = c*t0 - s*t1
        H[i, ilo+1] = s*t0 + c*t1
    for k in range(ilo, ihi-1):
        c, s = grot(H[k+1, k], H[k+2, k])
        for j in range(k, n):
            t0 = H[k+1, j]; t1 = H[k+2, j]
            H[k+1, j] = c*t0 - s*t1
            H[k+2, j] = s*t0 + c*t1
        lim = k+3
        if lim > n-1:
            lim = n-1
        for i in range(0, lim+1):
            t0 = H[i, k+1]; t1 = H[i, k+2]
            H[i, k+1] = c*t0 - s*t1
            H[i, k+2] = s*t0 + c*t1

@njit(fastmath=False)
def qr_driver(H, n, tol):
    ihi = n-1
    sweeps = 0
    it_since = 0
    while ihi >= 1:
        while ihi >= 1 and abs(H[ihi, ihi-1]) <= tol*(abs(H[ihi, ihi]) + abs(H[ihi-1, ihi-1])):
            H[ihi, ihi-1] = 0.0
            ihi -= 1
            it_since = 0
        if ihi < 1:
            break
        ilo = 0
        for i in range(ihi, 0, -1):
            if abs(H[i, i-1]) <= tol*(abs(H[i, i]) + abs(H[i-1, i-1])):
                H[i, i-1] = 0.0
                ilo = i
                break
        if ihi == ilo:
            ihi -= 1
            continue
        # Wilkinson shift from bottom entry, with exceptional shift periodically
        it_since += 1
        if it_since % 10 == 0:
            shift = H[ihi, ihi] + 1.5*abs(H[ihi, ihi-1])
        else:
            shift = H[ihi, ihi]
        sweep(H, n, ilo, ihi, shift)
        sweeps += 1
        if sweeps > 60*n:
            break
    return sweeps

def test(n, seed):
    rng = np.random.default_rng(seed)
    A = rng.standard_normal((n,n))
    H0 = np.ascontiguousarray(scipy.linalg.hessenberg(A, calc_q=False))
    Hc = H0.copy(); qr_driver(Hc, n, 1e-12)
    H = H0.copy()
    t0=time.perf_counter()
    sw = qr_driver(H, n, 1e-12)
    t1=time.perf_counter()
    w = np.diag(H).astype(complex)
    ref = np.linalg.eigvals(A)
    err = np.max(np.abs(np.sort_complex(w) - np.sort_complex(ref)))
    print(f'n={n} seed={seed}: {sw} sweeps {(t1-t0)*1000:.1f} ms eigval err {err:.2e}')

for n in [30, 60, 150]:
    for s in range(2):
        test(n, s)
