import numpy as np, time, scipy.linalg
from numba import njit

@njit(fastmath=False)
def hh3(x, y, z):
    beta = np.sqrt(x*x + y*y + z*z)
    if beta == 0.0:
        return 0.0, 0.0, 0.0
    sign = 1.0 if x >= 0.0 else -1.0
    v0 = x + sign*beta
    if v0 == 0.0:
        return 0.0, 0.0, 0.0
    v1 = y/v0
    v2 = z/v0
    tau = 2.0/(1.0 + v1*v1 + v2*v2)
    return v1, v2, tau

@njit(fastmath=False)
def hh2(x, y):
    beta = np.hypot(x, y)
    if beta == 0.0:
        return 0.0, 0.0
    sign = 1.0 if x >= 0.0 else -1.0
    v0 = x + sign*beta
    if v0 == 0.0:
        return 0.0, 0.0
    v1 = y/v0
    tau = 2.0/(1.0 + v1*v1)
    return v1, tau

@njit(fastmath=False)
def sweep(H, n, ilo, ihi):
    """Double-shift QR sweep on rows/cols ilo..ihi inclusive."""
    a = H[ihi-1, ihi-1]; b = H[ihi-1, ihi]; c0 = H[ihi, ihi-1]; d = H[ihi, ihi]
    tr = a + d
    det = a*d - b*c0
    h00 = H[ilo, ilo]; h10 = H[ilo+1, ilo]
    x = (h00 - tr)*h00 + H[ilo, ilo+1]*h10 + det
    y = h10*(h00 + H[ilo+1, ilo+1] - tr)
    z = h10*H[ilo+2, ilo+1]
    v1, v2, tau = hh3(x, y, z)
    if tau != 0.0:
        for j in range(ilo, n):
            s = tau*(H[ilo, j] + v1*H[ilo+1, j] + v2*H[ilo+2, j])
            H[ilo, j] -= s; H[ilo+1, j] -= s*v1; H[ilo+2, j] -= s*v2
        for i in range(0, ihi+1):
            s = tau*(H[i, ilo] + v1*H[i, ilo+1] + v2*H[i, ilo+2])
            H[i, ilo] -= s; H[i, ilo+1] -= s*v1; H[i, ilo+2] -= s*v2
    for k in range(ilo, ihi-2):
        x = H[k+1, k]; y = H[k+2, k]; z = H[k+3, k]
        v1, v2, tau = hh3(x, y, z)
        if tau == 0.0:
            continue
        r0 = k+1
        for j in range(k, n):
            s = tau*(H[r0, j] + v1*H[r0+1, j] + v2*H[r0+2, j])
            H[r0, j] -= s; H[r0+1, j] -= s*v1; H[r0+2, j] -= s*v2
        lim = k+4
        if lim > ihi:
            lim = ihi
        for i in range(0, lim+1):
            s = tau*(H[i, r0] + v1*H[i, r0+1] + v2*H[i, r0+2])
            H[i, r0] -= s; H[i, r0+1] -= s*v1; H[i, r0+2] -= s*v2
    k = ihi-2
    x = H[k+1, k]; y = H[k+2, k]
    v1, tau = hh2(x, y)
    if tau != 0.0:
        r0 = k+1
        for j in range(k, n):
            s = tau*(H[r0, j] + v1*H[r0+1, j])
            H[r0, j] -= s; H[r0+1, j] -= s*v1
        for i in range(0, ihi+1):
            s = tau*(H[i, r0] + v1*H[i, r0+1])
            H[i, r0] -= s; H[i, r0+1] -= s*v1

@njit(fastmath=False)
def eig_qr(H, n, tol):
    ihi = n-1
    sweeps = 0
    while ihi >= 2:
        while ihi >= 1 and abs(H[ihi, ihi-1]) <= tol*(abs(H[ihi, ihi]) + abs(H[ihi-1, ihi-1])):
            H[ihi, ihi-1] = 0.0
            ihi -= 1
        if ihi < 2:
            break
        ilo = 0
        for i in range(ihi, 0, -1):
            if abs(H[i, i-1]) <= tol*(abs(H[i, i]) + abs(H[i-1, i-1])):
                H[i, i-1] = 0.0
                ilo = i
                break
        if ihi - ilo < 2:
            ihi = ilo - 1
            continue
        sweep(H, n, ilo, ihi)
        sweeps += 1
        if sweeps > 40*n:
            break
    return sweeps

def extract(H, tol):
    n = H.shape[0]
    w = []
    i = 0
    while i < n:
        if i < n-1 and abs(H[i+1, i]) > tol:
