def test(n, seed):
    rng = np.random.default_rng(seed)
    A = rng.standard_normal((n,n))
    H0 = np.ascontiguousarray(scipy.linalg.hessenberg(A, calc_q=False))
    Hc = H0.copy(); eig_qr(Hc, n, 1e-12)
    H = H0.copy()
    t0=time.perf_counter()
    sw = eig_qr(H, n, 1e-13)
    t1=time.perf_counter()
    w = extract(H, 1e-8)
    ref = np.linalg.eigvals(A)
    err = np.max(np.abs(np.sort_complex(w)-np.sort_complex(ref)))
    print(f'n={n} seed={seed}: {sw} sweeps {(t1-t0)*1000:.2f} ms err {err:.2e}')

for n in [30, 60, 150]:
    for s in range(3):
        test(n, s)
