                Z[i, r0] -= s; Z[i, r0+1] -= s*v1

@njit(fastmath=False)
def schur(H, Z, n, tol, accZ):
    ihi = n-1
    sweeps = 0
    while ihi >= 2:
        while ihi >= 1 and abs(H[ihi, ihi-1]) <= tol*(abs(H[ihi, ihi]) + abs(H[ihi-1, ihi-1])):
            H[ihi, ihi-1] = 0.0
            ihi -= 1
        if ihi < 2:
            break
        ilo = 0
        for i in range(ihi, 0, -1):
            if abs(H[i, i-1]) <= tol*(abs(H[i, i]) + abs(H[i-1, i-1])):
                H[i, i-1] = 0.0
                ilo = i
                break
        if ihi - ilo < 2:
            ihi = ilo - 1
            continue
        sweep(H, Z, n, ilo, ihi, accZ)
        sweeps += 1
        if sweeps > 40*n:
            break
    return sweeps

