import numpy as np, time
from numba import njit

@njit(fastmath=False)
def chase_width(H, n, width):
    """Simulate one full bulge chase with a reflector of given width, numba scalar loops."""
    tau = 0.5
    v = np.empty(width)
    for t in range(width):
        v[t] = 0.1*(t+1)
    for k in range(n-width):
        r0 = k
        j0 = k
        for j in range(j0, n):
            s = 0.0
            for t in range(width):
                s += v[t]*H[r0+t, j]
            s *= tau
            for t in range(width):
                H[r0+t, j] -= s*v[t]
        lim = k+2*width
        if lim > n:
            lim = n
        c0 = k
        for i in range(0, lim):
            s = 0.0
            for t in range(width):
                s += v[t]*H[i, c0+t]
            s *= tau
            for t in range(width):
                H[i, c0+t] -= s*v[t]

