#include <cstdint>
#include <vector>
#include <cstring>
#include <limits>
#include <Python.h>
#include <numpy/arrayobject.h>

// Jonker-Volgenant shortest-augmenting-path LAP (minimization), dense.
// Uses a binary heap for the column scan.

static void lapjv(const double* cost, int n, int64_t* rowsol) {
    const double INF = std::numeric_limits<double>::infinity();
    std::vector<double> v(n, 0.0), minv(n);
    std::vector<int64_t> colsol(n, -1), pred(n);
    std::vector<char> used(n);

    // binary heap of (key, col). Simple array heap.
    std::vector<double> hkey(n);
    std::vector<int> hcol(n);
    std::vector<int> hpos(n);

    for (int i = 0; i < n; ++i) {
        std::memset(used.data(), 0, n);
        for (int j = 0; j < n; ++j) {
            minv[j] = cost[(size_t)i * n + j] - v[j];
            pred[j] = i;
        }
        // init heap with all columns
        int hs = n;
        for (int j = 0; j < n; ++j) { hkey[j] = minv[j]; hcol[j] = j; hpos[j] = j; }
        // heapify
        auto sift_up = [&](int p) {
            while (p > 0) {
                int par = (p - 1) >> 1;
                if (hkey[par] <= hkey[p]) break;
                std::swap(hkey[par], hkey[p]);
                std::swap(hcol[par], hcol[p]);
                hpos[hcol[par]] = par; hpos[hcol[p]] = p;
                p = par;
            }
        };
        auto sift_down = [&](int p) {
            for (;;) {
                int l = p * 2 + 1, r = l + 1, b = p;
                if (l < hs && hkey[l] < hkey[b]) b = l;
                if (r < hs && hkey[r] < hkey[b]) b = r;
                if (b == p) break;
                std::swap(hkey[b], hkey[p]);
                std::swap(hcol[b], hcol[p]);
                hpos[hcol[b]] = b; hpos[hcol[p]] = p;
                p = b;
            }
        };
        for (int p = (hs >> 1) - 1; p >= 0; --p) sift_down(p);

        int j_cur = -1;
        double best = INF;
        for (;;) {
            // pop
            j_cur = hcol[0];
            best = hkey[0];
            hs--;
            if (hs > 0) {
                hkey[0] = hkey[hs]; hcol[0] = hcol[hs]; hpos[hcol[0]] = 0;
                sift_down(0);
            }
            if (used[j_cur]) continue; // stale
            used[j_cur] = 1;
            int i_cur = (int)colsol[j_cur];
            if (i_cur < 0) break; // free column
            double h = cost[(size_t)i_cur * n + j_cur] - v[j_cur] - best;
            const double* row = cost + (size_t)i_cur * n;
            for (int j = 0; j < n; ++j) {
                if (used[j]) continue;
                double cand = row[j] - v[j] - h;
                if (cand < minv[j]) {
                    minv[j] = cand;
                    pred[j] = i_cur;
                    // decrease key
                    int p = hpos[j];
                    hkey[p] = cand;
                    sift_up(p);
                }
            }
        }
        for (int j = 0; j < n; ++j) if (used[j]) v[j] += minv[j] - best;
        while (j_cur >= 0) {
            int i_pred = (int)pred[j_cur];
            int j_prev = (i_pred == i) ? -1 : (int)rowsol[i_pred];
            rowsol[i_pred] = j_cur;
            colsol[j_cur] = i_pred;
            j_cur = j_prev;
        }
    }
}

static PyObject* py_lapjv(PyObject* self, PyObject* args) {
    PyObject* obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr,0) != PyArray_DIM(arr,1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "need square 2d array");
        return NULL;
    }
    int n = (int)PyArray_DIM(arr, 0);
    const double* data = (const double*)PyArray_DATA(arr);
    // ensure contiguous copy if needed
    std::vector<double> buf;
    const double* cost = data;
    if (!PyArray_IS_C_CONTIGUOUS(arr)) {
        buf.resize((size_t)n * n);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                buf[(size_t)i*n+j] = *(double*)PyArray_GETPTR2(arr, i, j);
        cost = buf.data();
    }
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    lapjv(cost, n, (int64_t*)PyArray_DATA((PyArrayObject*)out));
    Py_DECREF(arr);
    return out;
}

static PyMethodDef methods[] = {
    {"lapjv", py_lapjv, METH_VARARGS, "LAP JV"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "lapjv_cpp", NULL, -1, methods};
PyMODINIT_FUNC PyInit_lapjv_cpp(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
