    std::vector<int> order(n);
    for (int j = 0; j < n; ++j) order[j] = j;
    // process columns in order of increasing min cost to reduce conflicts
    std::vector<double> colmin(n);
    for (int j = 0; j < n; ++j) {
        double m = cost[j];
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) m = c;
        }
        colmin[j] = m;
    }
    std::sort(order.begin(), order.end(), [&](int a, int b){ return colmin[a] < colmin[b]; });

    for (int t = 0; t < n; ++t) {
        int j = order[t];
        double best = INF, second = INF;
        int best_i = 0;
        for (int i = 0; i < n; ++i) {
            double red = cost[(size_t)i * n + j] - u[i];
            if (red < best) { second = best; best = red; best_i = i; }
            else if (red < second) { second = red; }
