            rowsol[best_i] = j;
            colsol[j] = best_i;
            free_row[best_i] = 0;
            u[best_i] -= (second - best); // transfer reduction? classic uses u[i] = u[i] - (v[j]-second) wait
            // We set v[j]=best = c - u. Transfer: lower u so this row is less attractive.
            // Standard column reduction: u[i] = u[i] - (second - best) makes the chosen edge's
            // reduced cost equal second-best, encouraging uniqueness. Let's apply:
        } else {
            // already matched; keep as unmatched column for augmentation
        }
    }
    // recompute v consistently? The transfer modified u after v set; recompute v for matched cols.
    for (int j = 0; j < n; ++j) if (colsol[j] >= 0) {
        int i = (int)colsol[j];
        v[j] = cost[(size_t)i * n + j] - u[i];
    }

    for (int i = 0; i < n; ++i) if (free_row[i]) free_rows.push_back(i);

