// Jonker-Volgenant shortest augmenting path with:
//  - column reduction + reduction transfer initialization
//  - augmenting row reduction
//  - dense scan but only over an index list of unscanned columns (no used[] branch)
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cstring>
#include <cmath>
#include <Python.h>
#include <numpy/arrayobject.h>

static inline double BIG() { return 1e300; }

static void lapjv(const double* C, int n, int64_t* rowsol) {
    const double INF = BIG();
    std::vector<double> u(n, 0.0), v(n, 0.0), minv(n);
    std::vector<int64_t> colsol(n, -1), pred(n);
    std::vector<int> free_rows; free_rows.reserve(n);
    std::vector<char> free_row(n, 1);

    // ---------- COLUMN REDUCTION ----------
    for (int j = n - 1; j >= 0; --j) {
        double mn = INF, second = INF;
        int mi = 0;
        for (int i = 0; i < n; ++i) {
            double r = C[(size_t)i * n + j] - u[i];
            if (r < mn) { second = mn; mn = r; mi = i; }
            else if (r < second) second = r;
        }
        v[j] = mn;
        if (free_row[mi]) {
            rowsol[mi] = j;
            colsol[j] = mi;
            free_row[mi] = 0;
            // reduction transfer: make the chosen edge no better than the runner-up
            u[mi] -= (second - mn);
        }
    }
    // recompute v for assigned columns so reduced costs stay consistent
    for (int j = 0; j < n; ++j) if (colsol[j] >= 0) {
        int i = (int)colsol[j];
        v[j] = C[(size_t)i * n + j] - u[i];
    }
    for (int i = 0; i < n; ++i) if (free_row[i]) free_rows.push_back(i);

    // ---------- AUGMENTING ROW REDUCTION ----------
    // a couple of passes assigning free rows to their unique minimum reduced-cost column
    for (int pass = 0; pass < 2 && !free_rows.empty(); ++pass) {
        std::vector<int> still;
        still.reserve(free_rows.size());
        for (int i : free_rows) {
            const double* row = C + (size_t)i * n;
            double mn = INF, second = INF; int mj = 0;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < mn) { second = mn; mn = r; mj = j; }
                else if (r < second) second = r;
            }
            u[i] = mn;
            int i2 = (int)colsol[mj];
            if (i2 < 0) {
                // free column: assign
                rowsol[i] = mj; colsol[mj] = i;
                v[mj] -= (second - mn); // keep uniqueness slack on the column side
            } else if (second - mn < 1e-12 * (1.0 + std::fabs(mn))) {
                // unique minimum (tie within tol): steal it, previous row becomes free
                rowsol[i] = mj; colsol[mj] = i;
                v[mj] = row[mj] - u[i];
                still.push_back(i2);
            } else {
                still.push_back(i);
            }
        }
        free_rows.swap(still);
    }

    // ---------- SHORTEST AUGMENTING PATHS ----------
    std::vector<int> cols(n);
    for (int fi = 0; fi < (int)free_rows.size(); ++fi) {
        int i0 = free_rows[fi];
        int m = n;                       // number of unscanned columns
        for (int j = 0; j < n; ++j) cols[j] = j;
        const double* row0 = C + (size_t)i0 * n;
        for (int j = 0; j < n; ++j) { minv[j] = row0[j] - v[j]; pred[j] = i0; }

        int j_cur = -1; double best = INF;
        for (;;) {
            // scan unscanned columns for minimum
            best = INF; int pos = -1;
            for (int t = 0; t < m; ++t) {
                int j = cols[t];
                if (minv[j] < best) { best = minv[j]; pos = t; }
            }
            j_cur = cols[pos];
            // remove from unscanned list (swap with last)
            cols[pos] = cols[--m];
            int i_cur = (int)colsol[j_cur];
            if (i_cur < 0) break;
            double h = C[(size_t)i_cur * n + j_cur] - v[j_cur] - best;
            const double* row = C + (size_t)i_cur * n;
            for (int t = 0; t < m; ++t) {
                int j = cols[t];
                double cand = row[j] - v[j] - h;
                if (cand < minv[j]) { minv[j] = cand; pred[j] = i_cur; }
            }
        }
        // dual update over scanned columns = all not in cols[0..m)
        // easier: scanned iff not in the remaining list
        std::vector<char> scanned(n, 1);
        for (int t = 0; t < m; ++t) scanned[cols[t]] = 0;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += minv[j] - best;

        while (j_cur >= 0) {
            int i_pred = (int)pred[j_cur];
            int j_prev = (i_pred == i0) ? -1 : (int)rowsol[i_pred];
            rowsol[i_pred] = j_cur;
            colsol[j_cur] = i_pred;
            j_cur = j_prev;
        }
    }
}

static PyObject* py_lapjv(PyObject* self, PyObject* args) {
    PyObject* obj;
