// Bertsekas epsilon-scaling auction for the dense assignment problem.
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cmath>
#include <Python.h>
#include <numpy/arrayobject.h>

struct Res { double eps; int iters; int unassigned; };

static Res auction(const double* C, int n, int64_t* rowsol, double eps_final, double eps_factor) {
    std::vector<double> price(n, 0.0), bid(n);
    std::vector<int> owner(n, -1), bidder(n);
    std::vector<char> assigned(n, 0);
    int nunassigned = n;
    double Cmax = 0;
    for (size_t k = 0; k < (size_t)n*n; ++k) if (C[k] > Cmax) Cmax = C[k];
    double eps = Cmax / 4.0;
    if (eps < eps_final) eps = eps_final;
    int total_iters = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assigned.begin(), assigned.end(), 0);
        nunassigned = n;
        int guard = 0;
        while (nunassigned > 0 && guard < n * 200) {
            guard++;
            total_iters++;
            // each unassigned row bids for its best column
            std::fill(bid.begin(), bid.end(), -1e300);
            std::fill(bidder.begin(), bidder.end(), -1);
            for (int i = 0; i < n; ++i) {
                if (assigned[i]) continue;
                const double* row = C + (size_t)i * n;
                // we minimize cost => maximize -cost - price
                double best = -1e300, second = -1e300; int bj = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; bj = j; }
                    else if (val > second) second = val;
                }
                double b = price[bj] + (best - second) + eps;
                if (b > bid[bj]) { bid[bj] = b; bidder[bj] = i; }
            }
            for (int j = 0; j < n; ++j) {
                int i = bidder[j];
                if (i < 0) continue;
                int prev = owner[j];
                if (prev >= 0) { assigned[prev] = 0; nunassigned++; }
                owner[j] = i;
                if (!assigned[i]) { assigned[i] = 1; nunassigned--; }
                price[j] = bid[j];
            }
        }
        if (eps <= eps_final * 1.0000001) break;
        eps *= eps_factor;
        if (eps < eps_final) eps = eps_final;
    }
    for (int j = 0; j < n; ++j) if (owner[j] >= 0) rowsol[owner[j]] = j;
    return {eps, total_iters, nunassigned};
}

static PyObject* py_auction(PyObject* self, PyObject* args) {
    PyObject* obj; double eps_final, eps_factor;
    if (!PyArg_ParseTuple(args, "Odd", &obj, &eps_final, &eps_factor)) return NULL;
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    if (!arr) return NULL;
    int n = (int)PyArray_DIM(arr, 0);
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    Res r = auction((const double*)PyArray_DATA(arr), n, (int64_t*)PyArray_DATA((PyArrayObject*)out), eps_final, eps_factor);
    Py_DECREF(arr);
    return Py_BuildValue("Nidi", out, r.iters, r.eps, r.unassigned);
}
static PyMethodDef methods[] = {{"auction", py_auction, METH_VARARGS, ""},{NULL,NULL,0,NULL}};
static struct PyModuleDef md = {PyModuleDef_HEAD_INIT, "auction_cpp", NULL, -1, methods};
PyMODINIT_FUNC PyInit_auction_cpp(void){ import_array(); return PyModule_Create(&md); }
