// Sparse auction: each row has k candidate columns (idx) with values (val).
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cmath>
#include <Python.h>
#include <numpy/arrayobject.h>

static void auction_sp(const double* val, const int64_t* idx, int n, int k,
                       int64_t* rowsol, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<char> assigned(n, 0);
    std::vector<double> bid(n);
    std::vector<int> bidder(n);
    double Cmax = 0;
    for (size_t t = 0; t < (size_t)n*k; ++t) if (val[t] > Cmax) Cmax = val[t];
    double eps = Cmax / 4.0;
    const double factor = 0.2;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assigned.begin(), assigned.end(), 0);
        int nunassigned = n;
        int guard = 0;
        int guardmax = n * 400;
        while (nunassigned > 0 && guard < guardmax) {
            guard++;
            std::fill(bid.begin(), bid.end(), -1e300);
            std::fill(bidder.begin(), bidder.end(), -1);
            for (int i = 0; i < n; ++i) {
                if (assigned[i]) continue;
                const double* rv = val + (size_t)i * k;
                const int64_t* ri = idx + (size_t)i * k;
                double best = -1e300, second = -1e300; int bj = (int)ri[0];
                for (int t = 0; t < k; ++t) {
                    double w = -rv[t] - price[ri[t]];
                    if (w > best) { second = best; best = w; bj = (int)ri[t]; }
                    else if (w > second) second = w;
                }
                if (second < -1e299) second = best - 1.0;
                double b = price[bj] + (best - second) + eps;
                if (b > bid[bj]) { bid[bj] = b; bidder[bj] = i; }
            }
            bool progress = false;
            for (int j = 0; j < n; ++j) {
                int i = bidder[j];
                if (i < 0) continue;
                progress = true;
                int prev = owner[j];
                if (prev >= 0 && prev != i) { assigned[prev] = 0; nunassigned++; }
                owner[j] = i;
                if (!assigned[i]) { assigned[i] = 1; nunassigned--; }
                price[j] = bid[j];
            }
            if (!progress) break;
        }
        if (nunassigned > 0) { // failed at this eps; relax by widening not possible here
            // mark failure
            for (int i = 0; i < n; ++i) rowsol[i] = -1;
            return;
        }
        if (eps <= eps_final * 1.0000001) {
            for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
            return;
        }
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
    }
}

