// Gauss-Seidel epsilon-scaling auction on a sparse candidate graph.
// val: (n,k) candidate costs, idx: (n,k) int64 candidate columns.
// Returns row->col assignment (col may repeat if graph forbids a perfect matching).
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cmath>
#include <Python.h>
#include <numpy/arrayobject.h>

struct Res { int iters; int unassigned; };

static Res auction(const double* val, const int64_t* idx, int n, int k,
                   int64_t* rowsol, double eps_final, double factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<char> assigned(n, 0);
    double Cmax = 0.0;
    for (size_t t = 0; t < (size_t)n * k; ++t) if (val[t] > Cmax) Cmax = val[t];
    double eps = std::max(Cmax / 4.0, eps_final);
    int total = 0;
    int nunassigned = n;
    for (;;) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assigned.begin(), assigned.end(), 0);
        nunassigned = n;
        // greedy seed from current prices
        for (int i = 0; i < n; ++i) {
            const double* rv = val + (size_t)i * k;
            const int64_t* ri = idx + (size_t)i * k;
            double best = -1e300; int bj = (int)ri[0];
            for (int t = 0; t < k; ++t) {
                double w = -rv[t] - price[ri[t]];
                if (w > best) { best = w; bj = (int)ri[t]; }
            }
            if (owner[bj] < 0) { owner[bj] = i; assigned[i] = 1; nunassigned--; }
        }
        int guard = 0, guardmax = n * 500;
        while (nunassigned > 0 && guard < guardmax) {
            bool progress = false;
            for (int i = 0; i < n; ++i) {
                if (assigned[i]) continue;
                guard++; total++;
                const double* rv = val + (size_t)i * k;
                const int64_t* ri = idx + (size_t)i * k;
                double best = -1e300, second = -1e300; int bj = (int)ri[0];
                for (int t = 0; t < k; ++t) {
                    double w = -rv[t] - price[ri[t]];
                    if (w > best) { second = best; best = w; bj = (int)ri[t]; }
                    else if (w > second) second = w;
                }
                if (second < -1e299) second = best - 1.0;
                double b = price[bj] + (best - second) + eps;
                int prev = owner[bj];
                if (prev >= 0 && prev != i) { assigned[prev] = 0; nunassigned++; }
                owner[bj] = i;
                if (!assigned[i]) { assigned[i] = 1; nunassigned--; }
                price[bj] = b;
                progress = true;
                if (nunassigned == 0) break;
            }
            if (!progress) break;
        }
        if (nunassigned > 0) {
            for (int i = 0; i < n; ++i) rowsol[i] = -1;
            return {total, nunassigned};
        }
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps * factor, eps_final);
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
    return {total, 0};
}

static PyObject* py_auction(PyObject* self, PyObject* args) {
    PyObject *vo, *io; double eps, factor;
    if (!PyArg_ParseTuple(args, "OOdd", &vo, &io, &eps, &factor)) return NULL;
    PyArrayObject* val = (PyArrayObject*)PyArray_FROM_OTF(vo, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* idx = (PyArrayObject*)PyArray_FROM_OTF(io, NPY_INT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    if (!val || !idx) return NULL;
    int n = (int)PyArray_DIM(val,0), k = (int)PyArray_DIM(val,1);
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    Res r = auction((const double*)PyArray_DATA(val), (const int64_t*)PyArray_DATA(idx),
                    n, k, (int64_t*)PyArray_DATA((PyArrayObject*)out), eps, factor);
    Py_DECREF(val); Py_DECREF(idx);
