// Complete a partial assignment to a globally optimal one by shortest augmenting
// paths (Jonker-Volgenant), starting from a partial matching given as row->col
// (-1 = unmatched row).
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cstring>
#include <cmath>
#include <Python.h>
#include <numpy/arrayobject.h>

static void refine(const double* C, int n, int64_t* rowsol) {
    std::vector<double> u(n, 0.0), v(n, 0.0), minv(n);
    std::vector<int64_t> colsol(n, -1), pred(n);
    std::vector<int> cols(n);
    std::vector<char> scanned(n);

    for (int i = 0; i < n; ++i) {
        int j = (int)rowsol[i];
        if (j >= 0 && colsol[j] < 0) colsol[j] = i;
        else rowsol[i] = -1;
    }
    // initialise duals so matched edges are tight and reduced costs nonnegative-ish
    for (int j = 0; j < n; ++j) if (colsol[j] >= 0) {
        int i = (int)colsol[j];
        v[j] = C[(size_t)i * n + j];
    }

    for (int i0 = 0; i0 < n; ++i0) {
        if (rowsol[i0] >= 0) continue;
        int m = n;
        for (int j = 0; j < n; ++j) cols[j] = j;
        const double* row0 = C + (size_t)i0 * n;
        for (int j = 0; j < n; ++j) { minv[j] = row0[j] - v[j]; pred[j] = i0; }
        int j_cur = -1; double best = 1e300;
        for (;;) {
            best = 1e300; int pos = -1;
            for (int t = 0; t < m; ++t) {
                int j = cols[t];
                if (minv[j] < best) { best = minv[j]; pos = t; }
            }
            j_cur = cols[pos];
            cols[pos] = cols[--m];
            int i_cur = (int)colsol[j_cur];
            if (i_cur < 0) break;
            double h = C[(size_t)i_cur * n + j_cur] - v[j_cur] - best;
            const double* row = C + (size_t)i_cur * n;
            for (int t = 0; t < m; ++t) {
                int j = cols[t];
                double cand = row[j] - v[j] - h;
                if (cand < minv[j]) { minv[j] = cand; pred[j] = i_cur; }
            }
        }
        std::memset(scanned.data(), 1, n);
        for (int t = 0; t < m; ++t) scanned[cols[t]] = 0;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += minv[j] - best;
        while (j_cur >= 0) {
            int i_pred = (int)pred[j_cur];
            int j_prev = (i_pred == i0) ? -1 : (int)rowsol[i_pred];
            rowsol[i_pred] = j_cur;
            colsol[j_cur] = i_pred;
            j_cur = j_prev;
        }
    }
}

static PyObject* py_refine(PyObject* self, PyObject* args) {
    PyObject *mo, *co;
    if (!PyArg_ParseTuple(args, "OO", &mo, &co)) return NULL;
    PyArrayObject* M = (PyArrayObject*)PyArray_FROM_OTF(mo, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* col = (PyArrayObject*)PyArray_FROM_OTF(co, NPY_INT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    if (!M || !col) return NULL;
    int n = (int)PyArray_DIM(M, 0);
    npy_intp dims[1] = {n};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT64);
    int64_t* rs = (int64_t*)PyArray_DATA((PyArrayObject*)out);
    std::memcpy(rs, PyArray_DATA(col), n * sizeof(int64_t));
    refine((const double*)PyArray_DATA(M), n, rs);
    Py_DECREF(M); Py_DECREF(col);
    return out;
}
