    std::vector<int64_t> colsol(n, -1), pred(n);
    std::vector<int> cols(n);
    std::vector<char> scanned(n);

    // column reduction with reduction transfer
    std::vector<char> free_row(n, 1);
    for (int j = n - 1; j >= 0; --j) {
        const double* col = nullptr;
