                if (w > best) { second = best; best = w; bj = (int)ri[t]; }
                else if (w > second) second = w;
            }
            if (second < -1e299) second = best - 1.0;
            double b = price[bj] + (best - second) + eps;
            // atomic max via compare; conflicts resolved serially below, so just record
            // We store per-row bid and resolve in serial. Use thread-local then merge.
        }
    };

    // per-row bid targets
    std::vector<int> row_choice(n);
    std::vector<double> row_bid(n);

    auto compute = [&](int lo, int hi, double eps) {
        for (int i = lo; i < hi; ++i) {
            if (assigned[i]) { row_choice[i] = -1; continue; }
            const double* rv = val + (size_t)i * k;
            const int64_t* ri = idx + (size_t)i * k;
            double best = -1e300, second = -1e300; int bj = (int)ri[0];
            for (int t = 0; t < k; ++t) {
                double w = -rv[t] - price[ri[t]];
                if (w > best) { second = best; best = w; bj = (int)ri[t]; }
                else if (w > second) second = w;
            }
            if (second < -1e299) second = best - 1.0;
            row_choice[i] = bj;
            row_bid[i] = price[bj] + (best - second) + eps;
        }
    };

    for (;;) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assigned.begin(), assigned.end(), 0);
        nunassigned = n;
        // greedy seed
        for (int i = 0; i < n; ++i) {
            const double* rv = val + (size_t)i * k;
            const int64_t* ri = idx + (size_t)i * k;
            double best = -1e300; int bj = (int)ri[0];
            for (int t = 0; t < k; ++t) {
                double w = -rv[t] - price[ri[t]];
                if (w > best) { best = w; bj = (int)ri[t]; }
            }
            if (owner[bj] < 0) { owner[bj] = i; assigned[i] = 1; nunassigned--; }
        }
        int guard = 0, guardmax = n * 80;
        while (nunassigned > 0 && guard < guardmax) {
            guard++; total++;
            int chunk = (n + nthreads - 1) / nthreads;
            std::vector<std::thread> pool;
            for (int t = 0; t < nthreads; ++t) {
                int lo = t * chunk, hi = std::min(n, lo + chunk);
                if (lo >= n) break;
                pool.emplace_back(compute, lo, hi, eps);
            }
            for (auto& th : pool) th.join();
            // resolve bids serially
            std::fill(bid.begin(), bid.end(), -1e300);
            std::fill(bidder.begin(), bidder.end(), -1);
            bool progress = false;
            for (int i = 0; i < n; ++i) {
                int j = row_choice[i];
                if (j < 0) continue;
                if (row_bid[i] > bid[j]) { bid[j] = row_bid[i]; bidder[j] = i; }
            }
            for (int j = 0; j < n; ++j) {
                int i = bidder[j];
                if (i < 0) continue;
                progress = true;
                int prev = owner[j];
                if (prev >= 0 && prev != i) { assigned[prev] = 0; nunassigned++; }
                owner[j] = i;
                if (!assigned[i]) { assigned[i] = 1; nunassigned--; }
                price[j] = bid[j];
            }
            if (!progress) break;
        }
        if (nunassigned > 0) {
            for (int i = 0; i < n; ++i) rowsol[i] = -1;
            return {total, nunassigned};
        }
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps * factor, eps_final);
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
    return {total, 0};
}

static PyObject* py_auction(PyObject* self, PyObject* args) {
    PyObject *vo, *io; double eps, factor; int nthreads;
    if (!PyArg_ParseTuple(args, "OOddi", &vo, &io, &eps, &factor, &nthreads)) return NULL;
    PyArrayObject* val = (PyArrayObject*)PyArray_FROM_OTF(vo, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* idx = (PyArrayObject*)PyArray_FROM_OTF(io, NPY_INT64, NPY_ARRAY_IN_ARRAY | NPY_ARRAY_C_CONTIGUOUS);
