// Sparse shortest-augmenting-path refinement.
// Starts from a (possibly suboptimal) perfect matching and repairs it using only
// the candidate edges (idx/val, k per row) plus a dynamic set of extra edges
// passed in (extra_idx, extra_val: n x kx, -1 = absent).
// Returns the improved assignment and its cost.
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <cstring>
#include <Python.h>
#include <numpy/arrayobject.h>

static void repair(const double* val, const int64_t* idx, int n, int k,
                   const double* eval, const int64_t* eidx, int kx,
                   int64_t* rowsol, double* out_cost) {
    const double INF = 1e300;
    std::vector<double> v(n, 0.0), u(n, 0.0);
    std::vector<int64_t> colsol(n, -1);
    for (int i = 0; i < n; ++i) {
        int j = (int)rowsol[i];
        if (j >= 0 && colsol[j] < 0) colsol[j] = i;
    }
    for (int j = 0; j < n; ++j) if (colsol[j] >= 0) {
        int i = (int)colsol[j];
        // find cost of matched edge in candidate list
        double c = 0;
        bool found = false;
        for (int t = 0; t < k; ++t) if (idx[(size_t)i*k+t] == j) { c = val[(size_t)i*k+t]; found = true; break; }
        if (!found) for (int t = 0; t < kx; ++t) if (eidx[(size_t)i*kx+t] == j) { c = eval[(size_t)i*kx+t]; found = true; break; }
        v[j] = found ? c : 0.0;
    }

    auto row_best = [&](int i, double& best, double& second, int& bj) {
        best = INF; second = INF; bj = -1;
        for (int t = 0; t < k; ++t) {
            int j = (int)idx[(size_t)i*k+t];
            double r = val[(size_t)i*k+t] - v[j];
            if (r < best) { second = best; best = r; bj = j; }
            else if (r < second) second = r;
        }
        for (int t = 0; t < kx; ++t) {
            int j = (int)eidx[(size_t)i*kx+t];
            if (j < 0) continue;
            double r = eval[(size_t)i*kx+t] - v[j];
            if (r < best) { second = best; best = r; bj = j; }
            else if (r < second) second = r;
        }
    };

    // Repeatedly flip along negative cycles / reassign violating rows via
    // sparse Dijkstra augmenting paths, dropping the current match first.
    std::vector<double> dist(n);
    std::vector<int> parent(n), scanned(n);
    bool improved = true;
    int passes = 0;
    while (improved && passes < 30) {
        improved = false; passes++;
        for (int i0 = 0; i0 < n; ++i0) {
            int j0 = (int)rowsol[i0];
            double best, second; int bj;
            row_best(i0, best, second, bj);
            double matched_red = INF;
            if (j0 >= 0) {
                bool found=false;
                for (int t = 0; t < k; ++t) if (idx[(size_t)i0*k+t]==j0) { matched_red = val[(size_t)i0*k+t]-v[j0]; found=true; break; }
                if (!found) for (int t = 0; t < kx; ++t) if (eidx[(size_t)i0*kx+t]==j0) { matched_red = eval[(size_t)i0*kx+t]-v[j0]; found=true; break; }
            }
            if (matched_red <= best + 1e-12) continue; // locally optimal
            // row violates: unmatch and augment
            if (j0 >= 0) { colsol[j0] = -1; rowsol[i0] = -1; }
            std::fill(dist.begin(), dist.end(), INF);
            std::fill(parent.begin(), parent.end(), -1);
            std::fill(scanned.begin(), scanned.end(), 0);
            // seed distances from i0
            for (int t = 0; t < k; ++t) {
                int j = (int)idx[(size_t)i0*k+t];
                double r = val[(size_t)i0*k+t] - v[j];
                if (r < dist[j]) { dist[j] = r; parent[j] = i0; }
            }
            for (int t = 0; t < kx; ++t) {
                int j = (int)eidx[(size_t)i0*kx+t];
                if (j < 0) continue;
                double r = eval[(size_t)i0*kx+t] - v[j];
                if (r < dist[j]) { dist[j] = r; parent[j] = i0; }
            }
            int j_cur = -1; double best_d = INF;
            for (int step = 0; step < n; ++step) {
                best_d = INF; j_cur = -1;
                for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < best_d) { best_d = dist[j]; j_cur = j; }
                if (j_cur < 0) break;
                scanned[j_cur] = 1;
                int i_cur = (int)colsol[j_cur];
                if (i_cur < 0) break;
                double h = 0;
                bool found=false;
                for (int t = 0; t < k; ++t) if (idx[(size_t)i_cur*k+t]==j_cur) { h = val[(size_t)i_cur*k+t]-v[j_cur]-best_d; found=true; break; }
                if (!found) for (int t = 0; t < kx; ++t) if (eidx[(size_t)i_cur*kx+t]==j_cur) { h = eval[(size_t)i_cur*kx+t]-v[j_cur]-best_d; break; }
                auto relax = [&](int j, double cand) {
                    if (!scanned[j] && cand < dist[j]) { dist[j] = cand; parent[j] = i_cur; }
                };
                for (int t = 0; t < k; ++t) relax((int)idx[(size_t)i_cur*k+t], val[(size_t)i_cur*k+t]-v[idx[(size_t)i_cur*k+t]]-h);
                for (int t = 0; t < kx; ++t) { int j=(int)eidx[(size_t)i_cur*kx+t]; if (j>=0) relax(j, eval[(size_t)i_cur*kx+t]-v[j]-h); }
            }
            if (j_cur < 0) continue;
            for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - best_d;
            while (j_cur >= 0) {
                int i_pred = parent[j_cur];
                int j_prev = (i_pred == i0) ? -1 : (int)rowsol[i_pred];
                rowsol[i_pred] = j_cur;
                colsol[j_cur] = i_pred;
                j_cur = j_prev;
            }
            improved = true;
        }
    }
    double cost = 0;
    for (int i = 0; i < n; ++i) {
        int j = (int)rowsol[i];
        for (int t = 0; t < k; ++t) if (idx[(size_t)i*k+t]==j) { cost += val[(size_t)i*k+t]; break; }
    }
    *out_cost = cost;
}

static PyObject* py_repair(PyObject* self, PyObject* args) {
    PyObject *vo,*io,*evo,*eio,*co;
    if (!PyArg_ParseTuple(args, "OOOOO", &vo,&io,&evo,&eio,&co)) return NULL;
    PyArrayObject* val=(PyArrayObject*)PyArray_FROM_OTF(vo,NPY_FLOAT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* idx=(PyArrayObject*)PyArray_FROM_OTF(io,NPY_INT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* eval=(PyArrayObject*)PyArray_FROM_OTF(evo,NPY_FLOAT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* eidx=(PyArrayObject*)PyArray_FROM_OTF(eio,NPY_INT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* col=(PyArrayObject*)PyArray_FROM_OTF(co,NPY_INT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    if(!val||!idx||!eval||!eidx||!col) return NULL;
    int n=(int)PyArray_DIM(val,0), k=(int)PyArray_DIM(val,1), kx=(int)PyArray_DIM(eval,1);
    npy_intp dims[1]={n};
    PyObject* out=PyArray_SimpleNew(1,dims,NPY_INT64);
    std::memcpy(PyArray_DATA((PyArrayObject*)out), PyArray_DATA(col), n*sizeof(int64_t));
    double cost=0;
    repair((const double*)PyArray_DATA(val),(const int64_t*)PyArray_DATA(idx),n,k,
           (const double*)PyArray_DATA(eval),(const int64_t*)PyArray_DATA(eidx),kx,
           (int64_t*)PyArray_DATA((PyArrayObject*)out), &cost);
    Py_DECREF(val);Py_DECREF(idx);Py_DECREF(eval);Py_DECREF(eidx);Py_DECREF(col);
    return Py_BuildValue("Nd", out, cost);
}
