// Improve a perfect matching by flipping negative alternating cycles, using a
// candidate edge list (k per row) plus the full cost matrix for cycle evaluation.
// Strategy: for each matched edge, look for a negative 2-cycle or 3-cycle through
// candidate edges and flip the best one found. Repeat until no improvement.
#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <cstdint>
#include <vector>
#include <Python.h>
#include <numpy/arrayobject.h>

static void improve(const double* C, const int64_t* idx, int n, int k, int64_t* rowsol) {
    std::vector<int64_t> colsol(n);
    for (int i = 0; i < n; ++i) colsol[rowsol[i]] = i;
    auto cost = [&](int i, int j){ return C[(size_t)i*n+j]; };

    bool improved = true;
    int passes = 0;
    while (improved && passes < 50) {
        improved = false; passes++;
        for (int i1 = 0; i1 < n; ++i1) {
            int j1 = (int)rowsol[i1];
            double c11 = cost(i1, j1);
            // 2-cycles: candidate edge (i1, j2) where j2 is matched to i2
            for (int t = 0; t < k; ++t) {
                int j2 = (int)idx[(size_t)i1*k+t];
                if (j2 == j1) continue;
                int i2 = (int)colsol[j2];
                double delta = cost(i1, j2) + cost(i2, j1) - c11 - cost(i2, j2);
                if (delta < -1e-12) {
                    // flip
                    rowsol[i1] = j2; rowsol[i2] = j1;
                    colsol[j2] = i1; colsol[j1] = i2;
                    j1 = j2; c11 = cost(i1, j1);
                    improved = true;
                }
            }
            // 3-cycles: (i1,j2),(i2,j3),(i3,j1)
            j1 = (int)rowsol[i1]; c11 = cost(i1, j1);
            for (int t = 0; t < k; ++t) {
                int j2 = (int)idx[(size_t)i1*k+t];
                if (j2 == j1) continue;
                int i2 = (int)colsol[j2];
                double base = cost(i1, j2) - c11 - cost(i2, j2);
                for (int s = 0; s < k; ++s) {
                    int j3 = (int)idx[(size_t)i2*k+s];
                    if (j3 == j2 || j3 == j1) continue;
                    int i3 = (int)colsol[j3];
                    if (i3 == i1 || i3 == i2) continue;
                    double delta = base + cost(i2, j3) + cost(i3, j1) - cost(i3, j3);
                    if (delta < -1e-12) {
                        rowsol[i1]=j2; rowsol[i2]=j3; rowsol[i3]=j1;
                        colsol[j2]=i1; colsol[j3]=i2; colsol[j1]=i3;
                        improved = true;
                        goto next_row;
                    }
                }
            }
            next_row: ;
        }
    }
}

static PyObject* py_improve(PyObject* self, PyObject* args) {
    PyObject *mo,*io,*co;
    if (!PyArg_ParseTuple(args, "OOO", &mo,&io,&co)) return NULL;
    PyArrayObject* M=(PyArrayObject*)PyArray_FROM_OTF(mo,NPY_FLOAT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* idx=(PyArrayObject*)PyArray_FROM_OTF(io,NPY_INT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    PyArrayObject* col=(PyArrayObject*)PyArray_FROM_OTF(co,NPY_INT64,NPY_ARRAY_IN_ARRAY|NPY_ARRAY_C_CONTIGUOUS);
    if(!M||!idx||!col) return NULL;
    int n=(int)PyArray_DIM(M,0), k=(int)PyArray_DIM(idx,1);
    npy_intp dims[1]={n};
    PyObject* out=PyArray_SimpleNew(1,dims,NPY_INT64);
    std::memcpy(PyArray_DATA((PyArrayObject*)out), PyArray_DATA(col), n*sizeof(int64_t));
    improve((const double*)PyArray_DATA(M),(const int64_t*)PyArray_DATA(idx),n,k,(int64_t*)PyArray_DATA((PyArrayObject*)out));
    Py_DECREF(M);Py_DECREF(idx);Py_DECREF(col);
