    __m128i S2 = _mm_set1_epi32(0x3c6ef372);
    __m128i S3 = _mm_set1_epi32(0xa54ff53a);
    __m128i S4 = _mm_set1_epi32(0x510e527f);
    __m128i S5 = _mm_set1_epi32(0x9b05688c);
    __m128i S6 = _mm_set1_epi32(0x1f83d9ab);
    __m128i S7 = _mm_set1_epi32(0x5be0cd19);

    for (size_t b = 0; b < blocks; b++) {
        __m128i W[64];
        for (int i = 0; i < 16; i++) {
            auto ld = [&](const uint8_t *in) {
                const uint8_t *p = in + b*64 + i*4;
                return (int)(((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]);
            };
            W[i] = _mm_set_epi32(ld(in3), ld(in2), ld(in1), ld(in0));
