            h=g; g=f; f=e; e=Add(d,t1); d=c; c=b_; b_=a; a=Add(t1,t2);
        }
        S0=Add(S0,a); S1=Add(S1,b_); S2=Add(S2,c); S3=Add(S3,d);
        S4=Add(S4,e); S5=Add(S5,f); S6=Add(S6,g); S7=Add(S7,h);
