    unsigned char o[32];
    t0 = now();
    for (int i = 0; i < reps; i++) CC_SHA256(buf, (CC_LONG)total, o);
    dt = now()-t0;
    printf("CC 1-way: %.2f ms (%.1f MB/s)\n", dt/reps*1000, total*reps/dt/1e6);
    return 0;
}
