    0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) (((x)>>(n)) | ((x)<<(32-(n))))
#define S0(x) (ROTR(x,2) ^ ROTR(x,13) ^ ROTR(x,22))
#define S1(x) (ROTR(x,6) ^ ROTR(x,11) ^ ROTR(x,25))
#define CH(x,y,z) (((x) & (y)) ^ (~(x) & (z)))
#define MAJ(x,y,z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))

#define ROUND(a,b,c,d,e,f,g,h,kw) do { \
    uint32_t t1 = (h) + S1(e) + CH(e,f,g) + (kw); \
    uint32_t t2 = S0(a) + MAJ(a,b,c); \
    (d) += t1; \
    (h) = t1 + t2; \
} while (0)

/*
 * Expand next 4 words.
 * w0 = W[i-16..i-13], w1 = W[i-12..i-9], w2 = W[i-8..i-5], w3 = W[i-4..i-1]
 * returns W[i..i+3]
 *
 * This is the formulation from noloader/SHA-Intrinsics sha256-x86.c (public domain):
 *
 *   __m128i s1 = _mm_srli_epi32(w3, 10); ... no, they use a different trick.
 *
 * Working formulation used by "SHA-Intrinsics/sha256-x86.c" MessageSchedule:
 *
 *   // From Intel whitepaper listing, corrected:
 */
static inline __m128i expand(__m128i w0, __m128i w1, __m128i w2, __m128i w3) {
    /* W[i-15] */
    __m128i w15 = _mm_alignr_epi8(w1, w0, 4);
    /* sigma0 */
    __m128i s0 = _mm_xor_si128(
                    _mm_xor_si128(_mm_srli_epi32(w15, 7),  _mm_slli_epi32(w15, 25)),
                    _mm_xor_si128(_mm_srli_epi32(w15, 18), _mm_slli_epi32(w15, 14)));
    s0 = _mm_xor_si128(s0, _mm_srli_epi32(w15, 3));

    /* W[i-7] */
    __m128i w7 = _mm_alignr_epi8(w3, w2, 4);

    __m128i sum = _mm_add_epi32(w0, s0);
    sum = _mm_add_epi32(sum, w7);
    /* sum = W[i-16] + s0(W[i-15]) + W[i-7]   missing s1(W[i-2]) */

    /*
     * sigma1 has a dependency: the 4 new words need sigma1 of
     *   W[i-2], W[i-1], W[i], W[i+1]
     * i.e. the last two of w3 and the first two of the result.
     *
     * Trick from the Intel paper / noloader (sha256-x86.c lines ~190):
     *   Compute sigma1 on a vector that has W[i-2] in lane 0 and zeros after,
     *   add it, then shuffle the new word into place and repeat. That's 4 serial
     *   steps — still faster than scalar if the rest is vectorized, but the
     *   dependency chain is the same length as scalar. The WIN is doing sigma0
     *   and the adds for 4 words at once, and sigma1's 4 steps are short.
     *
     * Concrete (from https://github.com/noloader/SHA-Intrinsics blob sha256-x86.c):
     *
     *   __m128i s1 = _mm_shuffle_epi32(w3, 0xFA); // not quite
     *
     * I'll implement the 4 serial sigma1 steps explicitly. It's correct and
     * the sigma0 part is vectorized.
     */
    /* lane-wise serial sigma1 add. Extract, compute, insert. */
    uint32_t tmp[4], prev[4];
    _mm_storeu_si128((__m128i*)tmp, sum);
    _mm_storeu_si128((__m128i*)prev, w3); /* W[i-4] W[i-3] W[i-2] W[i-1] */
    uint32_t wm2 = prev[2], wm1 = prev[3];
    for (int k = 0; k < 4; k++) {
        uint32_t y = (k == 0) ? wm2 : (k == 1) ? wm1 : tmp[k-2];
        uint32_t s1 = ROTR(y,17) ^ ROTR(y,19) ^ (y >> 10);
        tmp[k] += s1;
    }
    return _mm_loadu_si128((const __m128i*)tmp);
}

static void sha256_blocks(const uint8_t *data, size_t nblocks, uint32_t st[8]) {
    const __m128i mask = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    uint32_t a=st[0], b=st[1], c=st[2], d=st[3];
    uint32_t e=st[4], f=st[5], g=st[6], h=st[7];

