        R(32);R(33);R(34);R(35);R(36);R(37);R(38);R(39);
        R(40);R(41);R(42);R(43);R(44);R(45);R(46);R(47);
        R(48);R(49);R(50);R(51);R(52);R(53);R(54);R(55);
        R(56);R(57);R(58);R(59);R(60);R(61);R(62);R(63);
#undef R
        a+=A; b+=B; c+=C; d+=D; e+=E; f+=F; g+=G; h+=H;
    }
    st[0]=a; st[1]=b; st[2]=c; st[3]=d; st[4]=e; st[5]=f; st[6]=g; st[7]=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len / 64;
    sha256_blocks(data, nblocks, st);
    size_t rem = len % 64;
    uint8_t tail[128];
    memset(tail, 0, sizeof tail);
    memcpy(tail, data + nblocks*64, rem);
    tail[rem] = 0x80;
    size_t padblocks = (rem < 56) ? 1 : 2;
    uint64_t bits = (uint64_t)len * 8;
    tail[padblocks*64 - 8] = bits >> 56;
    tail[padblocks*64 - 7] = bits >> 48;
    tail[padblocks*64 - 6] = bits >> 40;
    tail[padblocks*64 - 5] = bits >> 32;
    tail[padblocks*64 - 4] = bits >> 24;
    tail[padblocks*64 - 3] = bits >> 16;
    tail[padblocks*64 - 2] = bits >> 8;
    tail[padblocks*64 - 1] = bits;
    sha256_blocks(tail, padblocks, st);
    for (int i = 0; i < 8; i++) {
        out[4*i]   = st[i] >> 24;
        out[4*i+1] = st[i] >> 16;
        out[4*i+2] = st[i] >> 8;
        out[4*i+3] = st[i];
