/*
 * 1-way SHA-256, SSSE3 schedule kept in XMM, scalar rounds.
 * Correctness of expand() already verified. This version avoids storing
 * the whole schedule before the rounds: each group of 4 words is expanded
 * and immediately consumed (software-pipelined with the previous group's rounds
 * only loosely — we still expand-then-round per group to cut memory traffic).
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <CommonCrypto/CommonDigest.h>

static const uint32_t K[64] __attribute__((aligned(16))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,
    0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,
    0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,
    0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,
    0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,
    0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,
    0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,
    0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,
    0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) (((x)>>(n)) | ((x)<<(32-(n))))
#define S0(x) (ROTR(x,2) ^ ROTR(x,13) ^ ROTR(x,22))
#define S1(x) (ROTR(x,6) ^ ROTR(x,11) ^ ROTR(x,25))
#define CH(x,y,z) (((x) & (y)) ^ (~(x) & (z)))
#define MAJ(x,y,z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))

/* Fully vectorized expand. sigma1 dependency resolved with shuffles,
   no scalar extract. Based on the standard formulation:

   After computing base = W[i-16]+s0(W[i-15])+W[i-7], we need to add
   s1(W[i-2]), s1(W[i-1]), s1(W[i]), s1(W[i+1]).

   Step used by many implementations (including the one in
   https://github.com/noloader/SHA-Intrinsics/blob/master/sha256-x86.c):

     __m128i s1 = _mm_shuffle_epi32(w3, 0xFA); // W[i-2] in low? let's just test empirically
*/
static inline __m128i sigma1_vec(__m128i x) {
    return _mm_xor_si128(
        _mm_xor_si128(_mm_or_si128(_mm_srli_epi32(x,17), _mm_slli_epi32(x,15)),
                      _mm_or_si128(_mm_srli_epi32(x,19), _mm_slli_epi32(x,13))),
        _mm_srli_epi32(x, 10));
}
static inline __m128i sigma0_vec(__m128i x) {
    return _mm_xor_si128(
        _mm_xor_si128(_mm_or_si128(_mm_srli_epi32(x,7), _mm_slli_epi32(x,25)),
                      _mm_or_si128(_mm_srli_epi32(x,18), _mm_slli_epi32(x,14))),
        _mm_srli_epi32(x, 3));
}

/*
 * Correct vector expand, no scalar loop.
 * Derived by unrolling the 4 dependent sigma1 additions with shuffles.
 *
 * Let prev = w3 = [W-4, W-3, W-2, W-1]
 * base = [b0, b1, b2, b3] = W-16+s0(W-15)+W-7
 *
 * W0 = b0 + s1(W-2)
 * W1 = b1 + s1(W-1)
 * W2 = b2 + s1(W0)
 * W3 = b3 + s1(W1)
 *
 * So first two are independent of the result; last two depend on first two.
 */
static inline __m128i expand4(__m128i w0, __m128i w1, __m128i w2, __m128i w3) {
    __m128i w15 = _mm_alignr_epi8(w1, w0, 4);
    __m128i w7  = _mm_alignr_epi8(w3, w2, 4);
    __m128i base = _mm_add_epi32(w0, sigma0_vec(w15));
    base = _mm_add_epi32(base, w7);

    /* s1 of [W-2, W-1, ?, ?] = shuffle w3: lanes 2,3,2,3 */
    __m128i prev = _mm_shuffle_epi32(w3, 0xFA); /* 3,3,2,2? 0xFA = 11 11 10 10 = lanes 3,3,2,2 */
    /* We need lanes [2,3,x,x] in positions [0,1,2,3].
       _mm_shuffle_epi32 imm: dest lane i = src lane bits(2*i+1, 2*i)
       We want dest0=src2, dest1=src3. imm bits: 00->2 (10), 01->3 (11) => low byte 0b1110 = 0xE
       High doesn't matter yet. Use 0x0E? shuffle is 8-bit: ddccbbaa where each is 2 bits.
       dest0=2, dest1=3, dest2=0, dest3=0 => 00 00 11 10 = 0x0E. */
    __m128i s1src = _mm_shuffle_epi32(w3, 0x0E); /* [W-2, W-1, W-4, W-4] */
    __m128i s1 = sigma1_vec(s1src);
    /* add s1 lanes 0,1 only. Zero lanes 2,3 of s1. */
    __m128i mask01 = _mm_set_epi32(0, 0, -1, -1);
    s1 = _mm_and_si128(s1, mask01);
    __m128i r = _mm_add_epi32(base, s1); /* [W0, W1, b2, b3] */

    /* W2 = b2 + s1(W0). W0 is lane 0 of r. */
    __m128i w0only = _mm_shuffle_epi32(r, 0x00); /* broadcast lane 0? 0x00 = 00 00 00 00 = lane0 x4 */
    __m128i s1w0 = sigma1_vec(w0only);
    /* add into lane 2 only */
    __m128i add2 = _mm_and_si128(s1w0, _mm_set_epi32(0, -1, 0, 0));
    r = _mm_add_epi32(r, add2);

    /* W3 = b3 + s1(W1). W1 is lane 1 of r. */
    __m128i w1only = _mm_shuffle_epi32(r, 0x55); /* 01 01 01 01 = lane1 x4 */
    __m128i s1w1 = sigma1_vec(w1only);
    __m128i add3 = _mm_and_si128(s1w1, _mm_set_epi32(-1, 0, 0, 0));
    r = _mm_add_epi32(r, add3);
    return r;
}

#define R4(A,B,C,D,E,F,G,H, kw) do { \
    uint32_t _k0 = _mm_cvtsi128_si32(kw); \
    uint32_t _k1 = _mm_extract_epi32(kw, 1); \
    uint32_t _k2 = _mm_extract_epi32(kw, 2); \
    uint32_t _k3 = _mm_extract_epi32(kw, 3); \
    uint32_t t1, t2; \
    t1 = H + S1(E) + CH(E,F,G) + _k0; t2 = S0(A) + MAJ(A,B,C); H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+t2; \
    t1 = H + S1(E) + CH(E,F,G) + _k1; t2 = S0(A) + MAJ(A,B,C); H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+t2; \
    t1 = H + S1(E) + CH(E,F,G) + _k2; t2 = S0(A) + MAJ(A,B,C); H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+t2; \
    t1 = H + S1(E) + CH(E,F,G) + _k3; t2 = S0(A) + MAJ(A,B,C); H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+t2; \
} while(0)

static void sha256_blocks(const uint8_t *data, size_t nblocks, uint32_t st[8]) {
    const __m128i bswap = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];

    for (size_t blk = 0; blk < nblocks; blk++) {
        const uint8_t *p = data + blk*64;
        __m128i w0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+0)),  bswap);
        __m128i w1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+16)), bswap);
        __m128i w2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+32)), bswap);
        __m128i w3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+48)), bswap);

        uint32_t A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;

        __m128i kw = _mm_add_epi32(w0, _mm_loadu_si128((const __m128i*)(K+0)));
        R4(A,B,C,D,E,F,G,H, kw);
        kw = _mm_add_epi32(w1, _mm_loadu_si128((const __m128i*)(K+4)));
        R4(A,B,C,D,E,F,G,H, kw);
        kw = _mm_add_epi32(w2, _mm_loadu_si128((const __m128i*)(K+8)));
        R4(A,B,C,D,E,F,G,H, kw);
        kw = _mm_add_epi32(w3, _mm_loadu_si128((const __m128i*)(K+12)));
        R4(A,B,C,D,E,F,G,H, kw);

        for (int i = 4; i < 16; i++) {
            __m128i wn = expand4(w0, w1, w2, w3);
            w0=w1; w1=w2; w2=w3; w3=wn;
            kw = _mm_add_epi32(wn, _mm_loadu_si128((const __m128i*)(K+i*4)));
            R4(A,B,C,D,E,F,G,H, kw);
        }
        a+=A; b+=B; c+=C; d+=D; e+=E; f+=F; g+=G; h+=H;
    }
    st[0]=a;st[1]=b;st[2]=c;st[3]=d;st[4]=e;st[5]=f;st[6]=g;st[7]=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len / 64;
    if (nblocks) sha256_blocks(data, nblocks, st);
    size_t rem = len % 64;
    uint8_t tail[128];
    memset(tail, 0, sizeof tail);
    if (rem) memcpy(tail, data + nblocks*64, rem);
    tail[rem] = 0x80;
    size_t padblocks = (rem < 56) ? 1 : 2;
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) tail[padblocks*64 - 1 - i] = (uint8_t)(bits >> (8*i));
    sha256_blocks(tail, padblocks, st);
    for (int i = 0; i < 8; i++) {
        out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i];
    }
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }

int main() {
    const char *msgs[] = {"", "abc", "hello", "The quick brown fox jumps over the lazy dog"};
    for (int i = 0; i < 4; i++) {
        uint8_t a[32], b[32];
        sha256((const uint8_t*)msgs[i], strlen(msgs[i]), a);
        CC_SHA256((const uint8_t*)msgs[i], (CC_LONG)strlen(msgs[i]), b);
        if (memcmp(a,b,32)) {
