    }
    printf("correct\n");

    size_t n = 20000UL*1024;
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0x5a, n);
    uint8_t out[32], ref[32];
    sha256(data, n, out);
    CC_SHA256(data, (CC_LONG)n, ref);
    printf("20MB %s\n", memcmp(out,ref,32)==0?"OK":"FAIL");
