    t0=now();
    for(int i=0;i<reps;i++) CC_SHA256(data,(CC_LONG)n,ref);
    dt=now()-t0;
    printf("CC:   %.2f ms (%.1f MB/s)\n", dt/reps*1000, n*reps/dt/1e6);
