static inline uint32_t ror(uint32_t x, int n) {
    uint32_t r;
    /* BMI2 rorx */
    if (n==2)  asm("rorxl $2, %1, %0" : "=r"(r) : "r"(x));
    else if (n==6) asm("rorxl $6, %1, %0" : "=r"(r) : "r"(x));
    else if (n==7) asm("rorxl $7, %1, %0" : "=r"(r) : "r"(x));
    else if (n==11) asm("rorxl $11, %1, %0" : "=r"(r) : "r"(x));
    else if (n==13) asm("rorxl $13, %1, %0" : "=r"(r) : "r"(x));
    else if (n==17) asm("rorxl $17, %1, %0" : "=r"(r) : "r"(x));
    else if (n==18) asm("rorxl $18, %1, %0" : "=r"(r) : "r"(x));
    else if (n==19) asm("rorxl $19, %1, %0" : "=r"(r) : "r"(x));
    else if (n==22) asm("rorxl $22, %1, %0" : "=r"(r) : "r"(x));
    else if (n==25) asm("rorxl $25, %1, %0" : "=r"(r) : "r"(x));
    else r = (x>>n)|(x<<(32-n));
    return r;
}

__attribute__((noinline))
static void sha_rorx(const uint8_t * __restrict data, size_t nblocks, uint32_t st[8]) {
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for (size_t blk=0; blk<nblocks; blk++) {
        const uint8_t *p = data + blk*64;
        uint32_t w[64];
        for (int i=0;i<16;i++) {
            uint32_t v;
            memcpy(&v, p+4*i, 4);
            w[i] = __builtin_bswap32(v);
        }
        for (int i=16;i<64;i++) {
            uint32_t x=w[i-15], y=w[i-2];
            uint32_t s0 = ror(x,7) ^ ror(x,18) ^ (x>>3);
            uint32_t s1 = ror(y,17) ^ ror(y,19) ^ (y>>10);
            w[i] = w[i-16] + s0 + w[i-7] + s1;
        }
        uint32_t A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;
        for (int i=0;i<64;i++) {
            uint32_t S1 = ror(E,6) ^ ror(E,11) ^ ror(E,25);
            uint32_t ch = (E & F) ^ (~E & G);
            uint32_t t1 = H + S1 + ch + K[i] + w[i];
            uint32_t S0 = ror(A,2) ^ ror(A,13) ^ ror(A,22);
            uint32_t maj = (A & B) ^ (A & C) ^ (B & C);
            H=G; G=F; F=E; E=D+t1; D=C; C=B; B=A; A=t1+S0+maj;
        }
        a+=A; b+=B; c+=C; d+=D; e+=E; f+=F; g+=G; h+=H;
    }
    st[0]=a;st[1]=b;st[2]=c;st[3]=d;st[4]=e;st[5]=f;st[6]=g;st[7]=h;
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }

