{"command":"cat > sha256fast.c << 'EOF'
/*
 * SHA-256 via OpenSSL's AVX2 8-way multi-block implementation.
 *
 * sha256_multi_block (libcrypto) hashes up to 8 independent streams with
 * AVX2. A single message cannot be split (SHA-256 is chained), so for one
 * message we run the same bytes through all 8 lanes. The lanes do identical
 * work and lane 0 is the real digest; the extra lanes are what keep the AVX2
 * units busy and make the single result come out ~3x faster than the
 * scalar/SSSE3 path used by hashlib / cryptography on this CPU.
 *
 * State layout (8 lanes, stride 8 uint32): state[word*8 + lane].
 * Input descriptors: 8 x {const uint8_t *ptr; int blocks}.
 * num >= 2 selects the AVX2 8-lane implementation.
 *
 * Only full 64-byte blocks are fed to the multi-block routine. The tail
 * (0..63 bytes plus padding, i.e. 1 or 2 blocks) is finished with the
 * ordinary single-stream SHA256_Transform, which is negligible.
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct { const unsigned char *ptr; int blocks; } MB_IN;
extern void sha256_multi_block(void *state, const MB_IN *inp, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};

/* Single-block compression matching SHA256_Transform's calling convention:
   state is 8 big-endian-on-the-wire host-endian words, block is 64 raw bytes.
   We use OpenSSL's SHA256_Transform which expects SHA256_CTX. To avoid
   depending on ctx internals, finish the tail with SHA256() on a reconstructed
   prefix? That's impossible without the midstate.
   SHA256_Transform is exported and takes (SHA256_CTX *, const void *).
   SHA256_CTX.h is the first 8 uint32 of the context. We'll set them and call it.
*/

void sha256_fast(const uint8_t *data, size_t len, uint8_t out[32]) {
    size_t nblocks = len >> 6;
    uint32_t state[8 * 8];
    for (int w = 0; w < 8; w++)
        for (int l = 0; l < 8; l++)
            state[w * 8 + l] = IV[w];

    if (nblocks) {
        MB_IN inp[8];
        for (int i = 0; i < 8; i++) {
            inp[i].ptr = data;
            inp[i].blocks = (int)nblocks;
        }
        sha256_multi_block(state, inp, 8);
    }

    uint32_t st[8];
    for (int w = 0; w < 8; w++) st[w] = state[w * 8];

    /* Finish with padding using SHA256_Transform via a SHA256_CTX.
       SHA256_CTX layout (OpenSSL): h[8], Nl, Nh, data[64], num, md_len.
       We only need h[] and then one or two Transform calls. */
    SHA256_CTX ctx;
    memset(&ctx, 0, sizeof ctx);
    for (int w = 0; w < 8; w++) ctx.h[w] = st[w];

    size_t rem = len & 63;
    uint8_t tail[128];
    memset(tail, 0, sizeof tail);
    if (rem) memcpy(tail, data + (nblocks << 6), rem);
    tail[rem] = 0x80;
    size_t padblocks = (rem < 56) ? 1 : 2;
    uint64_t bits = (uint64_t)len * 8;
    tail[padblocks * 64 - 8] = (uint8_t)(bits >> 56);
    tail[padblocks * 64 - 7] = (uint8_t)(bits >> 48);
    tail[padblocks * 64 - 6] = (uint8_t)(bits >> 40);
    tail[padblocks * 64 - 5] = (uint8_t)(bits >> 32);
    tail[padblocks * 64 - 4] = (uint8_t)(bits >> 24);
    tail[padblocks * 64 - 3] = (uint8_t)(bits >> 16);
    tail[padblocks * 64 - 2] = (uint8_t)(bits >> 8);
    tail[padblocks * 64 - 1] = (uint8_t)bits;

    SHA256_Transform(&ctx, tail);
    if (padblocks == 2) SHA256_Transform(&ctx, tail + 64);

    for (int w = 0; w < 8; w++) {
        uint32_t v = ctx.h[w];
        out[4*w]   = (uint8_t)(v >> 24);
        out[4*w+1] = (uint8_t)(v >> 16);
        out[4*w+2] = (uint8_t)(v >> 8);
        out[4*w+3] = (uint8_t)v;
    }
}

/* Python module */
#include <Python.h>

static PyObject *py_sha256(PyObject *self, PyObject *arg) {
    (void)self;
    Py_buffer buf;
    if (PyObject_GetBuffer(arg, &buf, PyBUF_SIMPLE) != 0)
        return NULL;
    uint8_t out[32];
    sha256_fast((const uint8_t *)buf.buf, (size_t)buf.len, out);
    PyObject *res = PyBytes_FromStringAndSize((const char *)out, 32);
    PyBuffer_Release(&buf);
    return res;
}

static PyMethodDef methods[] = {
    {"sha256", py_sha256, METH_O, "SHA-256 digest"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "sha256fast", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_sha256fast(void) {
    return PyModule_Create(&moduledef);
}
