#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

typedef struct { const unsigned char *ptr; int blocks; } MB_IN;
extern void sha256_multi_block(void *state, const MB_IN *inp, int num);

/* Run one block on a custom IV, return new state (lane 0). */
static void compress(const uint32_t iv[8], const uint8_t block[64], uint32_t out[8]) {
    uint32_t state[64];
    memset(state, 0, sizeof state);
    for (int w = 0; w < 8; w++)
        for (int l = 0; l < 8; l++)
            state[w*8 + l] = iv[w];
    MB_IN inp[8];
    for (int i = 0; i < 8; i++) { inp[i].ptr = block; inp[i].blocks = 1; }
    sha256_multi_block(state, inp, 8);
    for (int w = 0; w < 8; w++) out[w] = state[w*8];
}

static void xor8(uint32_t *d, const uint32_t *a, const uint32_t *b) {
    for (int i = 0; i < 8; i++) d[i] = a[i] ^ b[i];
}
static int eq8(const uint32_t *a, const uint32_t *b) {
    return memcmp(a, b, 32) == 0;
}

int main() {
    uint8_t block[64];
    for (int i = 0; i < 64; i++) block[i] = (uint8_t)(i*3+7);
    uint32_t zero[8] = {0};
    uint32_t h1[8], h2[8], h3[8];
    for (int i = 0; i < 8; i++) {
        h1[i] = 0x11111111u * (i+1);
        h2[i] = 0x01010101u * (i+3);
        h3[i] = h1[i] ^ h2[i];
    }
    uint32_t c0[8], c1[8], c2[8], c3[8], sum[8], tmp[8];
    compress(zero, block, c0);
    compress(h1, block, c1);
    compress(h2, block, c2);
    compress(h3, block, c3);
    /* linearity: C(h1)+C(h2)+C(0) == C(h1 xor h2)   if affine through origin-adjusted */
    xor8(sum, c1, c2);
    xor8(sum, sum, c0);
    printf("affine over GF2? %s\n", eq8(sum, c3) ? "YES" : "NO");

    /* Also test integer-add affinity? C(h1+h2) == C(h1)+C(h2)-C(0) ? extremely unlikely */
    uint32_t hs[8], cs[8];
    for (int i = 0; i < 8; i++) hs[i] = h1[i] + h2[i];
    compress(hs, block, cs);
    int add_aff = 1;
    for (int i = 0; i < 8; i++) {
        uint32_t pred = c1[i] + c2[i] - c0[i];
        if (pred != cs[i]) add_aff = 0;
    }
    printf("affine over integer add? %s\n", add_aff ? "YES" : "NO");

    /* print a couple values */
    printf("C0 %08x C1 %08x C2 %08x C3 %08x sum %08x\n", c0[0], c1[0], c2[0], c3[0], sum[0]);
    return 0;
}
