/*
 * Length-extension experiment.
 *
 * SHA-256(M) for |M| = n*64 bytes (full blocks, no padding yet) equals the
 * chaining value after n blocks. If we split M into two halves of n/2 blocks:
 *   H1 = Compress*(IV, M_left)
 *   H2 = Compress*(H1, M_right)
 * then H2 is the midstate. Computing H1 and a "from zero" compression of
 * M_right in parallel does NOT give H2, unless compression is affine — we
 * already showed it isn't.
 *
 * This file instead times the ONLY correct parallel scheme I can think of
 * that still yields SHA-256: nothing. It just double checks by computing
 * SHA256 of a message two ways.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <openssl/sha.h>
int main(){
    unsigned char d[128];
    memset(d, 0xab, sizeof d);
    unsigned char a[32], b[32];
    SHA256(d, sizeof d, a);
    SHA256_CTX c;
    SHA256_Init(&c);
    SHA256_Update(&c, d, 64);
    SHA256_Update(&c, d+64, 64);
    SHA256_Final(b, &c);
    printf("%d\n", memcmp(a,b,32)==0);
    return 0;
}
