    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline __m256i rotr(__m256i x, int n){
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}
static inline __m256i S0(__m256i x){ return _mm256_xor_si256(rotr(x,2), _mm256_xor_si256(rotr(x,13), rotr(x,22))); }
static inline __m256i S1(__m256i x){ return _mm256_xor_si256(rotr(x,6), _mm256_xor_si256(rotr(x,11), rotr(x,25))); }
static inline __m256i s0(__m256i x){ return _mm256_xor_si256(rotr(x,7), _mm256_xor_si256(rotr(x,18), _mm256_srli_epi32(x,3))); }
static inline __m256i s1(__m256i x){ return _mm256_xor_si256(rotr(x,17), _mm256_xor_si256(rotr(x,19), _mm256_srli_epi32(x,10))); }
static inline __m256i Ch(__m256i x,__m256i y,__m256i z){ return _mm256_xor_si256(_mm256_and_si256(x,y), _mm256_andnot_si256(x,z)); }
static inline __m256i Maj(__m256i x,__m256i y,__m256i z){
    return _mm256_xor_si256(_mm256_and_si256(x,y), _mm256_and_si256(_mm256_or_si256(x,y), z));
}

/* messages: 8 pointers, each 'blocks' * 64 bytes. */
static void sha256_8way(const uint8_t *m[8], int blocks, uint32_t out[8][8]) {
    __m256i A=_mm256_set1_epi32(0x6a09e667);
    __m256i B=_mm256_set1_epi32(0xbb67ae85);
    __m256i C=_mm256_set1_epi32(0x3c6ef372);
    __m256i D=_mm256_set1_epi32(0xa54ff53a);
    __m256i E=_mm256_set1_epi32(0x510e527f);
    __m256i F=_mm256_set1_epi32(0x9b05688c);
    __m256i G=_mm256_set1_epi32(0x1f83d9ab);
    __m256i H=_mm256_set1_epi32(0x5be0cd19);

    for (int b = 0; b < blocks; b++) {
        __m256i W[64];
        for (int i = 0; i < 16; i++) {
            uint32_t w[8];
            for (int lane = 0; lane < 8; lane++) {
                const uint8_t *p = m[lane] + (size_t)b*64 + i*4;
                w[lane] = ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];
            }
            W[i] = _mm256_set_epi32(w[7],w[6],w[5],w[4],w[3],w[2],w[1],w[0]);
        }
        for (int i = 16; i < 64; i++)
            W[i] = _mm256_add_epi32(_mm256_add_epi32(W[i-16], s0(W[i-15])),
                                    _mm256_add_epi32(W[i-7], s1(W[i-2])));
        __m256i a=A,b_=B,c=C,d=D,e=E,f=F,g=G,h=H;
        for (int i = 0; i < 64; i++) {
            __m256i t1 = _mm256_add_epi32(h, S1(e));
            t1 = _mm256_add_epi32(t1, Ch(e,f,g));
            t1 = _mm256_add_epi32(t1, _mm256_set1_epi32(K[i]));
            t1 = _mm256_add_epi32(t1, W[i]);
            __m256i t2 = _mm256_add_epi32(S0(a), Maj(a,b_,c));
            h=g; g=f; f=e; e=_mm256_add_epi32(d,t1); d=c; c=b_; b_=a; a=_mm256_add_epi32(t1,t2);
        }
        A=_mm256_add_epi32(A,a); B=_mm256_add_epi32(B,b_); C=_mm256_add_epi32(C,c); D=_mm256_add_epi32(D,d);
        E=_mm256_add_epi32(E,e); F=_mm256_add_epi32(F,f); G=_mm256_add_epi32(G,g); H=_mm256_add_epi32(H,h);
    }
    uint32_t tmp[8];
    _mm256_storeu_si256((__m256i*)tmp, A); for(int i=0;i<8;i++) out[i][0]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, B); for(int i=0;i<8;i++) out[i][1]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, C); for(int i=0;i<8;i++) out[i][2]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, D); for(int i=0;i<8;i++) out[i][3]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, E); for(int i=0;i<8;i++) out[i][4]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, F); for(int i=0;i<8;i++) out[i][5]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, G); for(int i=0;i<8;i++) out[i][6]=tmp[i];
    _mm256_storeu_si256((__m256i*)tmp, H); for(int i=0;i<8;i++) out[i][7]=tmp[i];
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }

int main(){
    size_t total = (20000UL*1024/512)*512;
    size_t each = total/8;
    int blocks = (int)(each/64);
    uint8_t *buf = aligned_alloc(64, total);
    memset(buf, 0x5a, total);
    const uint8_t *m[8];
    for (int i=0;i<8;i++) m[i]=buf+i*each;
    uint32_t out[8][8];
    sha256_8way(m, 2, out); /* warmup small */
    int reps=3;
    double t0=now();
    for(int r=0;r<reps;r++) sha256_8way(m, blocks, out);
    double dt=now()-t0;
    printf("hand 8-way: %.2f ms (%.1f MB/s)\n", dt/reps*1000, total*(double)reps/dt/1e6);
    return 0;
}
