                H[l]=G[l]; G[l]=F[l]; F[l]=E[l]; E[l]=D[l]+t1; D[l]=C[l]; C[l]=B[l]; B[l]=A[l]; A[l]=t1+t2;
            }
        }
        for (int l=0;l<4;l++){ a[l]+=A[l];b[l]+=B[l];c[l]+=C[l];d[l]+=D[l];e[l]+=E[l];f[l]+=F[l];g[l]+=G[l];h[l]+=H[l]; }
    }
    for (int l=0;l<4;l++){ st[l][0]=a[l];st[l][1]=b[l];st[l][2]=c[l];st[l][3]=d[l];st[l][4]=e[l];st[l][5]=f[l];st[l][6]=g[l];st[l][7]=h[l]; }
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }

int main(){
