#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
/* Measure the raw add-chain latency that SHA-256's round depends on.
   A round is approximately: 
     t1 = h + S1(e) + Ch + K + w     (S1 is 3 rotates + 2 xor, parallel with the adds somewhat)
     e' = d + t1
   The longest dependency is roughly 6 dependent ops. If we can do a synthetic
   chain of 6 dependent adds per "round" and time 64*nblocks of them, that is a
   lower bound on one SHA-256 chain. */
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }
int main(){
    size_t nblocks = (20000UL*1024)/64; /* 312500 */
    uint32_t a=1,b=2,c=3,d=4,e=5,f=6,g=7,h=8;
    uint32_t w=0x12345678, K=0x428a2f98;
    double t0=now();
    for (size_t blk=0; blk<nblocks; blk++){
        for (int i=0;i<64;i++){
            uint32_t S1 = ((e>>6)|(e<<26)) ^ ((e>>11)|(e<<21)) ^ ((e>>25)|(e<<7));
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = h + S1 + ch + K + w;
            uint32_t S0 = ((a>>2)|(a<<30)) ^ ((a>>13)|(a<<19)) ^ ((a>>22)|(a<<10));
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
            w += i;
        }
    }
    double dt=now()-t0;
    printf("synthetic rounds for 20MB: %.2f ms (a=%u)\n", dt*1000, a);
    /* repeat to see steady */
    t0=now();
    for (size_t blk=0; blk<nblocks; blk++){
        for (int i=0;i<64;i++){
            uint32_t S1 = ((e>>6)|(e<<26)) ^ ((e>>11)|(e<<21)) ^ ((e>>25)|(e<<7));
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = h + S1 + ch + K + w;
            uint32_t S0 = ((a>>2)|(a<<30)) ^ ((a>>13)|(a<<19)) ^ ((a>>22)|(a<<10));
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
        }
    }
    dt=now()-t0;
    printf("synthetic rounds (no w update) : %.2f ms\n", dt*1000);
    return 0;
}
EOF
