#include <time.h>
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }
int main(){
    /* 1-cycle dependent add chain. Use asm to prevent optimization. */
    uint32_t x = 1;
    uint64_t n = 200000000ULL;
    double t0 = now();
    asm volatile(
        "1:\n\t"
        "addl $1, %0\n\t"
        "subq $1, %1\n\t"
        "jne 1b\n\t"
        : "+r"(x), "+r"(n)
        :
        : "cc"
    );
    double dt = now()-t0;
    /* loop has add + sub + jne. jne is ~macro-fused with sub on Intel, so ~1 cycle/iter if predicted.
       The add is independent of the branch chain! So this measures branch throughput not add latency.
       Redo with a true dependency: addl %0, %0 doubles, latency 1. */
    printf("loop1 %.3f s (not pure latency)\n", dt);
    x = 1;
    n = 200000000ULL;
    t0 = now();
    asm volatile(
        "1:\n\t"
        "addl %0, %0\n\t"
        "subq $1, %1\n\t"
        "jne 1b\n\t"
        : "+r"(x), "+r"(n)
        :
        : "cc"
    );
    dt = now()-t0;
    printf("latency-ish loop %.3f s for 2e8 iters => %.2f GHz if 1 cyc/iter (branch may add)\n", dt, 0.2/dt);
    /* pure latency: unroll 8 dependent adds, decrement separate so the chain is the limit */
    n = 50000000ULL;
    uint32_t a=1;
    t0 = now();
    asm volatile(
        "1:\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "addl %%eax, %%eax\n\t"
        "subq $1, %1\n\t"
        "jne 1b\n\t"
        : "+a"(a), "+r"(n)
        :
        : "cc"
    );
    dt = now()-t0;
    double ops = 50000000.0 * 8;
    printf("8-dep-add chain: %.3f s, %.2f GHz (if 1cyc add)\n", dt, ops/dt/1e9);
