    st->r[0] = t0 & 0x0ffffffc0fffffffULL;
    st->r[1] = t1 & 0x0ffffffc0ffffffcULL;
    memcpy(&st->s[0], key+16, 8);
    memcpy(&st->s[1], key+24, 8);
