        for (int w = 0; w < 16; w++) dst[w] = m[w][b];
    }
}

static void chacha20_block(const uint32_t key[8], uint32_t counter,
                           const uint32_t nonce[3], uint8_t out[64]) {
    uint32_t s[16] = {
        0x61707865,0x3320646e,0x79622d32,0x6b206574,
        key[0],key[1],key[2],key[3],key[4],key[5],key[6],key[7],
        counter, nonce[0], nonce[1], nonce[2]
    };
    uint32_t w[16];
    memcpy(w, s, 64);
#define ROTL(x,n) (((x)<<(n)) | ((x)>>(32-(n))))
#define QR(a,b,c,d) \
    w[a]+=w[b]; w[d]^=w[a]; w[d]=ROTL(w[d],16); \
    w[c]+=w[d]; w[b]^=w[c]; w[b]=ROTL(w[b],12); \
    w[a]+=w[b]; w[d]^=w[a]; w[d]=ROTL(w[d],8);  \
    w[c]+=w[d]; w[b]^=w[c]; w[b]=ROTL(w[b],7);
    for (int i=0;i<10;i++){
        QR(0,4,8,12); QR(1,5,9,13); QR(2,6,10,14); QR(3,7,11,15);
        QR(0,5,10,15); QR(1,6,11,12); QR(2,7,8,13); QR(3,4,9,14);
    }
#undef QR
#undef ROTL
    for (int i=0;i<16;i++) store32(out+4*i, w[i]+s[i]);
}

/* XOR keystream into dst. counter starts at 1 (block 0 reserved for poly key). */
static void chacha20_xor(const uint32_t key[8], const uint32_t nonce[3],
                         const uint8_t *in, uint8_t *out, size_t len) {
    uint32_t counter = 1;
    uint8_t ks[512];
    while (len >= 512) {
        chacha20_8blocks(key, counter, nonce, ks);
        for (size_t i = 0; i < 512; i++) out[i] = in[i] ^ ks[i];
        in += 512; out += 512; len -= 512; counter += 8;
    }
    while (len >= 64) {
        chacha20_block(key, counter, nonce, ks);
        for (int i = 0; i < 64; i++) out[i] = in[i] ^ ks[i];
        in += 64; out += 64; len -= 64; counter++;
    }
    if (len) {
        chacha20_block(key, counter, nonce, ks);
        for (size_t i = 0; i < len; i++) out[i] = in[i] ^ ks[i];
    }
}

/* ---------- Poly1305 (Donna 26-bit limbs, __int128 mul) ---------- */
typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
} poly1305_ctx;

static void poly1305_init(poly1305_ctx *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
    /* r clamped, split into 26-bit limbs */
    uint32_t t0, t1, t2, t3;
    memcpy(&t0, key, 4); memcpy(&t1, key+4, 4);
    memcpy(&t2, key+8, 4); memcpy(&t3, key+12, 4);
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    memcpy(&st->pad[0], key+16, 4);
    memcpy(&st->pad[1], key+20, 4);
    memcpy(&st->pad[2], key+24, 4);
    memcpy(&st->pad[3], key+28, 4);
}

static void poly1305_blocks(poly1305_ctx *st, const uint8_t *m, size_t bytes, uint32_t hibit) {
    const uint32_t r0=st->r[0], r1=st->r[1], r2=st->r[2], r3=st->r[3], r4=st->r[4];
    const uint32_t s1 = r1*5, s2 = r2*5, s3 = r3*5, s4 = r4*5;
    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];

    while (bytes >= 16) {
        uint32_t t0,t1,t2,t3;
        memcpy(&t0, m, 4); memcpy(&t1, m+4, 4);
        memcpy(&t2, m+8, 4); memcpy(&t3, m+12, 4);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8) | (hibit << 24);

        unsigned __int128 d0 = (unsigned __int128)h0*r0 + (unsigned __int128)h1*s4 + (unsigned __int128)h2*s3 + (unsigned __int128)h3*s2 + (unsigned __int128)h4*s1;
        unsigned __int128 d1 = (unsigned __int128)h0*r1 + (unsigned __int128)h1*r0 + (unsigned __int128)h2*s4 + (unsigned __int128)h3*s3 + (unsigned __int128)h4*s2;
        unsigned __int128 d2 = (unsigned __int128)h0*r2 + (unsigned __int128)h1*r1 + (unsigned __int128)h2*r0 + (unsigned __int128)h3*s4 + (unsigned __int128)h4*s3;
        unsigned __int128 d3 = (unsigned __int128)h0*r3 + (unsigned __int128)h1*r2 + (unsigned __int128)h2*r1 + (unsigned __int128)h3*r0 + (unsigned __int128)h4*s4;
        unsigned __int128 d4 = (unsigned __int128)h0*r4 + (unsigned __int128)h1*r3 + (unsigned __int128)h2*r2 + (unsigned __int128)h3*r1 + (unsigned __int128)h4*r0;

        uint64_t c;
        c = (uint64_t)d0 & 0x3ffffff; h0 = (uint32_t)c; d1 += (uint64_t)(d0 >> 26);
        c = (uint64_t)d1 & 0x3ffffff; h1 = (uint32_t)c; d2 += (uint64_t)(d1 >> 26);
        c = (uint64_t)d2 & 0x3ffffff; h2 = (uint32_t)c; d3 += (uint64_t)(d2 >> 26);
        c = (uint64_t)d3 & 0x3ffffff; h3 = (uint32_t)c; d4 += (uint64_t)(d3 >> 26);
        c = (uint64_t)d4 & 0x3ffffff; h4 = (uint32_t)c;
        h0 += (uint32_t)((d4 >> 26) * 5);
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 16; bytes -= 16;
    }
    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
}

static void poly1305_update(poly1305_ctx *st, const uint8_t *m, size_t bytes) {
    if (st->buf_used) {
        size_t want = 16 - st->buf_used;
        if (want > bytes) want = bytes;
        memcpy(st->buf + st->buf_used, m, want);
        st->buf_used += want; m += want; bytes -= want;
        if (st->buf_used == 16) {
            poly1305_blocks(st, st->buf, 16, 1);
            st->buf_used = 0;
        }
    }
    size_t n = bytes & ~15u;
    if (n) { poly1305_blocks(st, m, n, 1); m += n; bytes -= n; }
    if (bytes) { memcpy(st->buf, m, bytes); st->buf_used = bytes; }
}

static void poly1305_finish(poly1305_ctx *st, uint8_t tag[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        memset(st->buf + st->buf_used + 1, 0, 16 - st->buf_used - 1);
        poly1305_blocks(st, st->buf, 16, 0);
    }
    uint32_t h0=st->h[0], h1=st->h[1], h2=st->h[2], h3=st->h[3], h4=st->h[4];
    uint32_t c;
    c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    /* fully carry-propagate and compute h + -p, select */
    uint32_t g0 = h0 + 5; c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    uint32_t mask = (g4 >> 31) - 1u; /* 0 if g4 negative (h < p), else all ones */
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = ((uint64_t)h0) | ((uint64_t)h1 << 26) | ((uint64_t)h2 << 52);
    uint64_t f1 = ((uint64_t)h2 >> 12) | ((uint64_t)h3 << 14) | ((uint64_t)h4 << 40);
    f0 += st->pad[0];
    f0 += ((uint64_t)st->pad[1]) << 32;
    f1 += (f0 >> 64);
    f1 += st->pad[2];
    f1 += ((uint64_t)st->pad[3]) << 32;

    uint32_t o0 = (uint32_t)f0;
    uint32_t o1 = (uint32_t)(f0 >> 32);
    uint32_t o2 = (uint32_t)f1;
    uint32_t o3 = (uint32_t)(f1 >> 32);
    memcpy(tag, &o0, 4); memcpy(tag+4, &o1, 4);
    memcpy(tag+8, &o2, 4); memcpy(tag+12, &o3, 4);
}

static void poly1305_auth(uint8_t tag[16], const uint8_t *m, size_t len, const uint8_t key[32]) {
    poly1305_ctx st;
    poly1305_init(&st, key);
    poly1305_update(&st, m, len);
    poly1305_finish(&st, tag);
}

/* AEAD encrypt. aad may be NULL if aad_len==0. */
int chacha20poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                             const uint8_t *aad, size_t aad_len,
                             const uint8_t *pt, size_t pt_len,
                             uint8_t *ct, uint8_t tag[16]) {
    uint32_t k[8], n[3];
    memcpy(k, key, 32);
    memcpy(n, nonce, 12);

    uint8_t block0[64];
    chacha20_block(k, 0, n, block0);

    chacha20_xor(k, n, pt, ct, pt_len);

    /* build mac data: aad || pad || ct || pad || le64(aad_len) || le64(ct_len) */
    poly1305_ctx st;
    poly1305_init(&st, block0);
    poly1305_update(&st, aad ? aad : (const uint8_t*)"", aad_len);
    if (aad_len & 15) {
        uint8_t zeros[16] = {0};
        poly1305_update(&st, zeros, 16 - (aad_len & 15));
    }
    poly1305_update(&st, ct, pt_len);
    if (pt_len & 15) {
        uint8_t zeros[16] = {0};
        poly1305_update(&st, zeros, 16 - (pt_len & 15));
    }
    uint8_t lens[16];
    uint64_t al = aad_len, cl = pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens+8, &cl, 8);
    poly1305_update(&st, lens, 16);
    poly1305_finish(&st, tag);
    return 0;
}
