        unsigned __int128 p_lo = (p00 & (unsigned __int128)(~0ULL)) | (mid << 64);
        unsigned __int128 p_hi = p11 + (p01 >> 64) + (p10 >> 64) + (mid >> 64);
        /* add q << 128, q = h2 * r */
        unsigned __int128 q = (unsigned __int128)h2 * r;
