/* partial-aware context wrapper: extend with buffer fields via a second struct */
typedef struct {
    poly1305_ctx base;
    uint8_t buf[16];
    size_t buf_used;
} poly1305_state;

static void poly1305_state_init(poly1305_state *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
    poly1305_init(&st->base, key);
}

static void poly1305_state_update(poly1305_state *st, const uint8_t *m, size_t bytes) {
    if (st->buf_used) {
        size_t want = 16 - st->buf_used;
        if (want > bytes) want = bytes;
        memcpy(st->buf + st->buf_used, m, want);
        st->buf_used += want; m += want; bytes -= want;
        if (st->buf_used == 16) {
            poly1305_blocks(&st->base, st->buf, 16);
            st->buf_used = 0;
        }
    }
    size_t n = bytes & ~(size_t)15;
    if (n) { poly1305_blocks(&st->base, m, n); m += n; bytes -= n; }
    if (bytes) { memcpy(st->buf, m, bytes); st->buf_used = bytes; }
}

static void poly1305_state_finish(poly1305_state *st, uint8_t tag[16]) {
    if (st->buf_used) {
        uint8_t tmp[16];
        memset(tmp, 0, 16);
        memcpy(tmp, st->buf, st->buf_used);
        tmp[st->buf_used] = 1;
