        uint64_t b0 = (uint64_t)r,  b1 = (uint64_t)(r >> 64);
        unsigned __int128 p00 = (unsigned __int128)a0 * b0;
        unsigned __int128 p01 = (unsigned __int128)a0 * b1;
        unsigned __int128 p10 = (unsigned __int128)a1 * b0;
