        p_hi += (unsigned __int128)h2 * r;
        unsigned __int128 lo = p_lo + (unsigned __int128)5 * (uint64_t)(p_hi >> 2);
        uint64_t hi2 = (uint64_t)(p_hi & 3) + (uint64_t)(lo < p_lo);
