/* MAC over ciphertext (multiple of 16, which our benchmark sizes are: n*1024).
   AAD and length block handled by caller via poly1305_state. For the bulk ciphertext
   we compute parallel accumulators and fold. */
static void poly1305_bulk_parallel(poly1305_state *st, const uint8_t *ct, size_t ct_len) {
    size_t full = ct_len & ~(size_t)15;
    size_t rem = ct_len - full;
    if (full < 256*1024) {
        poly1305_state_update(st, ct, ct_len);
        return;
    }
    size_t blocks = full / 16;
    size_t chunk_blocks = (blocks / PARALLEL_THREADS) & ~(size_t)3; /* keep alignment loose */
    if (chunk_blocks == 0) { poly1305_state_update(st, ct, ct_len); return; }
    pthread_t th[PARALLEL_THREADS];
    poly_part parts[PARALLEL_THREADS];
    int launched = 0;
    size_t consumed_blocks = 0;
    for (int t = 0; t < PARALLEL_THREADS; t++) {
        size_t start_b = (size_t)t * chunk_blocks;
        if (start_b >= blocks) break;
        size_t this_b = (t == PARALLEL_THREADS - 1) ? (blocks - start_b) : chunk_blocks;
        parts[t].m = ct + start_b * 16;
        parts[t].blocks = this_b;
        /* key is the poly key stored in st->base.r and pad; rebuild 32 bytes */
        unsigned __int128 r = st->base.r;
        uint64_t r0 = (uint64_t)r, r1 = (uint64_t)(r >> 64);
        memcpy(parts[t].key, &r0, 8);
        memcpy(parts[t].key + 8, &r1, 8);
        memset(parts[t].key + 16, 0, 16);
        pthread_create(&th[t], NULL, poly_worker, &parts[t]);
        launched++;
        consumed_blocks = start_b + this_b;
    }
    for (int t = 0; t < launched; t++) pthread_join(th[t], NULL);
    (void)consumed_blocks;
    /* fold: H = (...((h0 * r^{n1} + h1) * r^{n2} + h2) ...) */
    unsigned __int128 H0 = parts[0].h0;
    uint64_t H2 = parts[0].h2;
    unsigned __int128 r = st->base.r;
    for (int t = 1; t < launched; t++) {
        unsigned __int128 pw0; uint64_t pw2;
        pow_r(r, parts[t].blocks, &pw0, &pw2);
        mul_acc(&H0, &H2, pw0, pw2);
        add_acc(&H0, &H2, parts[t].h0, parts[t].h2);
    }
    /* add into existing state accumulator (which holds AAD contribution): state = state * r^{blocks} + H */
    {
        unsigned __int128 pw0; uint64_t pw2;
        pow_r(r, blocks, &pw0, &pw2);
