        poly1305_state_update(&st, aad, aad_len);
        if (aad_len & 15) {
            uint8_t zeros[16] = {0};
            poly1305_state_update(&st, zeros, 16 - (aad_len & 15));
        }
    }
    poly1305_bulk_parallel(&st, ct, pt_len);
    if (pt_len & 15) {
        uint8_t zeros[16] = {0};
        poly1305_state_update(&st, zeros, 16 - (pt_len & 15));
    }
    uint8_t lens[16];
    uint64_t al = aad_len, cl = pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    poly1305_state_update(&st, lens, 16);
    poly1305_state_finish(&st, tag);
    return 0;
}
