static void mul_by_r(unsigned __int128 *h0, uint64_t *h2, unsigned __int128 r) {
    unsigned __int128 hh0 = *h0; uint64_t hh2 = *h2;
    uint64_t a0 = (uint64_t)hh0, a1 = (uint64_t)(hh0 >> 64);
    uint64_t b0 = (uint64_t)r, b1 = (uint64_t)(r >> 64);
    unsigned __int128 p00 = (unsigned __int128)a0 * b0;
    unsigned __int128 p01 = (unsigned __int128)a0 * b1;
    unsigned __int128 p10 = (unsigned __int128)a1 * b0;
    unsigned __int128 p11 = (unsigned __int128)a1 * b1;
    unsigned __int128 mid = (p00 >> 64) + (uint64_t)p01 + (uint64_t)p10;
    unsigned __int128 p_lo = (unsigned __int128)(uint64_t)p00 | (mid << 64);
    unsigned __int128 p_hi = p11 + (p01 >> 64) + (p10 >> 64) + (mid >> 64);
    p_hi += (unsigned __int128)hh2 * r;
    unsigned __int128 hi_quot = p_hi >> 2;
    unsigned __int128 folded = hi_quot + (hi_quot << 2);
    unsigned __int128 lo = p_lo + folded;
    unsigned __int128 hi2_full = (p_hi & 3) + (lo < p_lo);
    while (hi2_full >= 4) {
        unsigned __int128 extra = (unsigned __int128)5 * (uint64_t)(hi2_full >> 2);
        unsigned __int128 lo2 = lo + extra;
        hi2_full = (hi2_full & 3) + (lo2 < lo);
        lo = lo2;
    }
    *h0 = lo; *h2 = (uint64_t)hi2_full;
}

