#include <stdlib.h>
#include <string.h>
#include <math.h>

extern void dgeev_(const char *jobvl, const char *jobvr, const int *n,
                   double *a, const int *lda, double *wr, double *wi,
                   double *vl, const int *ldvl, double *vr, const int *ldvr,
                   double *work, const int *lwork, int *info);

typedef struct {
    int n;
    int lwork;
    double *Af;
    double *wr;
    double *wi;
    double *vr;
    double *work;
    int *order;
    double *out; /* n*n*2 interleaved row-major eigenvectors after sort+norm */
} ws_t;

static ws_t W = {0};

static void ensure(int n) {
    if (W.n == n && W.work) return;
    free(W.Af); free(W.wr); free(W.wi); free(W.vr); free(W.work); free(W.order); free(W.out);
    W.n = n;
    W.Af = (double *)malloc((size_t)n * n * sizeof(double));
    W.wr = (double *)malloc((size_t)n * sizeof(double));
    W.wi = (double *)malloc((size_t)n * sizeof(double));
    W.vr = (double *)malloc((size_t)n * n * sizeof(double));
    W.order = (int *)malloc((size_t)n * sizeof(int));
    W.out = (double *)malloc((size_t)n * n * 2 * sizeof(double));
    double vl_dummy;
    int ldvl = 1, ldvr = n, lda = n, info = 0, lwork = -1;
    double wkopt = 0;
    char jobvl = 'N', jobvr = 'V';
    memset(W.Af, 0, (size_t)n * n * sizeof(double));
    dgeev_(&jobvl, &jobvr, &n, W.Af, &lda, W.wr, W.wi, &vl_dummy, &ldvl, W.vr, &ldvr, &wkopt, &lwork, &info);
    lwork = (int)wkopt;
    if (lwork < 8 * n) lwork = 8 * n;
    W.lwork = lwork;
    W.work = (double *)malloc((size_t)lwork * sizeof(double));
}

/* Compare eigenvalues for descending real, then descending imag. */
static int cmp_idx(const void *pa, const void *pb) {
    int ia = *(const int *)pa;
    int ib = *(const int *)pb;
    double ra = W.wr[ia], rb = W.wr[ib];
    if (ra < rb) return 1;
    if (ra > rb) return -1;
    double ia_ = W.wi[ia], ib_ = W.wi[ib];
    if (ia_ < ib_) return 1;
    if (ia_ > ib_) return -1;
    return 0;
}

/* out_rowmajor: n*n complex interleaved, each eigenvector is a contiguous row of n complexes.
   Returns info. */
int mkl_eig_sorted(const double *A_row, int n, double *out_rowmajor) {
    ensure(n);
    int lda = n, ldvl = 1, ldvr = n, info = 0, lwork = W.lwork;
    double vl_dummy;
    char jobvl = 'N', jobvr = 'V';
    for (int j = 0; j < n; ++j) {
        const double *src = A_row + (size_t)j; /* not contiguous in col */
        for (int i = 0; i < n; ++i)
            W.Af[i + (size_t)j * n] = A_row[(size_t)i * n + j];
    }
    dgeev_(&jobvl, &jobvr, &n, W.Af, &lda, W.wr, W.wi, &vl_dummy, &ldvl, W.vr, &ldvr, W.work, &lwork, &info);

    /* Build complex evals in wr/wi already (conjugate pairs stored as wr, +/- wi).
       For a conjugate pair, dgeev stores wi[k] > 0, wi[k+1] < 0, same wr.
       Eigenvectors:
         real: column k
         complex: col k + i col k+1 and conjugate.
    */
    for (int i = 0; i < n; ++i) W.order[i] = i;
    qsort(W.order, n, sizeof(int), cmp_idx);

    for (int t = 0; t < n; ++t) {
        int k = W.order[t];
        double *dst = out_rowmajor + (size_t)t * n * 2;
        double nrm = 0.0;
        if (W.wi[k] == 0.0) {
            for (int i = 0; i < n; ++i) {
                double re = W.vr[i + (size_t)k * n];
                dst[2 * i] = re;
                dst[2 * i + 1] = 0.0;
                nrm += re * re;
            }
        } else if (W.wi[k] > 0.0) {
            for (int i = 0; i < n; ++i) {
                double re = W.vr[i + (size_t)k * n];
                double im = W.vr[i + (size_t)(k + 1) * n];
                dst[2 * i] = re;
                dst[2 * i + 1] = im;
                nrm += re * re + im * im;
            }
        } else {
            /* negative imag: partner is k-1, vector is conjugate of column pair starting at k-1 */
            int kp = k - 1;
            for (int i = 0; i < n; ++i) {
                double re = W.vr[i + (size_t)kp * n];
                double im = -W.vr[i + (size_t)(kp + 1) * n];
                dst[2 * i] = re;
                dst[2 * i + 1] = im;
                nrm += re * re + im * im;
            }
        }
        nrm = sqrt(nrm);
        if (nrm > 1e-12) {
            double inv = 1.0 / nrm;
            for (int i = 0; i < n * 2; ++i) dst[i] *= inv;
        }
    }
    return info;
}
