/* Blocked transpose row-major -> column-major. */
static void transpose_rm_to_cm(const double *A, double *Af, int n) {
    const int B = 32;
    for (int jj = 0; jj < n; jj += B) {
        int jmax = jj + B < n ? jj + B : n;
        for (int ii = 0; ii < n; ii += B) {
            int imax = ii + B < n ? ii + B : n;
            for (int j = jj; j < jmax; ++j) {
                double *dst = Af + (size_t)j * n + ii;
                const double *src = A + ii * n + j;
                int i = ii;
                for (; i + 3 < imax; i += 4) {
                    dst[0] = src[0];
                    dst[1] = src[n];
                    dst[2] = src[2 * n];
                    dst[3] = src[3 * n];
                    dst += 4;
                    src += 4 * n;
                }
                for (; i < imax; ++i) {
                    *dst++ = *src;
                    src += n;
                }
            }
        }
    }
}

static PyObject *eig_solve(PyObject *self, PyObject *args) {
    PyObject *buf_obj;
    if (!PyArg_ParseTuple(args, "O", &buf_obj)) return NULL;
    Py_buffer view;
    if (PyObject_GetBuffer(buf_obj, &view, PyBUF_CONTIG_RO) != 0) return NULL;
    if (view.ndim != 2 || view.shape[0] != view.shape[1] || view.itemsize != (Py_ssize_t)sizeof(double)) {
        PyBuffer_Release(&view);
        PyErr_SetString(PyExc_ValueError, "expected square float64 C-contiguous matrix");
        return NULL;
    }
    int n = (int)view.shape[0];
    ensure(n);
    transpose_rm_to_cm((const double *)view.buf, W.Af, n);
    PyBuffer_Release(&view);

    int lda = n, ldvl = 1, ldvr = n, info = 0, lwork = W.lwork;
    double vl_dummy = 0;
    char jobvl = 'N', jobvr = 'V';
    dgeev_(&jobvl, &jobvr, &n, W.Af, &lda, W.wr, W.wi, &vl_dummy, &ldvl, W.vr, &ldvr,
           W.work, &lwork, &info);

    for (int i = 0; i < n; ++i) W.order[i] = i;
    qsort(W.order, (size_t)n, sizeof(int), cmp_idx);

    PyObject *outer = PyList_New(n);
    if (!outer) return NULL;
    for (int t = 0; t < n; ++t) {
