#include <stdlib.h>
#include <string.h>
#include <math.h>

extern void dgeev_(const char *jobvl, const char *jobvr, const int *n,
                   double *a, const int *lda, double *wr, double *wi,
                   double *vl, const int *ldvl, double *vr, const int *ldvr,
                   double *work, const int *lwork, int *info);
extern void mkl_serv_set_num_threads(int nt);

typedef struct {
    int n;
    int lwork;
    double *Af;
    double *wr;
    double *wi;
    double *vr;
    double *work;
    int *order;
} ws_t;

static ws_t W = {0};
static int threads_set = 0;

static void ensure(int n) {
    if (!threads_set) {
        mkl_serv_set_num_threads(1);
        threads_set = 1;
    }
    if (W.n == n && W.work) return;
    free(W.Af); free(W.wr); free(W.wi); free(W.vr); free(W.work); free(W.order);
    W.n = n;
    W.Af = (double *)malloc((size_t)n * n * sizeof(double));
    W.wr = (double *)malloc((size_t)n * sizeof(double));
    W.wi = (double *)malloc((size_t)n * sizeof(double));
    W.vr = (double *)malloc((size_t)n * n * sizeof(double));
    W.order = (int *)malloc((size_t)n * sizeof(int));
    double vl_dummy = 0;
    int ldvl = 1, ldvr = n, lda = n, info = 0, lwork = -1;
    double wkopt = 0;
    char jobvl = 'N', jobvr = 'V';
    memset(W.Af, 0, (size_t)n * n * sizeof(double));
    dgeev_(&jobvl, &jobvr, &n, W.Af, &lda, W.wr, W.wi, &vl_dummy, &ldvl, W.vr, &ldvr,
           &wkopt, &lwork, &info);
    lwork = (int)wkopt;
    if (lwork < 8 * n) lwork = 8 * n;
    W.lwork = lwork;
    W.work = (double *)malloc((size_t)lwork * sizeof(double));
}

static int cmp_idx(const void *pa, const void *pb) {
    int ia = *(const int *)pa;
    int ib = *(const int *)pb;
    double ra = W.wr[ia], rb = W.wr[ib];
    if (ra < rb) return 1;
    if (ra > rb) return -1;
    double ia_ = W.wi[ia], ib_ = W.wi[ib];
    if (ia_ < ib_) return 1;
    if (ia_ > ib_) return -1;
    return 0;
}

int mkl_eig_sorted(const double *A_row, int n, double *out_rowmajor) {
    ensure(n);
    const int B = 32;
    for (int jj = 0; jj < n; jj += B) {
        int jmax = jj + B < n ? jj + B : n;
        for (int ii = 0; ii < n; ii += B) {
            int imax = ii + B < n ? ii + B : n;
            for (int j = jj; j < jmax; ++j) {
                double *dst = W.Af + (size_t)j * n + ii;
                const double *src = A_row + (size_t)ii * n + j;
                int i = ii;
                for (; i + 3 < imax; i += 4) {
                    dst[0] = src[0];
                    dst[1] = src[n];
                    dst[2] = src[2 * (size_t)n];
                    dst[3] = src[3 * (size_t)n];
                    dst += 4;
                    src += 4 * (size_t)n;
                }
                for (; i < imax; ++i) {
                    *dst++ = *src;
                    src += n;
                }
            }
        }
    }
    int lda = n, ldvl = 1, ldvr = n, info = 0, lwork = W.lwork;
    double vl_dummy = 0;
    char jobvl = 'N', jobvr = 'V';
    dgeev_(&jobvl, &jobvr, &n, W.Af, &lda, W.wr, W.wi, &vl_dummy, &ldvl, W.vr, &ldvr,
           W.work, &lwork, &info);

    for (int i = 0; i < n; ++i) W.order[i] = i;
    qsort(W.order, (size_t)n, sizeof(int), cmp_idx);

    for (int t = 0; t < n; ++t) {
        int k = W.order[t];
        double *dst = out_rowmajor + (size_t)t * n * 2;
        double nrm = 0.0;
        if (W.wi[k] == 0.0) {
            const double *col = W.vr + (size_t)k * n;
            for (int i = 0; i < n; ++i) nrm += col[i] * col[i];
            nrm = sqrt(nrm);
            double inv = nrm > 1e-12 ? 1.0 / nrm : 1.0;
            for (int i = 0; i < n; ++i) {
                dst[2 * i] = col[i] * inv;
                dst[2 * i + 1] = 0.0;
            }
        } else if (W.wi[k] > 0.0) {
            const double *colr = W.vr + (size_t)k * n;
            const double *coli = W.vr + (size_t)(k + 1) * n;
            for (int i = 0; i < n; ++i) nrm += colr[i] * colr[i] + coli[i] * coli[i];
            nrm = sqrt(nrm);
            double inv = nrm > 1e-12 ? 1.0 / nrm : 1.0;
            for (int i = 0; i < n; ++i) {
                dst[2 * i] = colr[i] * inv;
                dst[2 * i + 1] = coli[i] * inv;
            }
        } else {
            int kp = k - 1;
            const double *colr = W.vr + (size_t)kp * n;
            const double *coli = W.vr + (size_t)(kp + 1) * n;
            for (int i = 0; i < n; ++i) nrm += colr[i] * colr[i] + coli[i] * coli[i];
            nrm = sqrt(nrm);
            double inv = nrm > 1e-12 ? 1.0 / nrm : 1.0;
            for (int i = 0; i < n; ++i) {
                dst[2 * i] = colr[i] * inv;
                dst[2 * i + 1] = -coli[i] * inv;
            }
        }
    }
    return info;
}
