#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* One Francis double-shift QR sweep on unreduced Hessenberg H (n x n, column-major),
   accumulating into Z (column-major). Returns 1 if a deflation happened. */
static void francis_sweep(double *H, double *Z, int n, int l, int m) {
    /* active block rows/cols l..m inclusive */
    int nn = m - l + 1;
    if (nn < 3) return;
    double a = H[(m-1) + (size_t)(m-1)*n];
    double b = H[(m-1) + (size_t)m*n];
    double c = H[m + (size_t)(m-1)*n];
    double d = H[m + (size_t)m*n];
    double tr = a + d;
    double det = a*d - b*c;
    double h00 = H[l + (size_t)l*n];
    double h01 = H[l + (size_t)(l+1)*n];
    double h10 = H[(l+1) + (size_t)l*n];
    double h11 = H[(l+1) + (size_t)(l+1)*n];
    double h21 = H[(l+2) + (size_t)(l+1)*n];
    double x = h00*h00 + h01*h10 - tr*h00 + det;
    double y = h10*(h00 + h11 - tr);
    double z = h10*h21;

    for (int k = l; k <= m-2; ++k) {
        double nrm = sqrt(x*x + y*y + z*z);
        if (nrm == 0.0) break;
        double sign = x >= 0.0 ? 1.0 : -1.0;
        double v0 = x + sign*nrm;
        double v1 = y;
        double v2 = z;
        double vnorm2 = v0*v0 + v1*v1 + v2*v2;
        if (vnorm2 == 0.0) break;
        double beta = 2.0 / vnorm2;

        /* left apply rows k:k+2, cols k:n-1 (enough) */
        int j0 = k;
        for (int j = j0; j < n; ++j) {
            double *col = H + (size_t)j*n;
            double dot = v0*col[k] + v1*col[k+1] + v2*col[k+2];
            double fac = beta * dot;
            col[k] -= fac*v0;
            col[k+1] -= fac*v1;
            col[k+2] -= fac*v2;
        }
        /* right apply cols k:k+2, rows 0:min(n,k+4) */
        int rows_end = k+4 < n ? k+4 : n;
        for (int i = 0; i < rows_end; ++i) {
            double h0 = H[i + (size_t)k*n];
            double h1 = H[i + (size_t)(k+1)*n];
            double h2 = H[i + (size_t)(k+2)*n];
            double dot = h0*v0 + h1*v1 + h2*v2;
            double fac = beta * dot;
            H[i + (size_t)k*n] = h0 - fac*v0;
            H[i + (size_t)(k+1)*n] = h1 - fac*v1;
            H[i + (size_t)(k+2)*n] = h2 - fac*v2;
        }
        for (int i = 0; i < n; ++i) {
            double z0 = Z[i + (size_t)k*n];
            double z1 = Z[i + (size_t)(k+1)*n];
            double z2 = Z[i + (size_t)(k+2)*n];
            double dot = z0*v0 + z1*v1 + z2*v2;
            double fac = beta * dot;
            Z[i + (size_t)k*n] = z0 - fac*v0;
            Z[i + (size_t)(k+1)*n] = z1 - fac*v1;
            Z[i + (size_t)(k+2)*n] = z2 - fac*v2;
        }
        if (k+1 <= m-2) {
            x = H[(k+1) + (size_t)k*n];
            y = H[(k+2) + (size_t)k*n];
            z = (k+3 <= m) ? H[(k+3) + (size_t)k*n] : 0.0;
        } else break;
    }
    /* zero below subdiagonal in the chased region */
    for (int i = l+2; i <= m && i < n; ++i) {
        for (int j = 0; j <= i-2; ++j) H[i + (size_t)j*n] = 0.0;
    }
}

/* Drive until subdiagonal small or max sweeps. */
void qr_converge(double *H, double *Z, int n, int max_sweeps) {
    for (int sweep = 0; sweep < max_sweeps; ++sweep) {
        int m = n-1;
        while (m > 0) {
            double scale = fabs(H[m + (size_t)m*n]) + fabs(H[(m-1) + (size_t)(m-1)*n]);
            if (fabs(H[m + (size_t)(m-1)*n]) <= 1e-14 * (scale + 1e-30)) {
                H[m + (size_t)(m-1)*n] = 0.0;
                m--;
            } else break;
        }
        if (m < 1) return;
        int l = 0;
        for (int i = m; i > 0; --i) {
            double scale = fabs(H[i + (size_t)i*n]) + fabs(H[(i-1) + (size_t)(i-1)*n]);
            if (fabs(H[i + (size_t)(i-1)*n]) <= 1e-14 * (scale + 1e-30)) {
                l = i;
                break;
            }
        }
        if (m - l < 2) {
            /* 1x1 or 2x2 already, treat as converged by zeroing if tiny, else just continue other blocks
               For simplicity mark this subdiag as accepted if 2x2 and move on by zeroing nothing.
               Split: if block length 2, skip it by zeroing a sentinel? We set a large deflation by
               temporarily considering it converged: zero nothing, but force m = l-1 next by setting a flag.
               Easiest: set H[l, l-1] stay, and reduce m to l-1 for next iteration by zeroing a fake?
               We'll just zero the connection above the 2x2 if the 2x2 is the active end and its subdiag is not tiny
               only when block size <=2. */
            if (m - l <= 1) {
                /* deflate this block by treating connection at l as a split: set a marker by reducing via setting subdiag at l to 0 only if l>0 and block is 1 or 2 and we've decided it's a final 2x2.
                   A 2x2 with large subdiag IS the converged complex pair. Split it off. */
                if (l > 0) H[l + (size_t)(l-1)*n] = 0.0;
                else return;
                continue;
            }
        }
        francis_sweep(H, Z, n, l, m);
    }
}
