static void inc_counter(unsigned char ctr[16], uint32_t blocks) {
    /* increment last 32 bits big-endian by blocks */
    uint32_t c = ((uint32_t)ctr[12] << 24) | ((uint32_t)ctr[13] << 16) | ((uint32_t)ctr[14] << 8) | ctr[15];
    c += blocks;
    ctr[12] = (c >> 24) & 0xff;
    ctr[13] = (c >> 16) & 0xff;
    ctr[14] = (c >> 8) & 0xff;
    ctr[15] = c & 0xff;
}

static void *worker(void *arg) {
    job_t *j = arg;
    unsigned char ctr[16];
    memcpy(ctr, j->counter0, 16);
    /* message block index of start: start/16, GCM counter starts at 2 for first block */
    uint32_t block_index = (uint32_t)(j->start / 16);
    unsigned char local[16];
    memcpy(local, j->counter0, 16);
    /* counter0 is nonce||00000002 already for first block. increment by block_index */
    inc_counter(local, block_index);

    size_t off = 0;
    unsigned char ks[16];
    while (off + 16 <= j->len) {
        AES_encrypt(local, ks, &j->aes);
        const unsigned char *p = j->pt + j->start + off;
        unsigned char *c = j->ct + j->start + off;
        for (int i = 0; i < 16; i++) c[i] = p[i] ^ ks[i];
        inc_counter(local, 1);
        off += 16;
    }
    if (off < j->len) {
        AES_encrypt(local, ks, &j->aes);
        const unsigned char *p = j->pt + j->start + off;
        unsigned char *c = j->ct + j->start + off;
        size_t rem = j->len - off;
        for (size_t i = 0; i < rem; i++) c[i] = p[i] ^ ks[i];
    }
    return NULL;
}

int main() {
    size_t n = 60ull * 1024 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ct_ref = malloc(n + 16);
    unsigned char key[16], nonce[12], tag[16];
    memset(pt, 0x5a, n);
    memset(key, 0x11, 16);
    memset(nonce, 0x22, 12);

    /* reference */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen=0, finlen=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ct_ref, &outlen, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct_ref + outlen, &finlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    AES_KEY aes;
    AES_set_encrypt_key(key, 128, &aes);

    job_t jobs[NTHREADS];
    pthread_t th[NTHREADS];
    size_t chunk = (n / NTHREADS) & ~15ull;
    double t0 = now();
    int iters = 3;
    for (int it = 0; it < iters; it++) {
        size_t pos = 0;
        for (int i = 0; i < NTHREADS; i++) {
            jobs[i].pt = pt;
            jobs[i].ct = ct;
            jobs[i].start = pos;
            jobs[i].len = (i == NTHREADS-1) ? (n - pos) : chunk;
            memcpy(jobs[i].counter0, nonce, 12);
            jobs[i].counter0[12]=0; jobs[i].counter0[13]=0; jobs[i].counter0[14]=0; jobs[i].counter0[15]=2;
            jobs[i].aes = aes;
            pos += jobs[i].len;
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < NTHREADS; i++) pthread_join(th[i], NULL);
    }
    double t1 = now();
    printf("parallel AES_encrypt CTR %.4f s  MB/s %.1f\n", (t1-t0)/iters, 60.0/((t1-t0)/iters));
    printf("match ref %d\n", memcmp(ct, ct_ref, n)==0);

    /* single thread timing */
    t0 = now();
    for (int it = 0; it < iters; it++) {
        jobs[0].pt = pt; jobs[0].ct = ct; jobs[0].start = 0; jobs[0].len = n;
        memcpy(jobs[0].counter0, nonce, 12);
        jobs[0].counter0[12]=0; jobs[0].counter0[13]=0; jobs[0].counter0[14]=0; jobs[0].counter0[15]=2;
        jobs[0].aes = aes;
        worker(&jobs[0]);
    }
    t1 = now();
    printf("single AES_encrypt CTR %.4f s  MB/s %.1f match %d\n", (t1-t0)/iters, 60.0/((t1-t0)/iters), memcmp(ct, ct_ref, n)==0);
    return 0;
}
