    unsigned char z[32];
    memcpy(z, prod, 32);
    for (int i = 255; i >= 128; i--) {
        if (getbit_be(z, 256, i)) {
            /* cancel bit i by xoring x^128, and xor x^0,x^1,x^2,x^7 at position i-128 */
            int base = i - 128;
            /* xor bits base+0, base+1, base+2, base+7, and bit i */
            int offs[5] = {0,1,2,7,128};
            for (int k = 0; k < 5; k++) {
