    carry = _mm_srli_si128(tmp7, 4);          /* this gets xored into high */
    tmp7 = _mm_slli_si128(tmp7, 12);
    tmp3 = _mm_xor_si128(tmp3, tmp7);

    tmp2 = _mm_srli_epi32(tmp3, 1);
    tmp4 = _mm_xor_si128(tmp4, carry);        /* fold the left-shift carry into high */
    tmp7 = _mm_srli_epi32(tmp3, 2);
    tmp8 = _mm_srli_epi32(tmp3, 7);
    tmp2 = _mm_xor_si128(tmp2, tmp7);
    tmp2 = _mm_xor_si128(tmp2, tmp8);
    tmp2 = _mm_xor_si128(tmp2, tmp8);
    tmp3 = _mm_xor_si128(tmp3, tmp2);
    tmp4 = _mm_xor_si128(tmp4, tmp3);
    return tmp4;
