/* Another common exact copy (from Intel paper code sample "ghash" as republished):
   I found this exact sequence in my memory from https://github.com/veorq/cryptocore or similar.
   Let's also try NOT shifting the product by 1 first (that shift converts between two conventions).
*/

static __m128i variant_D(__m128i a, __m128i b) {
    /* CLMUL reduction with poly 0x87 on high half, for bit-reflected inputs where
       the modulus reduction constant in the low bits is 0x87 (x^7+x^2+x+1 reflected to low).
       Algorithm from Gueron 2012 "AES-GCM software" fast reduction:
    */
    __m128i lo = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i hi = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));

    const __m128i poly = _mm_set_epi32(0, 0, 0, 0x87); /* low 64 has 0x87? set_epi32 last arg is low */
    /* two-step: */
    __m128i t1 = _mm_clmulepi64_si128(lo, poly, 0x00); /* low64 * 0x87 */
    __m128i t2 = _mm_xor_si128(lo, _mm_slli_si128(t1, 8)); /* ? */
    (void)t2;
    /* Gueron fast reduction:
       T = lo
       A = clmul(T, poly, 0x01)  // high half of T * poly? 
       Let's try the published 2-clmul reduction:

       __m128i t = _mm_clmulepi64_si128(lo, _mm_set_epi32(0,0,0,0x87), 0x00);
       lo = _mm_xor_si128(lo, t); // no

       From https://github.com/golang/crypto/blob/master/internal/poly1305 — no.

       I'll implement scalar reduction of the reflected product (LSB = x^0) which I know is correct,
       just to have a correct (if slow) baseline, then optimize.
    */
    (void)hi; (void)poly;
    return lo;
}

/* Correct scalar reduction on reflected product, then we'll speed it up. */
static void gfmul_scalar_reflected(const unsigned char *A, const unsigned char *B, unsigned char *out) {
    /* A, B natural NIST bytes. Use bit algorithm. */
    unsigned char Z[16] = {0};
    unsigned char V[16];
    memcpy(V, A, 16);
    for (int i = 0; i < 16; i++) {
        unsigned char y = B[i];
        for (int bit = 0; bit < 8; bit++) {
            if (y & (0x80 >> bit)) {
                for (int k = 0; k < 16; k++) Z[k] ^= V[k];
            }
            int lsb = V[15] & 1;
            /* right shift V by 1 bit (NIST: toward LSB which is rightmost) */
            for (int k = 15; k > 0; k--) {
                V[k] = (V[k] >> 1) | (V[k-1] << 7);
            }
            V[0] >>= 1;
            if (lsb) V[0] ^= 0xe1;
        }
    }
    memcpy(out, Z, 16);
}

int main() {
    unsigned char H[16] = {0x66,0xe9,0x4b,0xd4,0xef,0x8a,0x2c,0x3b,0x88,0x4c,0xfa,0x59,0xca,0x34,0x2b,0x2e};
    unsigned char C[16] = {0x03,0x88,0xda,0xce,0x60,0xb6,0xa3,0x92,0xf3,0x28,0xc2,0xb9,0x71,0xb2,0xfe,0x78};
    unsigned char expect[16];
    gfmul_scalar_reflected(H, C, expect);
    printf("scalar ");
    for (int i = 0; i < 16; i++) printf("%02x", expect[i]);
    printf("\n");

    __m128i Hr = bitrev_bytes(_mm_loadu_si128((const __m128i*)H));
    __m128i Cr = bitrev_bytes(_mm_loadu_si128((const __m128i*)C));

    __m128i rA = variant_A(Hr, Cr);
    __m128i rC = variant_C(Hr, Cr);
    dump("A reflected", rA);
    dump("A natural", bitrev_bytes(rA));
    dump("C reflected", rC);
    dump("C natural", bitrev_bytes(rC));
    return 0;
}
