#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

static inline __m128i bitrev_bytes(__m128i x) {
    unsigned char table[16] = {0x0,0x8,0x4,0xc,0x2,0xa,0x6,0xe,0x1,0x9,0x5,0xd,0x3,0xb,0x7,0xf};
    __m128i tbl = _mm_loadu_si128((const __m128i*)table);
    __m128i lo = _mm_and_si128(x, _mm_set1_epi8(0x0f));
    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    lo = _mm_shuffle_epi8(tbl, lo);
    hi = _mm_shuffle_epi8(tbl, hi);
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}

static void dump(const char *n, __m128i v) {
    unsigned char b[16];
    _mm_storeu_si128((__m128i*)b, v);
    printf("%-20s ", n);
    for (int i = 0; i < 16; i++) printf("%02x", b[i]);
    printf("\n");
}

/* Product in reflected order (LSB of lo = x^0). */
static void product(__m128i a, __m128i b, __m128i *lo, __m128i *hi) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
                               _mm_clmulepi64_si128(a, b, 0x10));
    *lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    *hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
}

/* Reduce reflected 256-bit product modulo x^128 + x^7 + x^2 + x + 1.
   In reflected convention, x^128 terms (bit 128, which is LSB of hi) are replaced by
   x^7+x^2+x+1 = 0x87 in the low bits.
   For bit (128+k) set, xor 0x87 << k into the low 128, and clear that bit.
   This is: low ^= clmul(hi, 0x87)  but clmul of the 128-bit hi by 0x87 (which fits in low 8 bits)
   produces a 135-bit result; the top 7 bits must be folded again.
*/
static __m128i reduce_v1(__m128i lo, __m128i hi) {
    const __m128i poly = _mm_set_epi64x(0, 0x87); /* low 64 = 0x87 */
    __m128i p_lo, p_hi;
    /* hi * 0x87 */
    product(hi, poly, &p_lo, &p_hi);
    lo = _mm_xor_si128(lo, p_lo);
    /* p_hi is at most 7 bits (0x87 * x^127 needs up to bit 134, so 7 extra bits). fold again */
    product(p_hi, poly, &p_lo, &p_hi);
    lo = _mm_xor_si128(lo, p_lo);
    return lo;
}

/* Same but poly in the other lane conventions. */
static __m128i reduce_v2(__m128i lo, __m128i hi) {
    /* Only low 64 of hi matters for first? No hi is full 128.
       clmul64 of each half of hi by 0x87. */
    const __m128i poly = _mm_set_epi64x(0, 0x87);
    __m128i m0 = _mm_clmulepi64_si128(hi, poly, 0x00); /* hi.low * 0x87 -> 64+7 bits in low 128? 64*8=72, fits in 128 */
    __m128i m1 = _mm_clmulepi64_si128(hi, poly, 0x01); /* hi.high * 0x87 -> goes to bits 64..135 */
    /* m1's low 64 is bits 64..127 of the product, m1's high 64 is bits 128..191 (only low 7 used) */
    __m128i fold = _mm_xor_si128(m0, _mm_slli_si128(m1, 8));
    __m128i extra = _mm_srli_si128(m1, 8); /* bits 128+ */
    lo = _mm_xor_si128(lo, fold);
    /* extra * 0x87 */
    __m128i e = _mm_clmulepi64_si128(extra, poly, 0x00);
    lo = _mm_xor_si128(lo, e);
    return lo;
}

/* Gueron fast reduction exactly as commonly written, poly = _mm_setr_epi32(0x87,0,0,0) which is 0x87 in low dword.
   Try both orientations. */
static __m128i reduce_gueron(__m128i lo, __m128i hi, int which) {
    __m128i poly = which ? _mm_setr_epi32(0x87, 0, 0, 0) : _mm_set_epi32(0, 0, 0, 0x87);
    /* The fast reduction from Gueron "Intel PCLMUL" revised:
       Given X0 = lo, X1 = hi (product)
       __m128i t = _mm_clmulepi64_si128(X0? no X1)
    */
    (void)poly;
    return lo;
}

int main() {
    unsigned char H[16] = {0x66,0xe9,0x4b,0xd4,0xef,0x8a,0x2c,0x3b,0x88,0x4c,0xfa,0x59,0xca,0x34,0x2b,0x2e};
    unsigned char C[16] = {0x03,0x88,0xda,0xce,0x60,0xb6,0xa3,0x92,0xf3,0x28,0xc2,0xb9,0x71,0xb2,0xfe,0x78};
    __m128i Hr = bitrev_bytes(_mm_loadu_si128((const __m128i*)H));
    __m128i Cr = bitrev_bytes(_mm_loadu_si128((const __m128i*)C));
    __m128i lo, hi;
    product(Hr, Cr, &lo, &hi);
    dump("lo", lo);
    dump("hi", hi);
    __m128i r1 = reduce_v1(lo, hi);
    __m128i r2 = reduce_v2(lo, hi);
    dump("v1 natural", bitrev_bytes(r1));
    dump("v2 natural", bitrev_bytes(r2));
    printf("expected             5e2ec746917062882c85b0685353deb7\n");

    /* Also try if product halves are swapped in meaning */
    __m128i r3 = reduce_v2(hi, lo);
    dump("swapped natural", bitrev_bytes(r3));
    return 0;
}
