/* ---------------- GHASH ---------------- */
static inline __m128i bitrev_bytes(__m128i x) {
    /* table is constant; load each call is fine (hoisted by compiler hopefully) */
    unsigned char table[16] = {0x0,0x8,0x4,0xc,0x2,0xa,0x6,0xe,0x1,0x9,0x5,0xd,0x3,0xb,0x7,0xf};
