    __m128i hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
    __m128i m0 = _mm_clmulepi64_si128(hi, poly, 0x00);
    __m128i m1 = _mm_clmulepi64_si128(hi, poly, 0x01);
    __m128i fold = _mm_xor_si128(m0, _mm_slli_si128(m1, 8));
    __m128i extra = _mm_srli_si128(m1, 8);
    lo = _mm_xor_si128(lo, fold);
    lo = _mm_xor_si128(lo, _mm_clmulepi64_si128(extra, poly, 0x00));
    return lo;
}

/* GHASH over full blocks, data is natural byte order. H_ref is reflected hash subkey.
   Returns reflected state. */
static __m128i ghash_blocks(const unsigned char *data, size_t nblocks, __m128i H_ref, __m128i state) {
    for (size_t i = 0; i < nblocks; i++) {
        __m128i x = bitrev_bytes(_mm_loadu_si128((const __m128i*)(data + i*16)));
        state = gfmul(_mm_xor_si128(state, x), H_ref);
    }
    return state;
