/* ---------------- parallel job ---------------- */
#define NT 6
typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    size_t nblocks;
    uint32_t counter;
    unsigned char nonce[12];
    aes128_key key;
    __m128i H_ref;
    __m128i ghash_state; /* out, reflected */
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    ctr_xor_8(&j->key, j->pt, j->ct, j->nblocks, j->counter, j->nonce);
    j->ghash_state = ghash_blocks(j->ct, j->nblocks, j->H_ref, _mm_setzero_si128());
    return NULL;
}

static void gcm_encrypt(const unsigned char *key, const unsigned char *nonce,
                        const unsigned char *pt, size_t pt_len,
                        const unsigned char *aad, size_t aad_len,
                        unsigned char *ct, unsigned char tag[16]) {
    aes128_key ak;
