    __m128i H_ref = bitrev_bytes(H);

    size_t nblocks = pt_len / 16;
    size_t rem = pt_len % 16;

    /* For partial last block, handle in main thread after parallel full blocks.
       Split full blocks across threads. */
    job_t jobs[NT];
    pthread_t th[NT];
    size_t chunk = nblocks / NT;
    size_t pos = 0;
    int nthreads = NT;
    if (nblocks < (size_t)NT * 8) nthreads = 1;
    if (nthreads == 1) chunk = nblocks;

    for (int i = 0; i < nthreads; i++) {
        size_t nb = (i == nthreads-1) ? (nblocks - pos) : chunk;
        jobs[i].pt = pt + pos*16;
        jobs[i].ct = ct + pos*16;
        jobs[i].nblocks = nb;
        jobs[i].counter = 2 + (uint32_t)pos;
        memcpy(jobs[i].nonce, nonce, 12);
        jobs[i].key = ak;
        jobs[i].H_ref = H_ref;
        if (nthreads > 1)
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        else
            worker(&jobs[i]);
        pos += nb;
    }
    if (nthreads > 1) {
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
