    }

    /* Combine GHASH. Each job hashed its blocks as if starting from 0, so
       state_i = ct_i * H^(len_i) + ... but we need them chained.
       state_i = GHASH(chunk_i) = (...((c0*H)+c1)*H ... )*H
       To prepend previous state S (which equals GHASH(prev)*H^0 at the boundary,
       S is the state AFTER processing prev, i.e. already multiplied by H for each prev block):
       combined = (S + first_block_of_chunk) * H^nblocks_chunk  xor  (state_without the first multiply?)

       Careful:
       ghash_blocks starts with state 0 and does state = (state xor block) * H for each block.
       So state_i = b0*H^{n} xor b1*H^{n-1} xor ... xor b_{n-1}*H
       The true state after previous chunks S_prev = p0*H^{m} xor ... 
       True combined = S_prev * H^{n}  xor  state_i
       Yes! Because every previous block needs n more multiplications by H.
       S_prev * H^n = gfmul(S_prev, H^n).
    */
    __m128i state = _mm_setzero_si128();
    for (int i = 0; i < nthreads; i++) {
        size_t nb = jobs[i].nblocks;
        if (nb == 0) continue;
