        __m128i Hp = H_ref; /* H^1 */
        __m128i Hn = _mm_setzero_si128();
        /* identity for gfmul? We need H^nb. Use square-and-multiply.
           Careful: gfmul expects reflected operands and H_ref is reflected H^1.
           The multiplicative identity in reflected representation is reflect(1) where
           1 is x^0 which in NIST is the leftmost bit = 0x80 in byte 0.
           reflect(0x80 00..00) = bitrev(0x80) = 0x01 in byte 0.
        */
        unsigned char one_nat[16] = {0x80};
        __m128i one = bitrev_bytes(_mm_loadu_si128((const __m128i*)one_nat));
        Hn = one;
        __m128i base = H_ref;
