        memcpy(last, ct + nblocks*16, rem);
        __m128i x = bitrev_bytes(_mm_loadu_si128((const __m128i*)last));
        state = gfmul(_mm_xor_si128(state, x), H_ref);
    }

    /* AAD GHASH must be prepended: true state = GHASH(AAD || CT || len).
       We have GHASH(CT) in state (as if AAD empty). 
       If AAD present, S = GHASH(AAD) * H^{nblocks_ct_padded} xor GHASH(CT).
       Easiest correct approach: hash AAD first into a state, then multiply by H^{ct_blocks}
       and xor. ct_blocks includes the partial block as one block.
    */
    size_t ct_blocks_padded = nblocks + (rem ? 1 : 0);
