            unsigned char last[16] = {0};
            memcpy(last, aad + ab*16, ar);
            __m128i x = bitrev_bytes(_mm_loadu_si128((const __m128i*)last));
            sa = gfmul(_mm_xor_si128(sa, x), H_ref);
        }
        size_t aad_blocks = ab + (ar ? 1 : 0);
        /* state currently = GHASH(CT) which already includes *H per ct block.
           We need sa * H^{ct_blocks} xor state. */
        unsigned char one_nat[16] = {0x80};
        __m128i one = bitrev_bytes(_mm_loadu_si128((const __m128i*)one_nat));
        __m128i Hn = one;
        __m128i base = H_ref;
        size_t e = ct_blocks_padded;
        while (e) {
            if (e & 1) Hn = gfmul(Hn, base);
            base = gfmul(base, base);
            e >>= 1;
        }
        state = _mm_xor_si128(gfmul(sa, Hn), state);
