    unsigned char lenb[16] = {0};
    uint64_t aad_bits = (uint64_t)aad_len * 8;
    uint64_t ct_bits = (uint64_t)pt_len * 8;
    for (int i = 0; i < 8; i++) {
        lenb[i] = (aad_bits >> (56 - 8*i)) & 0xff;
        lenb[8+i] = (ct_bits >> (56 - 8*i)) & 0xff;
    }
    __m128i L = bitrev_bytes(_mm_loadu_si128((const __m128i*)lenb));
    state = gfmul(_mm_xor_si128(state, L), H_ref);

    /* tag = S xor E(K, nonce||1) */
    unsigned char j0[16] = {0};
    memcpy(j0, nonce, 12);
    j0[15] = 1;
    __m128i ek = aes128_enc(&ak, _mm_loadu_si128((const __m128i*)j0));
    __m128i S = bitrev_bytes(state);
    _mm_storeu_si128((__m128i*)tag, _mm_xor_si128(S, ek));
}

