static __m128i ghash(const unsigned char *data, size_t nblocks, __m128i H) {
    __m128i state = _mm_setzero_si128();
    for (size_t i = 0; i < nblocks; i++) {
        __m128i x = bitrev(_mm_loadu_si128((const __m128i*)(data + i*16)));
        state = gfmul(_mm_xor_si128(state, x), H);
    }
    return state;
}

#define NT 6
typedef struct {
    const unsigned char *in; unsigned char *out; size_t nblocks;
    uint32_t counter; unsigned char nonce[12]; aes128_key key; __m128i H;
    int mode; /* 0 ctr, 1 ghash, 2 both */
} job;
static void *worker(void *arg) {
    job *j = arg;
    if (j->mode == 0 || j->mode == 2)
        ctr8(&j->key, j->in, j->out, j->nblocks, j->counter, j->nonce);
    if (j->mode == 1 || j->mode == 2)
        ghash(j->mode==1 ? j->in : j->out, j->nblocks, j->H);
    return NULL;
}

static double run(int mode, unsigned char *pt, unsigned char *ct, size_t nblocks, aes128_key *ak, __m128i H, unsigned char *nonce) {
    job jobs[NT]; pthread_t th[NT];
    size_t chunk = nblocks / NT;
    double t0 = now();
    int iters = 3;
    for (int it = 0; it < iters; it++) {
        size_t pos = 0;
        for (int i = 0; i < NT; i++) {
            size_t nb = (i==NT-1)? nblocks-pos : chunk;
            jobs[i].in = pt + pos*16;
            jobs[i].out = ct + pos*16;
            jobs[i].nblocks = nb;
            jobs[i].counter = 2 + (uint32_t)pos;
            memcpy(jobs[i].nonce, nonce, 12);
            jobs[i].key = *ak;
            jobs[i].H = H;
            jobs[i].mode = mode;
            pos += nb;
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < NT; i++) pthread_join(th[i], NULL);
    }
    return (now()-t0)/iters;
