/* Current gfmul */
static inline __m128i gfmul_old(__m128i a, __m128i b) {
    const __m128i poly = _mm_set_epi64x(0, 0x87);
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    __m128i hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
    __m128i m0 = _mm_clmulepi64_si128(hi, poly, 0x00);
    __m128i m1 = _mm_clmulepi64_si128(hi, poly, 0x01);
    lo = _mm_xor_si128(lo, _mm_xor_si128(m0, _mm_slli_si128(m1, 8)));
    lo = _mm_xor_si128(lo, _mm_clmulepi64_si128(_mm_srli_si128(m1, 8), poly, 0x00));
    return lo;
}

/* Faster reduction: since poly is 0x87 (8 bits), hi.high * 0x87 fits in a way we can
   use shifts. Gueron-style 2-clmul reduction for reflected poly 0x87:

   A well-known fast reduction (from Intel, for the bit-reflected convention where
   the reduction constant is in the LOW bits as 0x87):

   __m128i reduce(__m128i lo, __m128i hi) {
     // fold hi into lo
     __m128i p = _mm_set_epi32(0, 0, 0, 0x87);
     __m128i t = _mm_clmulepi64_si128(hi, p, 0x00); // only multiplies low 64 of hi!
     // need both halves.
   }

   Let's try the shift-xor reduction which uses no extra clmuls:
   For each bit of hi, xor (0x87 << k). That's equivalent to:
     lo ^= hi << 0 (the x^0 part of 0x87 which is bit 0, 1, 2, 7)
     i.e. lo ^= (hi) ^ (hi<<1) ^ (hi<<2) ^ (hi<<7)   but with the overflow of those
     shifts (bits past 127) folded the same way again.

   128-bit left shift by k (in reflected LSB=x^0 convention, << means toward higher powers,
   which is a left shift of the little-endian bit string, i.e. _mm_slli_epi64 plus carry between halves).
*/

static inline __m128i shl1(__m128i x) {
    __m128i c = _mm_srli_epi64(x, 63);
    __m128i s = _mm_slli_epi64(x, 1);
    /* carry from low 64 into high 64: c's low lane bit0 should go to high lane bit0 */
    c = _mm_slli_si128(c, 8);
    return _mm_or_si128(s, c);
}
static inline __m128i shl7(__m128i x) {
    /* shift left 7 */
    __m128i c = _mm_srli_epi64(x, 57);
    __m128i s = _mm_slli_epi64(x, 7);
    c = _mm_slli_si128(c, 8);
    return _mm_or_si128(s, c);
}
static inline __m128i shl128_overflow(__m128i x, int sh, __m128i *overflow) {
    /* return low 128 of (x << sh), and overflow = bits shifted past bit 127 (as low bits) */
    /* x is 128, sh is 1,2, or 7. overflow is sh bits. */
    if (sh == 1) {
        *overflow = _mm_srli_si128(_mm_srli_epi64(x, 63), 8); /* high lane's bit 63 -> low bit of overflow */
        /* wait high lane bit 63 is bit 127 of x. srli_epi64 by 63 puts it at bit 0 of high lane.
           srli_si128 by 8 moves high lane to low lane. So overflow low bit = bit 127. Good. */
        return shl1(x);
    }
    return x;
}

/* Direct: lo ^= hi ^ (hi<<1) ^ (hi<<2) ^ (hi<<7), then fold the bits that overflowed
   (at most 7 bits) the same way. */
static inline __m128i reduce_shift(__m128i lo, __m128i hi) {
    /* Compute (hi << k) for k=0,1,2,7 within 128 bits, and the overflow bits separately. */
    __m128i hi1_c = _mm_srli_epi64(hi, 63);
    __m128i hi1 = _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_slli_si128(hi1_c, 8));
    __m128i ov1 = _mm_srli_si128(hi1_c, 8); /* bit 127 -> bit 0 */

    __m128i hi2_c = _mm_srli_epi64(hi, 62);
    __m128i hi2 = _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_slli_si128(hi2_c, 8));
    __m128i ov2 = _mm_srli_si128(hi2_c, 8); /* bits 126-127 -> bits 0-1 */

    __m128i hi7_c = _mm_srli_epi64(hi, 57);
    __m128i hi7 = _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_slli_si128(hi7_c, 8));
    __m128i ov7 = _mm_srli_si128(hi7_c, 8);

    lo = _mm_xor_si128(lo, hi);
    lo = _mm_xor_si128(lo, hi1);
    lo = _mm_xor_si128(lo, hi2);
    lo = _mm_xor_si128(lo, hi7);

    __m128i ov = _mm_xor_si128(_mm_xor_si128(ov1, ov2), ov7);
    /* ov is at most 7 bits in the low byte of the low lane. Fold ov the same way:
       lo ^= ov ^ (ov<<1) ^ (ov<<2) ^ (ov<<7). ov<<7 fits in 14 bits, no second overflow. */
    __m128i ov1s = _mm_slli_epi64(ov, 1);
    __m128i ov2s = _mm_slli_epi64(ov, 2);
    __m128i ov7s = _mm_slli_epi64(ov, 7);
    lo = _mm_xor_si128(lo, ov);
    lo = _mm_xor_si128(lo, ov1s);
    lo = _mm_xor_si128(lo, ov2s);
    lo = _mm_xor_si128(lo, ov7s);
    return lo;
}

static inline __m128i gfmul_shift(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    __m128i hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
    return reduce_shift(lo, hi);
