/* 4-way aggregated GHASH: compute 
   state = (((state*H xor b0)*H xor b1)*H xor b2)*H xor b3)*H
         = state*H^4 xor b0*H^4 xor b1*H^3 xor b2*H^2 xor b3*H
   Precompute H, H^2, H^3, H^4.
   For streaming, do 4 independent clmuls then sum products then one reduction? 
   The sum of products before reduction: we can add (xor) the 256-bit products and reduce once.
*/
typedef struct { __m128i lo, hi; } prod256;

static inline void mul256(__m128i a, __m128i b, __m128i *lo, __m128i *hi) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    *lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    *hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
}

static __m128i ghash4(const unsigned char *data, size_t nblocks, __m128i H) {
    __m128i H2 = gfmul_shift(H, H);
    __m128i H3 = gfmul_shift(H2, H);
    __m128i H4 = gfmul_shift(H2, H2);
    __m128i state = _mm_setzero_si128();
    size_t i = 0;
    while (i + 4 <= nblocks) {
        __m128i b0 = bitrev(_mm_loadu_si128((const __m128i*)(data + (i+0)*16)));
        __m128i b1 = bitrev(_mm_loadu_si128((const __m128i*)(data + (i+1)*16)));
        __m128i b2 = bitrev(_mm_loadu_si128((const __m128i*)(data + (i+2)*16)));
        __m128i b3 = bitrev(_mm_loadu_si128((const __m128i*)(data + (i+3)*16)));
        /* (state xor b0)*H^4 xor b1*H^3 xor b2*H^2 xor b3*H */
        __m128i l0,h0,l1,h1,l2,h2,l3,h3;
        mul256(_mm_xor_si128(state, b0), H4, &l0, &h0);
        mul256(b1, H3, &l1, &h1);
        mul256(b2, H2, &l2, &h2);
        mul256(b3, H, &l3, &h3);
        __m128i lo = _mm_xor_si128(_mm_xor_si128(l0, l1), _mm_xor_si128(l2, l3));
        __m128i hi = _mm_xor_si128(_mm_xor_si128(h0, h1), _mm_xor_si128(h2, h3));
        state = reduce_shift(lo, hi);
        i += 4;
    }
    while (i < nblocks) {
        __m128i x = bitrev(_mm_loadu_si128((const __m128i*)(data + i*16)));
        state = gfmul_shift(_mm_xor_si128(state, x), H);
        i++;
    }
