}

static __m128i ghash1(const unsigned char *data, size_t nblocks, __m128i H) {
    __m128i state = _mm_setzero_si128();
    for (size_t i = 0; i < nblocks; i++) {
        __m128i x = bitrev(_mm_loadu_si128((const __m128i*)(data + i*16)));
