        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
}

static void pool_init(int n) {
    if (POOL_INIT) return;
    pthread_mutex_lock(&POOL_MU);
    if (!POOL_INIT) {
        for (int i = 0; i < MAX_THREADS; i++) {
            pthread_mutex_init(&POOL[i].mu, NULL);
            pthread_cond_init(&POOL[i].cv, NULL);
            POOL[i].has_work = 0;
            POOL[i].stop = 0;
            POOL[i].done = 0;
            POOL[i].index = i;
            pthread_create(&POOL[i].thread, NULL, pool_worker, &POOL[i]);
        }
        POOL_INIT = 1;
    }
    pthread_mutex_unlock(&POOL_MU);
    (void)n;
}

static void pool_run(job_t *jobs, int n) {
    pool_init(n);
    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&POOL[i].mu);
        POOL[i].job = &jobs[i];
        POOL[i].done = 0;
        POOL[i].has_work = 1;
        pthread_cond_signal(&POOL[i].cv);
        pthread_mutex_unlock(&POOL[i].mu);
