    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&POOL[i].mu);
        while (!POOL[i].done) pthread_cond_wait(&POOL[i].cv, &POOL[i].mu);
        pthread_mutex_unlock(&POOL[i].mu);
    }
}
