static inline __m128i aes128_assist(__m128i t1, __m128i t2){
    __m128i t3; t2=_mm_shuffle_epi32(t2,0xff);
    t3=_mm_slli_si128(t1,4); t1=_mm_xor_si128(t1,t3);
