typedef struct { __m128i rk[11]; } ak_t;
static void expand(const unsigned char *k, ak_t *o){
    __m128i t=_mm_loadu_si128((const __m128i*)k); o->rk[0]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x01)); o->rk[1]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x02)); o->rk[2]=t;
