    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x08)); o->rk[4]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x10)); o->rk[5]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x20)); o->rk[6]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x40)); o->rk[7]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x80)); o->rk[8]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x1b)); o->rk[9]=t;
    t=aes128_assist(t,_mm_aeskeygenassist_si128(t,0x36)); o->rk[10]=t;
}

static const unsigned char REV_TBL[16] __attribute__((aligned(16))) = {
    0x0,0x8,0x4,0xc,0x2,0xa,0x6,0xe,0x1,0x9,0x5,0xd,0x3,0xb,0x7,0xf
};
static inline __m128i bitrev(__m128i x) {
    __m128i t = _mm_load_si128((const __m128i*)REV_TBL);
    __m128i lo = _mm_and_si128(x, _mm_set1_epi8(0x0f));
    __m128i hi = _mm_and_si128(_mm_srli_epi16(x, 4), _mm_set1_epi8(0x0f));
    lo = _mm_shuffle_epi8(t, lo);
    hi = _mm_shuffle_epi8(t, hi);
    return _mm_or_si128(_mm_slli_epi16(lo, 4), hi);
}
static inline void mul256(__m128i a, __m128i b, __m128i *lo, __m128i *hi) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    *lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    *hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
}
static inline __m128i reduce_shift(__m128i lo, __m128i hi) {
    __m128i c1 = _mm_srli_epi64(hi, 63);
    __m128i c2 = _mm_srli_epi64(hi, 62);
    __m128i c7 = _mm_srli_epi64(hi, 57);
    __m128i hi1 = _mm_or_si128(_mm_slli_epi64(hi, 1), _mm_slli_si128(c1, 8));
    __m128i hi2 = _mm_or_si128(_mm_slli_epi64(hi, 2), _mm_slli_si128(c2, 8));
    __m128i hi7 = _mm_or_si128(_mm_slli_epi64(hi, 7), _mm_slli_si128(c7, 8));
    lo = _mm_xor_si128(lo, hi);
    lo = _mm_xor_si128(lo, hi1);
    lo = _mm_xor_si128(lo, hi2);
    lo = _mm_xor_si128(lo, hi7);
    __m128i ov = _mm_xor_si128(_mm_srli_si128(c1, 8), _mm_xor_si128(_mm_srli_si128(c2, 8), _mm_srli_si128(c7, 8)));
    lo = _mm_xor_si128(lo, ov);
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 1));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 2));
    lo = _mm_xor_si128(lo, _mm_slli_epi64(ov, 7));
