}
static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i lo, hi; mul256(a,b,&lo,&hi); return reduce_shift(lo, hi);
}

#define W 8
typedef struct {
    __m128i Hpow[W+1]; /* Hpow[1]=H ... Hpow[W]=H^W reflected */
} gctx;

static void gctx_init(gctx *g, __m128i H) {
    g->Hpow[1] = H;
    for (int i = 2; i <= W; i++) g->Hpow[i] = gfmul(g->Hpow[i-1], H);
}

/* Fused CTR+GHASH over full blocks. Returns reflected GHASH state of the ciphertext blocks
   (as if starting from 0). */
static __m128i ctr_ghash(const ak_t *k, const gctx *g,
                         const unsigned char *pt, unsigned char *ct,
                         size_t nblocks, uint32_t counter, const unsigned char nonce[12]) {
    unsigned char nb[16];
    memcpy(nb, nonce, 12);
    const __m128i *rk = k->rk;
    __m128i state = _mm_setzero_si128();
    size_t i = 0;
    while (i + W <= nblocks) {
        __m128i ks[W];
        for (int j = 0; j < W; j++) {
            uint32_t cv = counter + j;
            nb[12]=(unsigned char)(cv>>24); nb[13]=(unsigned char)(cv>>16);
            nb[14]=(unsigned char)(cv>>8); nb[15]=(unsigned char)cv;
            ks[j] = _mm_loadu_si128((const __m128i*)nb);
        }
        counter += W;
        for (int j = 0; j < W; j++) ks[j] = _mm_xor_si128(ks[j], rk[0]);
        for (int r = 1; r <= 9; r++)
            for (int j = 0; j < W; j++) ks[j] = _mm_aesenc_si128(ks[j], rk[r]);
        for (int j = 0; j < W; j++) ks[j] = _mm_aesenclast_si128(ks[j], rk[10]);

        __m128i x[W];
        for (int j = 0; j < W; j++) {
            __m128i p = _mm_loadu_si128((const __m128i*)(pt + (i+j)*16));
            __m128i c = _mm_xor_si128(p, ks[j]);
            _mm_storeu_si128((__m128i*)(ct + (i+j)*16), c);
            x[j] = bitrev(c);
        }
        /* state = (state xor x0)*H^W xor x1*H^{W-1} xor ... xor x_{W-1}*H */
        __m128i lo = _mm_setzero_si128(), hi = _mm_setzero_si128();
        x[0] = _mm_xor_si128(x[0], state);
        for (int j = 0; j < W; j++) {
            __m128i l, h;
            mul256(x[j], g->Hpow[W-j], &l, &h);
            lo = _mm_xor_si128(lo, l);
            hi = _mm_xor_si128(hi, h);
        }
        state = reduce_shift(lo, hi);
        i += W;
    }
    while (i < nblocks) {
        uint32_t cv = counter++;
        nb[12]=(unsigned char)(cv>>24); nb[13]=(unsigned char)(cv>>16);
        nb[14]=(unsigned char)(cv>>8); nb[15]=(unsigned char)cv;
        __m128i ks = _mm_xor_si128(_mm_loadu_si128((const __m128i*)nb), rk[0]);
        for (int r = 1; r <= 9; r++) ks = _mm_aesenc_si128(ks, rk[r]);
        ks = _mm_aesenclast_si128(ks, rk[10]);
        __m128i c = _mm_xor_si128(_mm_loadu_si128((const __m128i*)(pt + i*16)), ks);
        _mm_storeu_si128((__m128i*)(ct + i*16), c);
        state = gfmul(_mm_xor_si128(state, bitrev(c)), g->Hpow[1]);
        i++;
    }
    return state;
}

#define NT 4
typedef struct {
