#define POOL_N 4
static PyObject *CT_POOL[POOL_N];
static PyObject *TAG_POOL[POOL_N];
static Py_ssize_t CT_POOL_LEN[POOL_N];
static int POOL_I = 0;

static PyObject *py_encrypt_pooled(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad))
        return NULL;
    if (key.len != 16 || nonce.len != 12) {
        PyErr_SetString(PyExc_ValueError, "unsupported");
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (PyTuple_GET_SIZE(args) >= 4) PyBuffer_Release(&aad);
        return NULL;
