    int i = POOL_I;
    POOL_I = (POOL_I + 1) % POOL_N;
    if (CT_POOL[i] == NULL || CT_POOL_LEN[i] != pt.len) {
        Py_XDECREF(CT_POOL[i]);
        CT_POOL[i] = PyBytes_FromStringAndSize(NULL, pt.len);
