/* SHA-256, 8-way interleaved (AVX2), public-domain style compact impl.
   Processes 8 independent messages in parallel. For a single message we
   instead use a 4-block parallel? We'll do single-stream with AVX2 for
   message schedule + scalar compress, and also an 8-lane version for
   benchmarking independent hashes. */
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t be32(const uint8_t *p){
    return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];
}

static void sha256_block(uint32_t st[8], const uint8_t blk[64]){
    uint32_t w[64];
    for(int i=0;i<16;i++) w[i]=be32(blk+4*i);
    for(int i=16;i<64;i++){
        uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>3);
        uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for(int i=0;i<64;i++){
        uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
        uint32_t ch = (e&f) ^ (~e&g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t n = len/64;
    for(size_t i=0;i<n;i++) sha256_block(st, data+i*64);
    uint8_t tail[128];
    size_t rem = len%64;
    memcpy(tail, data+n*64, rem);
    tail[rem]=0x80;
    size_t pad = (rem<56)? 64 : 128;
    memset(tail+rem+1, 0, pad-rem-1);
    uint64_t bits = (uint64_t)len*8;
    for(int i=0;i<8;i++) tail[pad-1-i] = (uint8_t)(bits>>(8*i));
    sha256_block(st, tail);
    if(pad==128) sha256_block(st, tail+64);
    for(int i=0;i<8;i++){
        out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i];
    }
}

/* AVX2 message schedule for a single block, compress still scalar.
   This mainly tests whether AVX2 schedule helps. */
static inline __m256i rotr_epi32(__m256i x, int n){
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}

/* 4-way parallel SHA-256 (4 independent messages), AVX2.
   Used to measure peak throughput if we could split. */
typedef struct { __m256i v; } v32;

static inline __m256i load_be4(const uint8_t *p0, const uint8_t *p1, const uint8_t *p2, const uint8_t *p3, int off){
    /* load one big-endian word from each of 4 streams */
    uint32_t a = be32(p0+off), b=be32(p1+off), c=be32(p2+off), d=be32(p3+off);
    return _mm256_set_epi32(0,0,0,0, d,c,b,a); /* only low 128 used? we'll use 4 lanes in low via setr */
}

/* redo with 4 lanes in a __m128i? We want 8-wide for AVX2. Use 8 streams. */
static void sha256x8_blocks(uint32_t st[8][8], const uint8_t *blk[8]){
    __m256i w[64];
    for(int i=0;i<16;i++){
        uint32_t t[8];
        for(int l=0;l<8;l++) t[l]=be32(blk[l]+4*i);
        w[i] = _mm256_set_epi32(t[7],t[6],t[5],t[4],t[3],t[2],t[1],t[0]);
    }
    for(int i=16;i<64;i++){
        __m256i w15=w[i-15], w2=w[i-2];
        __m256i s0 = _mm256_xor_si256(rotr_epi32(w15,7), _mm256_xor_si256(rotr_epi32(w15,18), _mm256_srli_epi32(w15,3)));
        __m256i s1 = _mm256_xor_si256(rotr_epi32(w2,17), _mm256_xor_si256(rotr_epi32(w2,19), _mm256_srli_epi32(w2,10)));
        w[i] = _mm256_add_epi32(_mm256_add_epi32(w[i-16], s0), _mm256_add_epi32(w[i-7], s1));
    }
    __m256i a,b,c,d,e,f,g,h;
    #define LOAD(idx) _mm256_set_epi32(st[7][idx],st[6][idx],st[5][idx],st[4][idx],st[3][idx],st[2][idx],st[1][idx],st[0][idx])
    a=LOAD(0); b=LOAD(1); c=LOAD(2); d=LOAD(3); e=LOAD(4); f=LOAD(5); g=LOAD(6); h=LOAD(7);
    #undef LOAD
    for(int i=0;i<64;i++){
        __m256i S1 = _mm256_xor_si256(rotr_epi32(e,6), _mm256_xor_si256(rotr_epi32(e,11), rotr_epi32(e,25)));
        __m256i ch = _mm256_xor_si256(_mm256_and_si256(e,f), _mm256_andnot_si256(e,g));
        __m256i ki = _mm256_set1_epi32(K[i]);
        __m256i t1 = _mm256_add_epi32(h, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(ki, w[i]))));
        __m256i S0 = _mm256_xor_si256(rotr_epi32(a,2), _mm256_xor_si256(rotr_epi32(a,13), rotr_epi32(a,22)));
        __m256i maj = _mm256_xor_si256(_mm256_and_si256(a,b), _mm256_xor_si256(_mm256_and_si256(a,c), _mm256_and_si256(b,c)));
        __m256i t2 = _mm256_add_epi32(S0, maj);
        h=g; g=f; f=e; e=_mm256_add_epi32(d,t1); d=c; c=b; b=a; a=_mm256_add_epi32(t1,t2);
    }
    uint32_t tmp[8];
    #define STORE(reg, idx) do{ _mm256_storeu_si256((__m256i*)tmp, reg); for(int l=0;l<8;l++) st[l][idx]+=tmp[l]; }while(0)
    STORE(a,0); STORE(b,1); STORE(c,2); STORE(d,3); STORE(e,4); STORE(f,5); STORE(g,6); STORE(h,7);
    #undef STORE
}

int main(){
    size_t n = 20000*1024;
    /* make multiple of 64 for fair block throughput, then compare */
    uint8_t *data = aligned_alloc(64, n);
    memset(data, 0x5a, n);
    uint8_t out[32];
    sha256(data, n, out);
    int iters=3;
    struct timespec a,b;
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++) sha256(data,n,out);
    clock_gettime(CLOCK_MONOTONIC,&b);
    double ms = ((b.tv_sec-a.tv_sec)*1000.0 + (b.tv_nsec-a.tv_nsec)/1e6)/iters;
    printf("scalar sha256 %.2f ms digest %02x%02x%02x%02x\n", ms, out[0],out[1],out[2],out[3]);

    /* 8-way: 8 independent buffers of n/8 */
    size_t m = n; /* each stream full size would be 8x work; instead each is n bytes, measure per-byte */
    uint8_t *bufs[8];
    for(int i=0;i<8;i++){ bufs[i]=aligned_alloc(64, m+64); memset(bufs[i], 0x5a+i, m); }
    size_t blocks = m/64;
    uint32_t st[8][8];
    const uint8_t *bp[8];
    /* warmup */
    for(int l=0;l<8;l++){
        uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        memcpy(st[l], iv, 32);
    }
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int l=0;l<8;l++){
        uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        memcpy(st[l], iv, 32);
    }
    for(size_t i=0;i<blocks;i++){
        for(int l=0;l<8;l++) bp[l]=bufs[l]+i*64;
        sha256x8_blocks(st, bp);
    }
    clock_gettime(CLOCK_MONOTONIC,&b);
    ms = (b.tv_sec-a.tv_sec)*1000.0 + (b.tv_nsec-a.tv_nsec)/1e6;
    double mb = (8.0*m)/(1024.0*1024.0);
    printf("avx2 x8: %.2f ms for %.1f MB => %.1f MB/s\n", ms, mb, mb/(ms/1000.0));
    return 0;
}
EOF
clang -O3 -mavx2 -mbmi2 -o avx2_sha avx2_sha.c && ./avx2_sha"}

