/* AVX2 single-stream: vectorize message schedule (8 words at a time) and
   keep state scalar. Also software-pipeline the schedule ahead of compress. */

static inline __m256i rotr(__m256i x, int n){
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}
static inline __m256i sigma0(__m256i x){
    return _mm256_xor_si256(rotr(x,7), _mm256_xor_si256(rotr(x,18), _mm256_srli_epi32(x,3)));
}
static inline __m256i sigma1(__m256i x){
    return _mm256_xor_si256(rotr(x,17), _mm256_xor_si256(rotr(x,19), _mm256_srli_epi32(x,10)));
}

static inline uint32_t ror32(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

static void block_avx2(uint32_t st[8], const uint8_t *blk){
    __m256i w[8];
    /* load 64 bytes, byte-swap words */
    const __m256i shuf = _mm256_set_epi8(
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3,
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    __m128i lo = _mm_loadu_si128((const __m128i*)blk);
    __m128i hi = _mm_loadu_si128((const __m128i*)(blk+16));
    __m256i v0 = _mm256_set_m128i(hi, lo);
    lo = _mm_loadu_si128((const __m128i*)(blk+32));
    hi = _mm_loadu_si128((const __m128i*)(blk+48));
    __m256i v1 = _mm256_set_m128i(hi, lo);
    w[0] = _mm256_shuffle_epi8(v0, shuf);
    w[1] = _mm256_shuffle_epi8(v1, shuf);

    /* expand rest. w[i] holds words 8*i .. 8*i+7 */
    for(int i=2;i<8;i++){
        /* Need w[i] = f(w[i-2], w[i-1], ...) — dependency spans 2 vectors.
           Compute word-by-word via alignr is fiddly; do scalar expansion into w
           for correctness first, vector compress later. */
    }
    uint32_t ws[64];
    _mm256_storeu_si256((__m256i*)ws, w[0]);
    _mm256_storeu_si256((__m256i*)(ws+8), w[1]);
    for(int i=16;i<64;i++){
        uint32_t x = ws[i-15];
        uint32_t s0 = ror32(x,7)^ror32(x,18)^(x>>3);
        x = ws[i-2];
        uint32_t s1 = ror32(x,17)^ror32(x,19)^(x>>10);
        ws[i] = ws[i-16] + s0 + ws[i-7] + s1;
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for(int i=0;i<64;i++){
        uint32_t S1 = ror32(e,6)^ror32(e,11)^ror32(e,25);
        uint32_t ch = (e&f) ^ (~e&g);
        uint32_t t1 = h + S1 + ch + K[i] + ws[i];
        uint32_t S0 = ror32(a,2)^ror32(a,13)^ror32(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t n = len/64;
    for(size_t i=0;i<n;i++) block_avx2(st, data+i*64);
    uint8_t tail[128];
    size_t rem = len%64;
    memcpy(tail, data+n*64, rem);
    tail[rem]=0x80;
    size_t pad = (rem<56)?64:128;
    memset(tail+rem+1, 0, pad-rem-1);
    uint64_t bits = (uint64_t)len*8;
    for(int i=0;i<8;i++) tail[pad-1-i]=(uint8_t)(bits>>(8*i));
    block_avx2(st, tail);
    if(pad==128) block_avx2(st, tail+64);
    for(int i=0;i<8;i++){ out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i]; }
}

int main(){
    size_t n=20000*1024;
    uint8_t *data=aligned_alloc(64,n);
    memset(data,0x5a,n);
    uint8_t out[32];
    sha256(data,n,out);
    struct timespec a,b; int iters=3;
    clock_gettime(CLOCK_MONOTONIC,&a);
    for(int i=0;i<iters;i++) sha256(data,n,out);
    clock_gettime(CLOCK_MONOTONIC,&b);
    double ms=((b.tv_sec-a.tv_sec)*1000.0+(b.tv_nsec-a.tv_nsec)/1e6)/iters;
    printf("avx2-sched scalar-compress %.2f ms %02x%02x%02x%02x\n", ms, out[0],out[1],out[2],out[3]);
    return 0;
}
EOF
