#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cstdlib>

// Auction algorithm for dense assignment, returns assignment of rows to cols.
// Based on Bertsekas auction. For integer-ish costs scaled.

extern "C" {

// Solve min cost assignment. M is n x n row-major double.
// out_assign[i] = column assigned to row i.
// Returns 0 on success.
int auction_assign(const double* M, int n, int* out_assign, double eps_final, int max_iter) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);      // owner of column
    std::vector<int> assign(n, -1);     // assignment of row
    std::vector<double> bid(n);
    std::vector<int> bidder(n);

    // scale: work with original doubles, epsilon schedule
    double maxc = 0;
    for (int i = 0; i < n*n; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 4.0;
    if (eps < eps_final) eps = eps_final;

    int iter = 0;
    while (eps >= eps_final * 0.999) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int unassigned = n;
        std::vector<int> free_rows(n);
        std::iota(free_rows.begin(), free_rows.end(), 0);

        int guard = 0;
        while (unassigned > 0 && guard < max_iter) {
            guard++;
            iter++;
            // each free row bids
            std::fill(bid.begin(), bid.end(), -1e300);
            std::fill(bidder.begin(), bidder.end(), -1);
            std::vector<int> next_free;
            next_free.reserve(unassigned);

            for (int r : free_rows) {
                const double* row = M + (size_t)r * n;
                // find best and second best value = -cost - price? 
                // We minimize cost, so benefit = -M
                int best_j = 0;
                double best_val = -1e300, second_val = -1e300;
                for (int j = 0; j < n; j++) {
                    double val = -row[j] - price[j];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best_j = j;
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
                double b = price[best_j] + (best_val - second_val) + eps;
                // store highest bid for column
                if (b > bid[best_j]) {
                    bid[best_j] = b;
                    bidder[best_j] = r;
                }
            }
            // assign
            free_rows.clear();
            for (int j = 0; j < n; j++) {
                if (bidder[j] >= 0) {
                    int r = bidder[j];
                    int prev = owner[j];
                    if (prev >= 0) {
                        assign[prev] = -1;
                        free_rows.push_back(prev);
                    }
                    owner[j] = r;
                    assign[r] = j;
                    price[j] = bid[j];
                }
            }
            unassigned = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) unassigned++;
            // rebuild free_rows if not tracked perfectly (because multiple bidders only one wins, losers not in prev)
            // Actually losers who bid but weren't highest are still free and not pushed. Need to recompute.
            free_rows.clear();
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows.push_back(i);
            if (guard > max_iter) break;
        }
        if (unassigned > 0) {
            // failed at this eps
            return -1;
        }
        eps *= 0.25;
        if (eps < eps_final) break;
    }
    for (int i = 0; i < n; i++) out_assign[i] = assign[i];
    return iter;
}

}
