extern "C" {

// Min-cost assignment via Bertsekas auction (forward auction, epsilon scaling).
// M: n*n row-major costs. out_assign[i] = column for row i.
// Returns iteration count, or -1 on failure.
int auction_assign(const double* M, int n, int* out_assign, double eps_final) {
    std::vector<double> price(n, 0.0);
    std::vector<int> assign(n, -1);
    std::vector<int> owner(n, -1);
    std::vector<double> high_bid(n);
    std::vector<int> high_bidder(n);
    std::vector<int> free_rows(n);

    double maxc = 0.0;
    size_t nn = (size_t)n * n;
    for (size_t i = 0; i < nn; i++) if (M[i] > maxc) maxc = M[i];
    double eps = maxc / 2.0;
    if (eps < eps_final) eps = eps_final;

    int total_iter = 0;

    while (true) {
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int nfree = n;

        int guard = 0;
        int guard_max = n * 100 + 10000;
        while (nfree > 0 && guard < guard_max) {
            guard++;
            total_iter++;
            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);

            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                const double* row = M + (size_t)r * n;
                int best_j = 0;
                double best_val = -1e300, second_val = -1e300;
                for (int j = 0; j < n; j++) {
                    double val = -row[j] - price[j];
                    if (val > best_val) {
                        second_val = best_val;
                        best_val = val;
                        best_j = j;
                    } else if (val > second_val) {
                        second_val = val;
                    }
                }
                double b = price[best_j] + (best_val - second_val) + eps;
                if (b > high_bid[best_j]) {
                    high_bid[best_j] = b;
                    high_bidder[best_j] = r;
                }
            }

            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r;
                assign[r] = j;
                price[j] = high_bid[j];
            }

            nfree = 0;
            for (int i = 0; i < n; i++) {
                if (assign[i] < 0) free_rows[nfree++] = i;
            }
        }
        if (nfree > 0) return -1;

        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; i++) out_assign[i] = assign[i];
    return total_iter;
}

}
