// Jonker-Volgenant algorithm for dense linear assignment (min cost).
// Adapted from the classic LAPJV description (Jonker & Volgenant 1987).
#include <vector>
#include <cstring>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <limits>

extern "C" {

int lapjv(const double* cost, int n, int* rowsol) {
    const double INF = 1e100;
    std::vector<int> colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> pred(n);
    std::vector<double> d(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);
    std::vector<char> unique(n, 1);

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            unique[imin] = 0;
            free_rows.push_back(imin); // may duplicate; fix later
        }
    }
    // unique free rows
    {
        std::vector<int> fr;
        std::vector<char> seen(n, 0);
        for (int i = 0; i < n; ++i) if (rowsol[i] == -1 && !seen[i]) { seen[i]=1; fr.push_back(i); }
        free_rows.swap(fr);
    }

    // reduction transfer
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] != -1 && unique[i]) {
            int j1 = rowsol[i];
            double minv = INF;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double red = cost[(size_t)i * n + j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    // augmenting row reduction
    int loopcnt = 0;
    for (int f = 0; f < 2; ++f) {
        int k = 0;
        int end = (int)free_rows.size();
        while (k < end) {
            int i = free_rows[k];
            k++;
            loopcnt++;
            double umin = cost[(size_t)i * n] - v[0];
            int j1 = 0;
            double usub = INF;
            int j2 = -1;
            for (int j = 1; j < n; ++j) {
