// Jonker-Volgenant dense LAP, min-cost.
// Structure follows the public-domain implementation used by scipy/py-lapsolver lineage.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

static const double LARGE = 1e100;

extern "C" int lapjv_solve(const double* cost, int n, int* rowsol) {
    std::vector<int> colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> pred(n, -1);
    std::vector<double> d(n);
    std::vector<int> cols(n);
    std::vector<char> scanned(n);

    // initialize rowsol to -1
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        int imin = 0;
        double minv = cost[j];
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1; // not taken uniquely yet; mark free column later
        }
    }

    // REDUCTION TRANSFER + build free lists via unique matching from col reduction
    // Recompute: columns with colsol set are matched.
    std::vector<int> freerows;
    freerows.reserve(n);
    std::vector<char> matched_row(n, 0);
    for (int j = 0; j < n; ++j) if (colsol[j] >= 0) matched_row[colsol[j]] = 1;
    for (int i = 0; i < n; ++i) {
        if (!matched_row[i]) freerows.push_back(i);
        else {
            // reduction transfer for uniquely matched rows
            int j1 = rowsol[i];
            double minv = LARGE;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double red = cost[(size_t)i * n + j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        }
    }

    auto augment = [&](int free_i) -> bool {
        // Dijkstra from free row free_i on equality graph of reduced costs
        for (int j = 0; j < n; ++j) {
            d[j] = cost[(size_t)free_i * n + j] - v[j];
            pred[j] = free_i;
            scanned[j] = 0;
        }
        int last_j = -1;
        double last_d = 0;
        int ready = 0; // number of columns in the "low" set — we scan linearly (n=600, fine)
        // Use a simple O(n^2) Dijkstra (no heap) which is fine and clear.
        while (true) {
            double mn = LARGE;
            int jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && d[j] < mn) { mn = d[j]; jmin = j; }
            if (jmin < 0) return false;
            scanned[jmin] = 1;
            last_d = mn;
            int i0 = colsol[jmin];
            if (i0 < 0) { last_j = jmin; break; }
            // relax through matched row i0
            double base = cost[(size_t)i0 * n + jmin] - v[jmin];
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double val = cost[(size_t)i0 * n + j] - v[j] - base + mn;
                if (val < d[j]) { d[j] = val; pred[j] = i0; }
            }
        }
        // update dual variables
        u[free_i] = last_d; // not strictly needed
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) {
                v[j] += d[j] - last_d; // wait: columns on path should increase price?
                // Reduced costs: we want v'[j] = v[j] - (last_d - d[j]) for scanned j != last? 
                // Standard: for every scanned column, v[j] -= (min_d_unscanned - d[j]) but since we stopped, delta = last_d.
                // The columns in the scanned set (including the free column) get v decreased by (last_d - d[j]).
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] -= (last_d - d[j]);
        // augment along pred
        int j = last_j;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jnext = rowsol[i];
            rowsol[i] = j;
            if (i == free_i) break;
            j = jnext;
        }
        return true;
    };

    for (int fr : freerows) {
        if (!augment(fr)) return -1;
    }
    // verify all assigned
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -2;
    return 0;
}
