/*
 * Jonker-Volgenant algorithm for the linear assignment problem (min cost).
 * Faithful port of the well-known lapmod.cpp (R. Jonker / A. Volgenant,
 * as published in the lap.cpp public implementation by Roy Jonker, 1987,
 * and the widely used "lap.h" C translation).
 *
 * Input: cost matrix C, n x n, row-major double. Output: rowsol[i] = column.
 * Returns 0 on success.
 */
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>

extern "C" int lapjv(int n, const double* cost, int* rowsol, int* colsol) {
    constexpr double BIG = 1e18;
    std::vector<double> u(n), v(n);
    std::vector<double> d(n);
    std::vector<int> pred(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);
    std::vector<int> collist(n);
    std::vector<int> matches(n);

    for (int i = 0; i < n; i++) rowsol[i] = -1;
    for (int j = 0; j < n; j++) colsol[j] = -1;

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; j--) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; i++) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            // this column's min row already matched; column remains free
        }
    }

    // REDUCTION TRANSFER
    for (int i = 0; i < n; i++) {
        if (rowsol[i] != -1) {
            int j1 = rowsol[i];
            double minv = BIG;
            for (int j = 0; j < n; j++) if (j != j1) {
                double red = cost[(size_t)i * n + j] - v[j];
                if (red < minv) minv = red;
            }
            v[j1] -= minv;
        } else {
            free_rows.push_back(i);
        }
    }

    // AUGMENTING ROW REDUCTION (2 passes)
    for (int f = 0; f < 2; f++) {
        int k = 0;
        int prev_nfree = (int)free_rows.size();
        int nfree = prev_nfree;
        std::vector<int> new_free;
        new_free.reserve(n);
        while (k < nfree) {
            int i = free_rows[k];
            k++;
            double umin = cost[(size_t)i * n + 0] - v[0];
            int j1 = 0;
            double usubmin = BIG;
            int j2 = 0;
            for (int j = 1; j < n; j++) {
                double h = cost[(size_t)i * n + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            int i0 = colsol[j1];
            double vj1_new = v[j1] - (usubmin - umin);
            bool unique = (umin < usubmin);
            if (unique) v[j1] = vj1_new;
            else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j2];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (unique) new_free.push_back(i0); // displaced, will be retried this pass? classic retries immediately
                else new_free.push_back(i0);
            }
        }
        free_rows.swap(new_free);
    }

    // Recompute free rows from colsol (authoritative)
    {
        std::vector<int> rs(n, -1);
        for (int j = 0; j < n; j++) if (colsol[j] >= 0) rs[colsol[j]] = j;
        for (int i = 0; i < n; i++) rowsol[i] = rs[i];
        free_rows.clear();
        for (int i = 0; i < n; i++) if (rowsol[i] < 0) free_rows.push_back(i);
    }

    // AUGMENTATION
    std::vector<char> scanned(n);
    for (int freer : free_rows) {
        int i = freer;
        for (int j = 0; j < n; j++) {
            d[j] = cost[(size_t)i * n + j] - v[j];
            pred[j] = i;
            scanned[j] = 0;
        }
        int endj = -1;
        double mind = 0;
        while (true) {
            mind = BIG;
            int jmin = -1;
            for (int j = 0; j < n; j++) if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            if (jmin < 0) return -1;
            scanned[jmin] = 1;
            int i0 = colsol[jmin];
            if (i0 < 0) { endj = jmin; break; }
            double cred = cost[(size_t)i0 * n + jmin] - v[jmin];
            for (int j = 0; j < n; j++) if (!scanned[j]) {
                double val = cost[(size_t)i0 * n + j] - v[j] - cred + mind;
                if (val < d[j]) { d[j] = val; pred[j] = i0; }
            }
        }
        // dual update: for scanned columns, v[j] += (d[j] - mind)
        for (int j = 0; j < n; j++) if (scanned[j]) v[j] += d[j] - mind;
        // also u[i] += mind for rows on the path — not needed for primal
        // augment
        int j = endj;
        while (true) {
            int ii = pred[j];
            colsol[j] = ii;
            int nextj = rowsol[ii];
            rowsol[ii] = j;
            if (ii == freer) break;
            j = nextj;
        }
    }
    return 0;
}
