// LAPJV-style successive shortest paths with a binary heap (O(n^2 log n)).
// Min-cost assignment. cost is n*n row-major.
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <queue>
#include <cmath>

extern "C" int lap_heap(int n, const double* cost, int* rowsol) {
    const double INF = 1e100;
    std::vector<int> colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);

    for (int i = 0; i < n; i++) rowsol[i] = -1;

    // init dual v[j] = min_i cost[i,j], greedy match
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) { rowsol[imin] = j; colsol[j] = imin; }
    }
    // reduction transfer
    for (int i = 0; i < n; i++) if (rowsol[i] >= 0) {
        int j1 = rowsol[i];
        double minv = INF;
        for (int j = 0; j < n; j++) if (j != j1) {
            double red = cost[(size_t)i * n + j] - v[j];
            if (red < minv) minv = red;
        }
        v[j1] -= minv;
    }

    using P = std::pair<double, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    for (int start = 0; start < n; ++start) {
        if (rowsol[start] >= 0) continue;
        std::fill(d.begin(), d.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        while (!pq.empty()) pq.pop();
        for (int j = 0; j < n; j++) {
            d[j] = cost[(size_t)start * n + j] - u[start] - v[j];
            pred[j] = start;
            pq.emplace(d[j], j);
        }
        int endj = -1;
        double endd = 0;
        while (!pq.empty()) {
            auto [dist, j] = pq.top(); pq.pop();
            if (scanned[j]) continue;
            if (dist > d[j] + 1e-12) continue;
            scanned[j] = 1;
            int i0 = colsol[j];
            if (i0 < 0) { endj = j; endd = dist; break; }
            double base = cost[(size_t)i0 * n + j] - u[i0] - v[j];
            for (int jj = 0; jj < n; jj++) if (!scanned[jj]) {
                double val = dist + cost[(size_t)i0 * n + jj] - u[i0] - v[jj] - base;
                if (val + 1e-15 < d[jj]) {
                    d[jj] = val;
                    pred[jj] = i0;
                    pq.emplace(val, jj);
                }
            }
        }
        if (endj < 0) return -1;
        // dual update
        u[start] += endd;
        for (int j = 0; j < n; j++) if (scanned[j] && j != endj) {
            // row matched to j has potential increased
            int i0 = colsol[j];
            if (i0 >= 0) u[i0] += endd - d[j];
            v[j] -= endd - d[j];
        }
        v[endj] -= endd - d[endj];
        // augment
        int j = endj;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == start) break;
            j = nxt;
        }
    }
    return 0;
}
