// Successive shortest paths on a local candidate graph, with cost-threshold fallback.
// Candidates: k nearest columns per row (passed in). If augmentation fails, caller retries denser.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <queue>
#include <cstring>

extern "C" int lap_local(int n, int k, const int* cand_idx, const double* cand_cost, int* rowsol) {
    const double INF = 1e100;
    std::vector<int> colsol(n, -1);
    std::vector<double> pot_row(n, 0.0), pot_col(n, 0.0);
    std::vector<double> dist(n);
    std::vector<int> pred(n, -1);
    std::vector<char> seen(n);
    // reverse adjacency: for each column, rows that list it
    std::vector<std::vector<int>> col_rows(n);
    std::vector<std::vector<double>> col_costs(n);
    for (int i = 0; i < n; i++) {
        for (int t = 0; t < k; t++) {
            int j = cand_idx[(size_t)i * k + t];
            double c = cand_cost[(size_t)i * k + t];
            col_rows[j].push_back(i);
            col_costs[j].push_back(c);
        }
    }
    // also forward lookup: cost of (i,j) if candidate, else INF. Use map? For n=600 k~100, scan is ok.
    // Build per-row vector already given.

    auto edge_cost = [&](int i, int j) -> double {
        const int* idx = cand_idx + (size_t)i * k;
        const double* cc = cand_cost + (size_t)i * k;
        for (int t = 0; t < k; t++) if (idx[t] == j) return cc[t];
        return INF;
    };

    for (int i = 0; i < n; i++) rowsol[i] = -1;

    using P = std::pair<double, int>;

    for (int start = 0; start < n; start++) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        // init from start row's candidates
        const int* idx = cand_idx + (size_t)start * k;
        const double* cc = cand_cost + (size_t)start * k;
        for (int t = 0; t < k; t++) {
            int j = idx[t];
            double red = cc[t] - pot_row[start] - pot_col[j];
            if (red < dist[j]) {
                dist[j] = red;
                pred[j] = start;
                pq.emplace(red, j);
            }
        }
        int endj = -1;
        double endd = 0;
        while (!pq.empty()) {
            auto [dcur, j] = pq.top(); pq.pop();
            if (seen[j]) continue;
            if (dcur > dist[j] + 1e-12) continue;
            seen[j] = 1;
            if (colsol[j] < 0) { endj = j; endd = dcur; break; }
            int i0 = colsol[j];
            // relax edges from i0
            const int* idx2 = cand_idx + (size_t)i0 * k;
            const double* cc2 = cand_cost + (size_t)i0 * k;
            double base = edge_cost(i0, j);
            if (base >= INF/2) continue;
            double add = dcur - (base - pot_row[i0] - pot_col[j]);
            for (int t = 0; t < k; t++) {
                int jj = idx2[t];
                if (seen[jj]) continue;
                double val = cc2[t] - pot_row[i0] - pot_col[jj] + add;
                if (val + 1e-15 < dist[jj]) {
                    dist[jj] = val;
                    pred[jj] = i0;
                    pq.emplace(val, jj);
                }
            }
        }
        if (endj < 0) return -(start+1); // fail
        // dual update
        pot_row[start] += endd;
        for (int j = 0; j < n; j++) if (seen[j]) {
            double delta = endd - dist[j];
            pot_col[j] -= delta;
            int i0 = colsol[j];
            if (i0 >= 0) pot_row[i0] += delta;
        }
        // augment
        int j = endj;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == start) break;
            j = nxt;
        }
    }
    return 0;
}
