#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <omp.h>

// Parallel auction on row-candidate graph.
// cand_idx, cand_cost: n*k row-major.
extern "C" int auction_omp(const int* cand_idx, const double* cand_cost, int n, int k,
                           int* out_assign, double eps_final, int nthreads) {
    std::vector<double> price(n, 0.0);
    std::vector<int> assign(n, -1);
    std::vector<int> owner(n, -1);
    std::vector<double> high_bid(n);
    std::vector<int> high_bidder(n);
    std::vector<int> free_rows(n);
    std::vector<int> best_j(n);
    std::vector<double> bid_of_row(n);

    double maxc = 0.0;
    #pragma omp parallel for reduction(max:maxc) num_threads(nthreads)
    for (int i = 0; i < n * k; i++) if (cand_cost[i] > maxc) maxc = cand_cost[i];
    double eps = std::max(maxc / 2.0, eps_final);

    while (true) {
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int nfree = n;
        int guard = 0;
        int guard_max = n * 300;
        while (nfree > 0 && guard < guard_max) {
            guard++;
            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);

            #pragma omp parallel for num_threads(nthreads) schedule(static)
            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                const int* idx = cand_idx + (size_t)r * k;
                const double* cost = cand_cost + (size_t)r * k;
                int bj = idx[0];
                double best = -1e300, second = -1e300;
                for (int t = 0; t < k; t++) {
                    double val = -cost[t] - price[idx[t]];
                    if (val > best) { second = best; best = val; bj = idx[t]; }
                    else if (val > second) second = val;
                }
                if (second < -1e299) second = best - 1.0;
                best_j[r] = bj;
                bid_of_row[r] = price[bj] + (best - second) + eps;
            }
            // serial merge of bids (n=600, cheap)
            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                int j = best_j[r];
                double b = bid_of_row[r];
                if (b > high_bid[j]) { high_bid[j] = b; high_bidder[j] = r; }
            }
            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r;
                assign[r] = j;
                price[j] = high_bid[j];
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows[nfree++] = i;
        }
        if (nfree > 0) return -1;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; i++) out_assign[i] = assign[i];
    return 0;
}
