struct Ctx {
    const int* cand_idx;
    const double* cand_cost;
    const double* price;
    const int* free_rows;
    int nfree;
    int k;
    int* best_j;
    double* bid_of_row;
    int tid;
    int nthreads;
};

static void* worker(void* arg) {
    Ctx* c = (Ctx*)arg;
    for (int fi = c->tid; fi < c->nfree; fi += c->nthreads) {
        int r = c->free_rows[fi];
        const int* idx = c->cand_idx + (size_t)r * c->k;
        const double* cost = c->cand_cost + (size_t)r * c->k;
        int bj = idx[0];
        double best = -1e300, second = -1e300;
        for (int t = 0; t < c->k; t++) {
            double val = -cost[t] - c->price[idx[t]];
            if (val > best) { second = best; best = val; bj = idx[t]; }
            else if (val > second) second = val;
        }
        if (second < -1e299) second = best - 1.0;
        c->best_j[r] = bj;
        c->bid_of_row[r] = c->price[bj] + (best - second);
    }
    return nullptr;
}

