                              best_j.data(), bid_of_row.data(), t, nthreads};
                pthread_create(&threads[t], nullptr, worker, &ctxs[t]);
            }
            for (int t = 0; t < nthreads; t++) pthread_join(threads[t], nullptr);

            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);
            for (int fi = 0; fi < nfree; fi++) {
