                int j = best_j[r];
                double b = bid_of_row[r] + price[j] + eps;
                if (b > high_bid[j]) { high_bid[j] = b; high_bidder[j] = r; }
            }
            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r;
                assign[r] = j;
                price[j] = high_bid[j];
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows[nfree++] = i;
        }
        if (nfree > 0) return -1;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
