#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <queue>

// Fast assignment for uniform EMD:
// 1. Build k nearest candidates per row (partial select) in C++.
// 2. Run epsilon-scaling auction on that sparse graph.
// 3. If the resulting assignment cost is not certified (reduced costs), fall back? 
//    Caller checks; this just returns assignment.
//
// Tie-break: among equal costs, prefer smaller column index (stable partial_sort behavior
// is NOT lexicographic). We add a tiny index penalty inside the auction value comparison
// only for bidding, but costs used for optimality are original. For unique optima this
// doesn't matter.

struct Cand {
    double c;
    int j;
};

extern "C" int auction_from_dense(const double* M, int n, int k, int* out_assign, double eps_final) {
    // build candidates
    std::vector<int> idx((size_t)n * k);
    std::vector<double> cst((size_t)n * k);
    std::vector<Cand> buf(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) buf[j] = Cand{row[j], j};
        std::nth_element(buf.begin(), buf.begin() + k, buf.end(), [](const Cand& a, const Cand& b){ return a.c < b.c; });
        // sort the k for stability of nothing; keep as is
        for (int t = 0; t < k; t++) {
            idx[(size_t)i * k + t] = buf[t].j;
            cst[(size_t)i * k + t] = buf[t].c;
        }
    }

    std::vector<double> price(n, 0.0);
    std::vector<int> assign(n, -1), owner(n, -1);
    std::vector<double> high_bid(n, -1e300);
    std::vector<int> high_bidder(n, -1);
    std::vector<int> free_rows(n);
    std::vector<int> best_j(n);
    std::vector<double> bid_delta(n); // best-second

    double maxc = 0;
    for (double c : cst) if (c > maxc) maxc = c;
    double eps = std::max(maxc / 2.0, eps_final);

    while (true) {
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int nfree = n;
        int guard = 0;
        while (nfree && guard < n * 500) {
            guard++;
            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);
            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                const int* id = idx.data() + (size_t)r * k;
                const double* cs = cst.data() + (size_t)r * k;
                int bj = id[0];
                double best = -1e300, second = -1e300;
                for (int t = 0; t < k; t++) {
                    double val = -cs[t] - price[id[t]];
                    if (val > best) { second = best; best = val; bj = id[t]; }
                    else if (val > second) second = val;
                }
                if (second < -1e299) second = best - 1.0;
                double b = price[bj] + (best - second) + eps;
                if (b > high_bid[bj]) { high_bid[bj] = b; high_bidder[bj] = r; }
            }
            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r;
                assign[r] = j;
                price[j] = high_bid[j];
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows[nfree++] = i;
        }
        if (nfree) return -1;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; i++) out_assign[i] = assign[i];
    return 0;
}
