// Successive shortest paths with potentials, dense, binary heap + adjacency scan.
// Initializes a greedy partial matching then augments.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <queue>
#include <cstring>
#include <cmath>

extern "C" int ssp_assign(const double* M, int n, int* rowsol) {
    const double INF = 1e100;
    std::vector<int> colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    for (int i = 0; i < n; i++) rowsol[i] = -1;

    // v[j] = min over i of M[i,j]
    for (int j = 0; j < n; j++) {
        double mn = M[j];
        for (int i = 1; i < n; i++) mn = std::min(mn, M[(size_t)i*n + j]);
        v[j] = mn;
    }
    // greedy: assign rows in order to cheapest feasible reduced column
    for (int i = 0; i < n; i++) {
        int best = -1; double bv = INF;
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) if (colsol[j] < 0) {
            double red = row[j] - v[j];
            if (red < bv) { bv = red; best = j; }
        }
        if (best >= 0) { rowsol[i] = best; colsol[best] = i; u[i] = bv; }
    }

    using P = std::pair<double,int>;
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> seen(n);

    for (int start = 0; start < n; start++) {
        if (rowsol[start] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        const double* row = M + (size_t)start * n;
        for (int j = 0; j < n; j++) {
            dist[j] = row[j] - u[start] - v[j];
            pred[j] = start;
            pq.emplace(dist[j], j);
        }
        int endj = -1; double endd = 0;
        while (!pq.empty()) {
            auto [dcur, j] = pq.top(); pq.pop();
            if (seen[j]) continue;
            seen[j] = 1;
            if (colsol[j] < 0) { endj = j; endd = dcur; break; }
            int i0 = colsol[j];
            const double* row2 = M + (size_t)i0 * n;
            double base = row2[j] - u[i0] - v[j];
            double add = dcur - base;
            for (int jj = 0; jj < n; jj++) if (!seen[jj]) {
                double val = row2[jj] - u[i0] - v[jj] + add;
                if (val < dist[jj]) {
                    dist[jj] = val;
                    pred[jj] = i0;
                    pq.emplace(val, jj);
                }
            }
        }
        if (endj < 0) return -1;
        // dual update: for seen columns
        for (int j = 0; j < n; j++) if (seen[j]) {
            double delta = endd - dist[j];
            v[j] -= delta;
            int i0 = colsol[j];
            if (i0 >= 0) u[i0] += delta;
        }
        u[start] += endd;
        int j = endj;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == start) break;
            j = nxt;
        }
    }
    return 0;
}
