            for (int j = 0; j < n; j++) if (j != j1) {
                double h = row[j] - v[j];
                if (h < minv) minv = h;
            }
            v[j1] -= minv;
        }
    }

    // Augmenting row reduction, but cap retries: process each row a limited number of times,
    // then stop. We just want the final matching of the FULL version's row reduction,
    // so keep the same logic but tighter memory access.
    for (int pass = 0; pass < 2; pass++) {
        int k = 0;
        int prv = numfree;
        numfree = 0;
        while (k < prv) {
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            // find two smallest reduced costs
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            for (int j = 0; j < n; j++) {
                double h = row[j] - v[j];
                if (h < umin) { usub = umin; j2 = j1; umin = h; j1 = j; }
                else if (h < usub) { usub = h; j2 = j; }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j2]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[prv++] = i0;
            }
        }
    }
    // authoritative
    std::vector<int> rs(n, -1);
    for (int j = 0; j < n; j++) if (colsol[j] >= 0) rs[colsol[j]] = j;
    int nfree = 0;
    for (int i = 0; i < n; i++) { rowsol[i] = rs[i]; if (rs[i] < 0) nfree++; }
    return nfree;
}
