#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>

struct Cand { double c; int j; };

// Auction that warm-starts from existing prices and assignment. Does NOT reset prices.
// One epsilon stage only (eps fixed). Returns 0 on full assignment.
static int auction_stage(int n, const std::vector<int>& off, const std::vector<int>& idx,
                         const std::vector<double>& cst, std::vector<int>& assign,
                         std::vector<double>& price, double eps, long& iters) {
    std::vector<int> owner(n, -1);
    std::vector<double> high_bid(n);
    std::vector<int> high_bidder(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);
    std::fill(assign.begin(), assign.end(), -1);
    // everyone starts free (prices carry over)
    for (int i = 0; i < n; i++) free_rows.push_back(i);
    int guard = 0;
    while (!free_rows.empty() && guard < n * 400) {
        guard++; iters++;
        std::fill(high_bid.begin(), high_bid.end(), -1e300);
        std::fill(high_bidder.begin(), high_bidder.end(), -1);
        int nfree = (int)free_rows.size();
        for (int fi = 0; fi < nfree; fi++) {
            int r = free_rows[fi];
            int bj = -1; double best = -1e300, second = -1e300;
            for (int p = off[r]; p < off[r+1]; p++) {
                double val = -cst[p] - price[idx[p]];
                if (val > best) { second = best; best = val; bj = idx[p]; }
                else if (val > second) second = val;
            }
            if (bj < 0) return -1;
            if (second < -1e299) second = best - 1.0;
            double b = price[bj] + (best - second) + eps;
            if (b > high_bid[bj]) { high_bid[bj] = b; high_bidder[bj] = r; }
        }
        for (int j = 0; j < n; j++) {
            int r = high_bidder[j];
            if (r < 0) continue;
            int prev = owner[j];
            if (prev >= 0) assign[prev] = -1;
            owner[j] = r; assign[r] = j; price[j] = high_bid[j];
        }
        free_rows.clear();
        for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows.push_back(i);
    }
    return free_rows.empty() ? 0 : -1;
}

static void build_csr(int n, const double* M, const std::vector<std::vector<int>>& cand,
                      std::vector<int>& off, std::vector<int>& idx, std::vector<double>& cst) {
    off.assign(n + 1, 0);
    for (int i = 0; i < n; i++) off[i+1] = off[i] + (int)cand[i].size();
    idx.resize(off[n]); cst.resize(off[n]);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int t = 0; t < (int)cand[i].size(); t++) {
            idx[off[i] + t] = cand[i][t];
            cst[off[i] + t] = row[cand[i][t]];
        }
    }
}

extern "C" int solve_refine2(const double* M, int n, int k0, int* out_assign) {
    std::vector<std::vector<int>> cand(n);
    std::vector<Cand> buf(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
