#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>

struct Cand { double c; int j; };

static int auction(int n, const std::vector<int>& off, const std::vector<int>& idx,
                   const std::vector<double>& cst, std::vector<int>& assign,
                   std::vector<double>& price, double eps_final) {
    std::vector<int> owner(n, -1);
    std::vector<double> high_bid(n);
    std::vector<int> high_bidder(n);
    std::vector<int> free_rows(n);
    std::fill(price.begin(), price.end(), 0.0);
    double maxc = 0; for (double c : cst) if (c > maxc) maxc = c;
    double eps = std::max(maxc / 2.0, eps_final);
    while (true) {
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int nfree = n, guard = 0;
        while (nfree > 0 && guard < n * 500) {
            guard++;
            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);
            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                int bj = -1; double best = -1e300, second = -1e300;
                for (int p = off[r]; p < off[r+1]; p++) {
                    double val = -cst[p] - price[idx[p]];
                    if (val > best) { second = best; best = val; bj = idx[p]; }
                    else if (val > second) second = val;
                }
                if (bj < 0) return -1;
                if (second < -1e299) second = best - 1.0;
                double b = price[bj] + (best - second) + eps;
                if (b > high_bid[bj]) { high_bid[bj] = b; high_bidder[bj] = r; }
            }
            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r; assign[r] = j; price[j] = high_bid[j];
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows[nfree++] = i;
        }
        if (nfree > 0) return -1;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    return 0;
}

extern "C" int solve_refine3(const double* M, int n, int k0, int* out_assign) {
    std::vector<std::vector<int>> cand(n);
    std::vector<Cand> buf(n);
    std::vector<char> member(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) buf[j] = Cand{row[j], j};
        std::nth_element(buf.begin(), buf.begin() + k0, buf.end(),
                         [](const Cand& a, const Cand& b){ return a.c < b.c; });
        cand[i].reserve(k0 + 64);
        for (int t = 0; t < k0; t++) cand[i].push_back(buf[t].j);
    }
    std::vector<int> assign(n), price_i(n);
    std::vector<double> price(n);
    const double eps_final = 1e-10;

    for (int round = 0; round < 8; round++) {
        std::vector<int> off(n + 1, 0);
        for (int i = 0; i < n; i++) off[i+1] = off[i] + (int)cand[i].size();
        std::vector<int> idx(off[n]);
        std::vector<double> cst(off[n]);
        for (int i = 0; i < n; i++) {
            const double* row = M + (size_t)i * n;
            for (int t = 0; t < (int)cand[i].size(); t++) {
                idx[off[i]+t] = cand[i][t];
                cst[off[i]+t] = row[cand[i][t]];
            }
        }
        if (auction(n, off, idx, cst, assign, price, eps_final) != 0) return -1;

        int violations = 0;
        for (int i = 0; i < n; i++) {
            const double* row = M + (size_t)i * n;
            double best = 1e300; int bj = -1;
            double second = 1e300; int sj = -1;
            for (int j = 0; j < n; j++) {
                double val = row[j] + price[j];
                if (val < best) { second = best; sj = bj; best = val; bj = j; }
                else if (val < second) { second = val; sj = j; }
            }
            int a = assign[i];
            if (bj != a && row[a] + price[a] > best + 1e-9) {
                std::fill(member.begin(), member.end(), 0);
                for (int c : cand[i]) member[c] = 1;
                if (!member[bj]) { cand[i].push_back(bj); violations++; }
                if (sj >= 0 && !member[sj]) cand[i].push_back(sj);
            }
        }
        if (violations == 0) {
            for (int i = 0; i < n; i++) out_assign[i] = assign[i];
            return 0;
