// Fast min-cost assignment via successive shortest augmenting paths with
// potentials, using a Dial-like bucket queue on scaled integer reduced costs
// and a local candidate graph that is expanded until optimality is certified.
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>

struct Cand { double c; int j; };

extern "C" int solve_fast(const double* M, int n, int k0, int* out_assign) {
    // candidate lists
    std::vector<std::vector<int>> cand(n);
    std::vector<Cand> buf(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) buf[j] = Cand{row[j], j};
        std::nth_element(buf.begin(), buf.begin() + k0, buf.end(),
                         [](const Cand& a, const Cand& b){ return a.c < b.c; });
        cand[i].reserve(k0 + 64);
        for (int t = 0; t < k0; t++) cand[i].push_back(buf[t].j);
    }

    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);

    // initial greedy on candidates
    for (int i = 0; i < n; i++) {
        double best = 1e300; int bj = -1;
        const double* row = M + (size_t)i * n;
        for (int j : cand[i]) if (colsol[j] < 0) {
            double red = row[j] - v[j];
            if (red < best) { best = red; bj = j; }
        }
        if (bj >= 0) { rowsol[i] = bj; colsol[bj] = i; u[i] = best; }
    }

    auto edge = [&](int i, int j, const std::vector<int>& cl) -> double {
        // linear scan of small list
        const double* row = M + (size_t)i * n;
        for (int c : cl) if (c == j) return row[c];
        return 1e300;
    };

    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> seen(n);
    std::vector<int> touched;
    touched.reserve(n);

    auto augment_one = [&](int start) -> bool {
        std::fill(dist.begin(), dist.end(), 1e300);
        std::fill(seen.begin(), seen.end(), 0);
        touched.clear();
        // init
        const double* row = M + (size_t)start * n;
        for (int j : cand[start]) {
            dist[j] = row[j] - u[start] - v[j];
            pred[j] = start;
            touched.push_back(j);
        }
        int endj = -1; double endd = 0;
        // Dijkstra by repeated min scan over touched (touched grows, but local)
        std::vector<char> inqueue(n, 0);
        for (int j : touched) inqueue[j] = 1;
        int remaining = (int)touched.size();
        while (remaining > 0) {
            double mn = 1e300; int jmin = -1;
            for (int j : touched) if (!seen[j] && dist[j] < mn) { mn = dist[j]; jmin = j; }
            if (jmin < 0) break;
            seen[jmin] = 1; remaining--;
            if (colsol[jmin] < 0) { endj = jmin; endd = mn; break; }
            int i0 = colsol[jmin];
            const double* row2 = M + (size_t)i0 * n;
            double base = 1e300;
            for (int c : cand[i0]) if (c == jmin) { base = row2[c]; break; }
            if (base > 1e299) continue;
            double add = mn - (base - u[i0] - v[jmin]);
            for (int jj : cand[i0]) if (!seen[jj]) {
                double val = row2[jj] - u[i0] - v[jj] + add;
                if (val < dist[jj]) {
                    if (dist[jj] > 1e299) { touched.push_back(jj); inqueue[jj]=1; remaining++; }
                    dist[jj] = val;
                    pred[jj] = i0;
                }
            }
        }
        if (endj < 0) return false;
        for (int j : touched) if (seen[j]) {
            double delta = endd - dist[j];
            v[j] -= delta;
            int i0 = colsol[j];
            if (i0 >= 0) u[i0] += delta;
        }
        u[start] += endd;
        int j = endj;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            if (i == start) break;
            j = nxt;
        }
        return true;
    };

    for (int i = 0; i < n; i++) if (rowsol[i] < 0) {
        if (!augment_one(i)) return -1;
    }

    // certify / repair: while some row has a better column outside candidates, add it and re-solve that row by augmentation after unmatching
    std::vector<char> member(n);
    for (int round = 0; round < 20; round++) {
        int violations = 0;
        int worst_i = -1; double worst_gap = 0; int worst_j = -1;
        // full check
        std::vector<std::pair<int,int>> adds;
        for (int i = 0; i < n; i++) {
            const double* row = M + (size_t)i * n;
            double best = 1e300; int bj = -1;
            for (int j = 0; j < n; j++) {
                double val = row[j] - v[j];
                if (val < best) { best = val; bj = j; }
            }
            int a = rowsol[i];
            double aval = row[a] - v[a];
            if (aval > best + 1e-9) {
                adds.push_back({i, bj});
                violations++;
            }
        }
        if (violations == 0) {
            for (int i = 0; i < n; i++) out_assign[i] = rowsol[i];
            return 0;
        }
        // add violating edges and re-augment from those rows (unmatch first)
        for (auto [i, bj] : adds) {
            bool has = false;
            for (int c : cand[i]) if (c == bj) { has = true; break; }
            if (!has) cand[i].push_back(bj);
        }
        // unmatch all violating rows and re-augment
        for (auto [i, bj] : adds) {
            int j = rowsol[i];
            if (j >= 0 && colsol[j] == i) colsol[j] = -1;
            rowsol[i] = -1;
        }
        for (auto [i, bj] : adds) {
            if (rowsol[i] < 0) {
                if (!augment_one(i)) return -2;
            }
        }
    }
    return -3;
}
