#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <queue>
#include <cstring>
#include <chrono>
static double now(){ using namespace std::chrono; return duration<double>(steady_clock::now().time_since_epoch()).count(); }
struct Cand { double c; int j; };

extern "C" int solve_prof(const double* M, int n, int k0, int* out_assign, double* times) {
    double t0=now();
    std::vector<std::vector<int>> cand(n);
    std::vector<Cand> buf(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) buf[j] = Cand{row[j], j};
        std::nth_element(buf.begin(), buf.begin() + k0, buf.end(),
                         [](const Cand& a, const Cand& b){ return a.c < b.c; });
        cand[i].reserve(k0 + 64);
        for (int t = 0; t < k0; t++) cand[i].push_back(buf[t].j);
    }
    times[0]=now()-t0;

    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    for (int i = 0; i < n; i++) {
        double best = 1e300; int bj = -1;
        const double* row = M + (size_t)i * n;
        for (int j : cand[i]) if (colsol[j] < 0) {
            double red = row[j] - v[j];
            if (red < best) { best = red; bj = j; }
        }
        if (bj >= 0) { rowsol[i] = bj; colsol[bj] = i; u[i] = best; }
    }

    std::vector<double> dist(n, 1e300);
    std::vector<int> pred(n, -1);
    std::vector<int> seen_stamp(n, 0);
    int stamp = 0;
    std::vector<int> touched; touched.reserve(2048);
    using P = std::pair<double,int>;

    auto augment_one = [&](int start) -> bool {
        stamp++;
        if (stamp==0){ std::fill(seen_stamp.begin(),seen_stamp.end(),0); stamp=1; }
        touched.clear();
        std::priority_queue<P,std::vector<P>,std::greater<P>> pq;
        const double* row = M + (size_t)start * n;
        for (int j : cand[start]) {
            double d = row[j] - u[start] - v[j];
            dist[j]=d; pred[j]=start; seen_stamp[j]=stamp; touched.push_back(j); pq.emplace(d,j);
        }
        int endj=-1; double endd=0;
        while(!pq.empty()){
            auto [dcur,j]=pq.top(); pq.pop();
            if(seen_stamp[j]!=stamp) continue;
            if(dcur>dist[j]+1e-15) continue;
            seen_stamp[j]=-stamp;
            if(colsol[j]<0){ endj=j; endd=dcur; break; }
            int i0=colsol[j];
            const double* row2=M+(size_t)i0*n;
            double base=1e300;
            for(int c:cand[i0]) if(c==j){ base=row2[c]; break; }
            if(base>1e299) continue;
            double add=dcur-(base-u[i0]-v[j]);
            for(int jj:cand[i0]){
                if(seen_stamp[jj]==-stamp) continue;
                double val=row2[jj]-u[i0]-v[jj]+add;
                if(seen_stamp[jj]!=stamp || val<dist[jj]){
                    if(seen_stamp[jj]!=stamp){ touched.push_back(jj); seen_stamp[jj]=stamp; }
                    dist[jj]=val; pred[jj]=i0; pq.emplace(val,jj);
                }
            }
        }
        if(endj<0) return false;
        for(int j:touched) if(seen_stamp[j]==-stamp){
            double delta=endd-dist[j]; v[j]-=delta; int i0=colsol[j]; if(i0>=0) u[i0]+=delta;
        }
        u[start]+=endd;
        int j=endj;
        while(true){ int i=pred[j]; colsol[j]=i; int nxt=rowsol[i]; rowsol[i]=j; if(i==start) break; j=nxt; }
        return true;
    };

    t0=now();
    int n_aug=0;
    for(int i=0;i<n;i++) if(rowsol[i]<0){ n_aug++; if(!augment_one(i)) return -1; }
    times[1]=now()-t0; times[3]=n_aug;

    t0=now();
    int rounds=0, total_viol=0;
    for(int round=0; round<30; round++){
        rounds++;
        std::vector<std::pair<int,int>> adds;
        for(int i=0;i<n;i++){
            const double* row=M+(size_t)i*n;
            double best=1e300; int bj=-1;
            for(int j=0;j<n;j++){ double val=row[j]-v[j]; if(val<best){ best=val; bj=j; } }
            int a=rowsol[i];
            if(row[a]-v[a] > best+1e-9) adds.push_back({i,bj});
        }
        total_viol+=adds.size();
        if(adds.empty()){ for(int i=0;i<n;i++) out_assign[i]=rowsol[i]; times[2]=now()-t0; times[4]=rounds; times[5]=total_viol; return 0; }
        for(auto [i,bj]:adds){
            bool has=false; for(int c:cand[i]) if(c==bj){has=true;break;}
            if(!has) cand[i].push_back(bj);
            int j=rowsol[i]; if(j>=0 && colsol[j]==i) colsol[j]=-1; rowsol[i]=-1;
        }
        for(auto [i,bj]:adds){ if(rowsol[i]<0){ if(!augment_one(i)) return -2; } }
    }
    times[2]=now()-t0; times[4]=rounds; times[5]=total_viol; return -3;
}
