#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <queue>
#include <cstring>

struct Cand { double c; int j; };

extern "C" int solve_fast4(const double* M, int n, int k0, int* out_assign) {
    std::vector<std::vector<int>> cand(n);
    std::vector<std::vector<double>> cc(n);
    std::vector<Cand> buf(n);
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; j++) buf[j] = Cand{row[j], j};
        std::nth_element(buf.begin(), buf.begin() + k0, buf.end(),
                         [](const Cand& a, const Cand& b){ return a.c < b.c; });
        std::sort(buf.begin(), buf.begin() + k0, [](const Cand& a, const Cand& b){ return a.c < b.c; });
        cand[i].resize(k0); cc[i].resize(k0);
        for (int t = 0; t < k0; t++) { cand[i][t] = buf[t].j; cc[i][t] = buf[t].c; }
    }
    // cost lookup: for matched edge we know it. For base during dijkstra, store matched cost.
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> match_cost(n, 0.0);

    for (int i = 0; i < n; i++) {
        double best = 1e300; int bj = -1; double bc = 0;
        for (int t = 0; t < (int)cand[i].size(); t++) {
            int j = cand[i][t];
            if (colsol[j] < 0) {
                double red = cc[i][t] - v[j];
                if (red < best) { best = red; bj = j; bc = cc[i][t]; }
            }
        }
        if (bj >= 0) { rowsol[i] = bj; colsol[bj] = i; u[i] = best; match_cost[i] = bc; }
    }

    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<int> stamp_reach(n, 0), stamp_scan(n, 0);
    int stamp = 0;
    using P = std::pair<double,int>;

    auto augment_one = [&](int start) -> bool {
        stamp++;
        if (stamp == 0) { std::fill(stamp_reach.begin(), stamp_reach.end(), 0); std::fill(stamp_scan.begin(), stamp_scan.end(), 0); stamp = 1; }
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        for (int t = 0; t < (int)cand[start].size(); t++) {
            int j = cand[start][t];
            double d = cc[start][t] - u[start] - v[j];
            dist[j] = d; pred[j] = start; stamp_reach[j] = stamp;
            pq.emplace(d, j);
        }
        int endj = -1; double endd = 0;
        while (!pq.empty()) {
            auto [dcur, j] = pq.top(); pq.pop();
            if (stamp_scan[j] == stamp) continue;
            if (stamp_reach[j] != stamp || dcur > dist[j] + 1e-15) continue;
            stamp_scan[j] = stamp;
            if (colsol[j] < 0) { endj = j; endd = dcur; break; }
            int i0 = colsol[j];
            double base = match_cost[i0];
            double add = dcur - (base - u[i0] - v[j]);
            for (int t = 0; t < (int)cand[i0].size(); t++) {
                int jj = cand[i0][t];
                if (stamp_scan[jj] == stamp) continue;
                double val = cc[i0][t] - u[i0] - v[jj] + add;
                if (stamp_reach[jj] != stamp || val < dist[jj]) {
                    dist[jj] = val; pred[jj] = i0; stamp_reach[jj] = stamp;
                    pq.emplace(val, jj);
                }
            }
        }
        if (endj < 0) return false;
        for (int j = 0; j < n; j++) if (stamp_scan[j] == stamp) {
            double delta = endd - dist[j];
            v[j] -= delta;
            int i0 = colsol[j];
            if (i0 >= 0) u[i0] += delta;
        }
        u[start] += endd;
        int j = endj;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int nxt = rowsol[i];
            rowsol[i] = j;
            match_cost[i] = M[(size_t)i * n + j];
            if (i == start) break;
            j = nxt;
        }
        return true;
    };

    for (int i = 0; i < n; i++) if (rowsol[i] < 0) {
        if (!augment_one(i)) return -1;
    }

    // repair. Only full-scan rows whose candidate-best reduced cost is close to suspicious,
    // but correctness needs full scan. Do it, but vectorized-friendly.
    std::vector<char> in_cand(n);
    for (int round = 0; round < 40; round++) {
        std::vector<std::pair<int,int>> adds;
        adds.reserve(64);
        for (int i = 0; i < n; i++) {
            const double* row = M + (size_t)i * n;
            // threshold: matched reduced cost
            double thresh = match_cost[i] - v[rowsol[i]] - 1e-9;
            double best = 1e300; int bj = -1;
            // scan all columns; early? must find min
            for (int j = 0; j < n; j++) {
                double val = row[j] - v[j];
                if (val < best) { best = val; bj = j; }
            }
            if (best < thresh) adds.push_back({i, bj});
        }
        if (adds.empty()) {
            for (int i = 0; i < n; i++) out_assign[i] = rowsol[i];
            return 0;
        }
        for (auto [i, bj] : adds) {
            std::fill(in_cand.begin(), in_cand.end(), 0);
            for (int c : cand[i]) in_cand[c] = 1;
            if (!in_cand[bj]) { cand[i].push_back(bj); cc[i].push_back(M[(size_t)i * n + bj]); }
            int j = rowsol[i];
            if (j >= 0 && colsol[j] == i) colsol[j] = -1;
            rowsol[i] = -1;
        }
        for (auto [i, bj] : adds) if (rowsol[i] < 0) {
            if (!augment_one(i)) return -2;
        }
    }
    return -3;
}
