#include <pthread.h>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <atomic>

static const int MAX_T = 4;

struct Shared {
    const int* idx;       // n*k
    const double* cst;    // n*k
    const double* price;
    const int* free_rows;
    int nfree;
    int k;
    int* best_j;
    double* bid_delta;    // best - second (so bid = price[bj] + delta + eps)
    pthread_mutex_t mtx;
    pthread_cond_t cv_start, cv_done;
    int epoch;
    int done_count;
    bool stop;
    int nthreads;
};

static void* worker(void* arg) {
    auto* S = (Shared*)arg;
    int tid;
    pthread_mutex_lock(&S->mtx);
    static int next_tid = 0;
    tid = next_tid++;
    int my_epoch = 0;
    pthread_mutex_unlock(&S->mtx);
    while (true) {
        pthread_mutex_lock(&S->mtx);
        while (S->epoch == my_epoch && !S->stop) pthread_cond_wait(&S->cv_start, &S->mtx);
        if (S->stop) { pthread_mutex_unlock(&S->mtx); break; }
        my_epoch = S->epoch;
        pthread_mutex_unlock(&S->mtx);

        for (int fi = tid; fi < S->nfree; fi += S->nthreads) {
            int r = S->free_rows[fi];
            const int* id = S->idx + (size_t)r * S->k;
            const double* cs = S->cst + (size_t)r * S->k;
            int bj = id[0];
            double best = -1e300, second = -1e300;
            for (int t = 0; t < S->k; t++) {
                double val = -cs[t] - S->price[id[t]];
                if (val > best) { second = best; best = val; bj = id[t]; }
                else if (val > second) second = val;
            }
            if (second < -1e299) second = best - 1.0;
            S->best_j[r] = bj;
            S->bid_delta[r] = best - second;
        }

        pthread_mutex_lock(&S->mtx);
        S->done_count++;
        if (S->done_count == S->nthreads) pthread_cond_signal(&S->cv_done);
        pthread_mutex_unlock(&S->mtx);
    }
    return nullptr;
}

struct Pool {
    Shared S;
    pthread_t th[MAX_T];
    bool started = false;
    void start(int nthreads) {
        S.nthreads = nthreads;
        S.epoch = 0; S.done_count = 0; S.stop = false;
        pthread_mutex_init(&S.mtx, nullptr);
        pthread_cond_init(&S.cv_start, nullptr);
        pthread_cond_init(&S.cv_done, nullptr);
        for (int t = 0; t < nthreads; t++) pthread_create(&th[t], nullptr, worker, &S);
        started = true;
    }
    void run() {
        pthread_mutex_lock(&S.mtx);
        S.done_count = 0;
        S.epoch++;
        pthread_cond_broadcast(&S.cv_start);
        while (S.done_count < S.nthreads) pthread_cond_wait(&S.cv_done, &S.mtx);
        pthread_mutex_unlock(&S.mtx);
    }
};

static Pool pool;
static bool pool_ready = false;

extern "C" int auction_pool(const int* idx, const double* cst, int n, int k, int* out, double eps_final, int nthreads) {
    if (!pool_ready) { pool.start(nthreads); pool_ready = true; }
    std::vector<double> price(n, 0.0);
    std::vector<int> assign(n, -1), owner(n, -1);
    std::vector<double> high_bid(n);
    std::vector<int> high_bidder(n);
    std::vector<int> free_rows(n);
    std::vector<int> best_j(n);
    std::vector<double> bid_delta(n);

    double maxc = 0; for (int i = 0; i < n*k; i++) if (cst[i] > maxc) maxc = cst[i];
    double eps = std::max(maxc / 2.0, eps_final);

    pool.S.idx = idx; pool.S.cst = cst; pool.S.k = k;
    pool.S.best_j = best_j.data(); pool.S.bid_delta = bid_delta.data();

    while (true) {
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(owner.begin(), owner.end(), -1);
        for (int i = 0; i < n; i++) free_rows[i] = i;
        int nfree = n, guard = 0;
        while (nfree > 0 && guard < n * 500) {
            guard++;
            pool.S.price = price.data();
            pool.S.free_rows = free_rows.data();
            pool.S.nfree = nfree;
            pool.run();
            std::fill(high_bid.begin(), high_bid.end(), -1e300);
            std::fill(high_bidder.begin(), high_bidder.end(), -1);
            for (int fi = 0; fi < nfree; fi++) {
                int r = free_rows[fi];
                int j = best_j[r];
                double b = price[j] + bid_delta[r] + eps;
                if (b > high_bid[j]) { high_bid[j] = b; high_bidder[j] = r; }
            }
            for (int j = 0; j < n; j++) {
                int r = high_bidder[j];
                if (r < 0) continue;
                int prev = owner[j];
                if (prev >= 0) assign[prev] = -1;
                owner[j] = r; assign[r] = j; price[j] = high_bid[j];
            }
            nfree = 0;
            for (int i = 0; i < n; i++) if (assign[i] < 0) free_rows[nfree++] = i;
        }
        if (nfree > 0) return -1;
        if (eps <= eps_final * 1.0000001) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    for (int i = 0; i < n; i++) out[i] = assign[i];
    return 0;
}
