struct Cand { double c; int j; };
extern "C" int stats(const double* M, int n, int k0) {
    std::vector<std::vector<int>> cand(n);
    std::vector<std::vector<double>> cc(n);
    std::vector<Cand> buf(n);
    for (int i=0;i<n;i++){ const double* row=M+(size_t)i*n;
        for(int j=0;j<n;j++) buf[j]=Cand{row[j],j};
        std::nth_element(buf.begin(),buf.begin()+k0,buf.end(),[](const Cand&a,const Cand&b){return a.c<b.c;});
        cand[i].resize(k0); cc[i].resize(k0);
        for(int t=0;t<k0;t++){cand[i][t]=buf[t].j; cc[i][t]=buf[t].c;} }
    std::vector<int> rowsol(n,-1), colsol(n,-1);
    std::vector<double> u(n,0), v(n,0), match_cost(n,0);
    for(int i=0;i<n;i++){ double best=1e300; int bj=-1; double bc=0;
        for(int t=0;t<(int)cand[i].size();t++){ int j=cand[i][t]; if(colsol[j]<0){ double red=cc[i][t]-v[j]; if(red<best){best=red;bj=j;bc=cc[i][t];} } }
        if(bj>=0){rowsol[i]=bj;colsol[bj]=i;u[i]=best;match_cost[i]=bc;} }
    std::vector<double> dist(n); std::vector<int> pred(n); std::vector<int> reach(n,0), scan(n,0); int stamp=0;
    using P=std::pair<double,int>;
    auto aug=[&](int start)->bool{ stamp++; if(stamp==0){std::fill(reach.begin(),reach.end(),0);std::fill(scan.begin(),scan.end(),0);stamp=1;}
        std::priority_queue<P,std::vector<P>,std::greater<P>> pq;
        for(int t=0;t<(int)cand[start].size();t++){ int j=cand[start][t]; double d=cc[start][t]-u[start]-v[j]; dist[j]=d; pred[j]=start; reach[j]=stamp; pq.emplace(d,j); }
        int endj=-1; double endd=0;
        while(!pq.empty()){ auto [dcur,j]=pq.top(); pq.pop(); if(scan[j]==stamp)continue; if(reach[j]!=stamp||dcur>dist[j]+1e-15)continue; scan[j]=stamp;
            if(colsol[j]<0){endj=j;endd=dcur;break;} int i0=colsol[j]; double base=match_cost[i0]; double add=dcur-(base-u[i0]-v[j]);
            for(int t=0;t<(int)cand[i0].size();t++){ int jj=cand[i0][t]; if(scan[jj]==stamp)continue; double val=cc[i0][t]-u[i0]-v[jj]+add; if(reach[jj]!=stamp||val<dist[jj]){dist[jj]=val;pred[jj]=i0;reach[jj]=stamp;pq.emplace(val,jj);} } }
        if(endj<0) return false;
        for(int j=0;j<n;j++) if(scan[j]==stamp){ double delta=endd-dist[j]; v[j]-=delta; int i0=colsol[j]; if(i0>=0) u[i0]+=delta; }
        u[start]+=endd; int j=endj; while(true){ int i=pred[j]; colsol[j]=i; int nxt=rowsol[i]; rowsol[i]=j; match_cost[i]=M[(size_t)i*n+j]; if(i==start)break; j=nxt; } return true; };
    for(int i=0;i<n;i++) if(rowsol[i]<0) if(!aug(i)) return -1;
    // round 1 violation analysis
    int nv=0; int max_extra_rank=0;
    for(int i=0;i<n;i++){ const double* row=M+(size_t)i*n; double thresh=match_cost[i]-v[rowsol[i]]-1e-9; double best=1e300; int bj=-1;
        for(int j=0;j<n;j++){ double val=row[j]-v[j]; if(val<best){best=val;bj=j;} }
        if(best<thresh){ nv++;
            // how many columns have reduced cost < thresh (would need to be candidates)?
            int cnt=0; for(int j=0;j<n;j++) if(row[j]-v[j] < thresh) cnt++;
            if(cnt>max_extra_rank) max_extra_rank=cnt; } }
    printf("round1 violating rows %d, max columns-better-than-match %d\n", nv, max_extra_rank);
    return 0;
}
