{"command":"cat > build/jv_fast.cpp << 'EOF'
// Cache-friendly Jonker-Volgenant. Column reduction + augmenting row reduction
// with immediate retry, then (rarely) shortest augmenting paths.
// Costs stored column-major internally for the column-oriented initialization,
// but row scans dominate, so keep row-major.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>

extern "C" int jv_fast(int n, const double* cost, int* rowsol) {
    const double BIG = 1e18;
    std::vector<int> colsol(n, -1);
    std::vector<int> matches(n, 0);
    std::vector<int> free_rows(n);
    std::vector<double> v(n);

    for (int i = 0; i < n; i++) rowsol[i] = -1;

    // column reduction, scanning rows (row-major friendly: transpose loop)
    // We need per-column min. Do it row-major: init v to row 0, then scan rows.
    for (int j = 0; j < n; j++) v[j] = cost[j];
    std::vector<int> imin(n, 0);
    for (int i = 1; i < n; i++) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; j++) if (row[j] < v[j]) { v[j] = row[j]; imin[j] = i; }
    }
    // assign unique mins, processing columns from the right like classic JV
    for (int j = n - 1; j >= 0; j--) {
        int i = imin[j];
        if (++matches[i] == 1) { rowsol[i] = j; colsol[j] = i; }
        else colsol[j] = -1;
    }

    int numfree = 0;
    for (int i = 0; i < n; i++) {
        if (matches[i] == 0) free_rows[numfree++] = i;
        else if (matches[i] == 1) {
            int j1 = rowsol[i];
            const double* row = cost + (size_t)i * n;
            double minv = BIG;
            for (int j = 0; j < n; j++) if (j != j1) {
                double h = row[j] - v[j];
                if (h < minv) minv = h;
            }
            v[j1] -= minv;
        }
    }

    // augmenting row reduction, 2 passes, but bound total iterations
    long long iter = 0;
    const long long iter_cap = (long long)n * 200; // if exceeded, fall through to augmentation
    bool capped = false;
    for (int pass = 0; pass < 2 && !capped; pass++) {
        int k = 0;
        int prv = numfree;
        numfree = 0;
        while (k < prv) {
            if (++iter > iter_cap) { capped = true; break; }
            int i = free_rows[k++];
            const double* row = cost + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = 0;
            for (int j = 0; j < n; j++) {
                double h = row[j] - v[j];
                if (h < umin) { usub = umin; j2 = j1; umin = h; j1 = j; }
                else if (h < usub) { usub = h; j2 = j; }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j2]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) free_rows[--k] = i0;
                else free_rows[prv++] = i0;
            }
        }
    }

    // authoritative free rows
    {
        std::vector<int> rs(n, -1);
        for (int j = 0; j < n; j++) if (colsol[j] >= 0) rs[colsol[j]] = j;
        numfree = 0;
        for (int i = 0; i < n; i++) { rowsol[i] = rs[i]; if (rs[i] < 0) free_rows[numfree++] = i; }
    }
    if (numfree == 0) return 0;

    // shortest augmenting paths for remaining free rows (column-list Dijkstra)
    std::vector<int> collist(n), pred(n);
    std::vector<double> d(n);
    for (int f = 0; f < numfree; f++) {
        int freerow = free_rows[f];
        const double* frow = cost + (size_t)freerow * n;
        for (int j = 0; j < n; j++) { d[j] = frow[j] - v[j]; pred[j] = freerow; collist[j] = j; }
        int low = 0, up = 0, last = 0, endofpath = -1;
        double minv = 0;
        bool found = false;
        while (!found) {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up]];
                up = low + 1;
                for (int kk = up; kk < n; kk++) {
                    int j = collist[kk];
                    double h = d[j];
                    if (h <= minv) {
                        if (h < minv) { up = low; minv = h; }
                        int tmp = collist[up]; collist[up++] = j; collist[kk] = tmp;
                    }
                }
                for (int kk = low; kk < up; kk++) if (colsol[collist[kk]] < 0) { endofpath = collist[kk]; found = true; break; }
            }
            if (found) break;
            int j1 = collist[low++];
            int i = colsol[j1];
            const double* row = cost + (size_t)i * n;
            double h = row[j1] - v[j1] - minv;
            for (int kk = up; kk < n; kk++) {
                int j = collist[kk];
                double cred = row[j] - v[j] - h;
                if (cred < d[j]) {
                    pred[j] = i;
                    if (cred == minv) {
                        if (colsol[j] < 0) { endofpath = j; found = true; break; }
                        int tmp = collist[up]; collist[up++] = j; collist[kk] = tmp;
                    }
                    d[j] = cred;
                }
            }
        }
        for (int kk = 0; kk <= last; kk++) { int j1 = collist[kk]; v[j1] += d[j1] - minv; }
        int i;
        do { i = pred[endofpath]; colsol[endofpath] = i; int j1 = endofpath; endofpath = rowsol[i]; rowsol[i] = j1; } while (i != freerow);
    }
    return numfree; // >0 means augmentation was needed (still correct)
}
