#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>

extern "C" double row_mins(const double* M, int n, double* out) {
    double sink = 0;
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        double mn = row[0];
        for (int j = 1; j < n; j++) if (row[j] < mn) mn = row[j];
        out[i] = mn;
        sink += mn;
    }
    return sink;
}

// two-smallest per row, branchless-ish
extern "C" double row_two(const double* M, int n, double* out) {
    double sink = 0;
    for (int i = 0; i < n; i++) {
        const double* row = M + (size_t)i * n;
        double a = 1e300, b = 1e300;
        for (int j = 0; j < n; j++) {
            double v = row[j];
            if (v < a) { b = a; a = v; }
            else if (v < b) b = v;
        }
        out[i] = a;
        sink += b;
    }
    return sink;
}
