#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <sys/time.h>

static double now() { struct timeval tv; gettimeofday(&tv, NULL); return tv.tv_sec + tv.tv_usec/1e6; }

typedef struct { unsigned char *pt, *ct, *key, *nonce, *aad; int n, aadlen, id; } Job;

static void* worker(void* arg) {
    Job* j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen=0, fl=0;
    unsigned char tag[16];
    unsigned char nonce[12];
    memcpy(nonce, j->nonce, 12);
    /* vary nonce per chunk so it's a valid independent encryption; for timing only */
    nonce[0] ^= j->id;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, nonce);
    if (j->aadlen) EVP_EncryptUpdate(ctx, NULL, &outlen, j->aad, j->aadlen);
    EVP_EncryptUpdate(ctx, j->ct, &outlen, j->pt, j->n);
    EVP_EncryptFinal_ex(ctx, j->ct+outlen, &fl);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int N = 60000*1024;
    unsigned char *pt = malloc(N), *ct = malloc(N);
    unsigned char key[16], nonce[12], aad[32];
    memset(pt, 0xab, N); memset(key,1,16); memset(nonce,2,12); memset(aad,3,32);
    for (int threads = 1; threads <= 6; threads++) {
        double t0 = now();
        int reps = 3;
        for (int r=0;r<reps;r++) {
            pthread_t th[16];
            Job jobs[16];
            int base = N/threads;
            for (int t=0;t<threads;t++) {
                int off = t*base;
                int len = (t==threads-1) ? N-off : base;
                jobs[t] = (Job){pt+off, ct+off, key, nonce, aad, len, 32, t};
                pthread_create(&th[t], NULL, worker, &jobs[t]);
            }
            for (int t=0;t<threads;t++) pthread_join(th[t], NULL);
        }
        double t1 = now();
        printf("threads %d: %.4fs  %.1f MB/s\n", threads, (t1-t0)/reps, N/((t1-t0)/reps)/1e6);
    }
    return 0;
}
