typedef struct { unsigned char *in, *out, *ks, *Htable; unsigned char ivec[16]; size_t len; unsigned char Xi[16]; } Job;
static void* worker(void* a){
    Job* j=a;
    unsigned char xiht[16+512];
    memset(xiht, 0, 16);
    memcpy(xiht+16, j->Htable, 256);
    unsigned char iv[16]; memcpy(iv, j->ivec, 16);
    size_t r = aesni_gcm_encrypt(j->in, j->out, j->len, j->ks, iv, xiht);
    /* tail */
    if (r < j->len){
        /* shouldn't happen for aligned lens; handle via ctr manually if needed */
    }
    memcpy(j->Xi, xiht, 16);
    return NULL;
}

static void p16(const char* l, const unsigned char* b){printf("%-16s ", l); for(int i=0;i<16;i++) printf("%02x", b[i]); printf("\n");}

int main(){
    unsigned char keyb[16]; memset(keyb,0x11,16);
    unsigned char nonce[12]; memset(nonce,0x22,12);
    unsigned char aad[32]; memset(aad,0x33,32);
    int N=60000*1024;
    unsigned char *pt=malloc(N), *ct=malloc(N), *ctref=malloc(N);
    for(int i=0;i<N;i++) pt[i]=i&0xff;
    unsigned char ks[512]; memset(ks,0,sizeof ks);
    aesni_set_encrypt_key(keyb,128,ks);
    unsigned char raw[2048]; memset(raw,0,sizeof raw);
    CRYPTO_gcm128_init((GCM128_CONTEXT*)raw, ks, (block128_f)aesni_encrypt);
    CRYPTO_gcm128_setiv((GCM128_CONTEXT*)raw, nonce, 12);
    CRYPTO_gcm128_aad((GCM128_CONTEXT*)raw, aad, 32);
    unsigned char *Htable = raw+0x60; /* 256 bytes */
    void (*ghash)(unsigned char*, const unsigned char*, const unsigned char*, size_t)=*(void**)(raw+0x168);
    void (*gmult)(unsigned char*, const unsigned char*)=*(void**)(raw+0x170);

    /* reference */
    EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new(); int outlen=0,fl=0; unsigned char tagref[16];
    EVP_EncryptInit_ex(ctx,EVP_aes_128_gcm(),NULL,NULL,NULL);
    EVP_CIPHER_CTX_ctrl(ctx,EVP_CTRL_GCM_SET_IVLEN,12,NULL);
    EVP_EncryptInit_ex(ctx,NULL,NULL,keyb,nonce);
    EVP_EncryptUpdate(ctx,NULL,&outlen,aad,32);
    EVP_EncryptUpdate(ctx,ctref,&outlen,pt,N);
    EVP_EncryptFinal_ex(ctx,ctref,&fl);
    EVP_CIPHER_CTX_ctrl(ctx,EVP_CTRL_GCM_GET_TAG,16,tagref);

    int threads=4;
    size_t chunk = (N/threads) & ~((size_t)15);
    Job jobs[8]; pthread_t th[8];
    double t0=now(); int reps=3;
    unsigned char tag[16];
    for(int rep=0;rep<reps;rep++){
        size_t off=0;
        for(int t=0;t<threads;t++){
            size_t len = (t==threads-1)? N-off : chunk;
            jobs[t].in=pt+off; jobs[t].out=ct+off; jobs[t].ks=ks; jobs[t].Htable=Htable; jobs[t].len=len;
            /* counter for block index off/16, starting counter value = 2 */
            unsigned int ctr = 2 + (unsigned)(off/16);
            memcpy(jobs[t].ivec, nonce, 12);
            jobs[t].ivec[12]=ctr>>24; jobs[t].ivec[13]=ctr>>16; jobs[t].ivec[14]=ctr>>8; jobs[t].ivec[15]=ctr;
            off+=len;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for(int t=0;t<threads;t++) pthread_join(th[t], NULL);
        /* combine GHASH: Xi_total = Xi0*H^(n1+n2+n3) + Xi1*H^(n2+n3) + Xi2*H^(n3) + Xi3
           where ni = blocks in chunk i. Use gmult repeatedly. */
        unsigned char Xi[16]; memset(Xi,0,16);
        /* start from aad Xi */
        unsigned char Xa[16]; memset(Xa,0,16);
        ghash(Xa, Htable, aad, 32);
        memcpy(Xi, Xa, 16);
        for(int t=0;t<threads;t++){
            size_t blocks = jobs[t].len/16;
            for(size_t b=0;b<blocks;b++) gmult(Xi, Htable);
            for(int i=0;i<16;i++) Xi[i]^=jobs[t].Xi[i];
        }
        /* len block */
        unsigned char lenblock[16]; memset(lenblock,0,16);
        unsigned long long ab=(unsigned long long)32*8, cb=(unsigned long long)N*8;
        for(int i=0;i<8;i++){ lenblock[7-i]=ab&0xff; ab>>=8; lenblock[15-i]=cb&0xff; cb>>=8; }
        ghash(Xi, Htable, lenblock, 16);
        for(int i=0;i<16;i++) tag[i]=Xi[i]^raw[0x20+i];
    }
    double t1=now();
    printf("parallel %d: %.4fs %.1f MB/s\n", threads,(t1-t0)/reps, N/((t1-t0)/reps)/1e6);
    printf("ct match: %d\n", memcmp(ct, ctref, N)==0);
    p16("tag", tag); p16("ref", tagref);
    return 0;
}
