    for (int i = 0; i < n; ++i) col_of_row[i] = -1;

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        const double* colbase = cost; // cost[i*n + j]
        double min_val = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double val = cost[i * n + j];
            if (val < min_val) {
                min_val = val;
                imin = i;
            }
        }
        v[j] = min_val;
        if (col_of_row[imin] == -1) {
            col_of_row[imin] = j;
            row_of_col[j] = imin;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (col_of_row[i] == -1) free_rows.push_back(i);
        else {
            int j = col_of_row[i];
            u[i] = cost[i * n + j] - v[j];
        }
    }

