        while (true) {
            double mind = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && dist[j] < mind) {
                    mind = dist[j];
                    jmin = j;
                }
            }
            scanned[jmin] = 1;
            int i = row_of_col[jmin];
            if (i == -1) {
                sink = jmin;
                break;
            }
            double u_i = cost[i * n + jmin] - v[jmin];
            double base = dist[jmin];
            const double* row = cost + i * n;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j]) {
                    double val = base + row[j] - u_i - v[j];
                    if (val < dist[j]) {
                        dist[j] = val;
                        pred[j] = i;
                    }
                }
            }
        }
        double ds = dist[sink];
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) v[j] += dist[j] - ds;
        }
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev_j = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            if (i == f) break;
            j = prev_j;
        }
        for (int jj = 0; jj < n; ++jj) {
            if (scanned[jj]) {
                int i = row_of_col[jj];
                if (i != -1) u[i] = cost[i * n + jj] - v[jj];
            }
        }
    }
    return 0;
}
