#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>

// Fast dense LAP: Jonker-Volgenant with column reduction + Dijkstra via binary heap.
extern "C" int lapjv(int n, const double* cost, int64_t* col_of_row) {
    const double INF = 1e300;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // heap
    std::vector<double> heap_d(n);
    std::vector<int> heap_j(n);
    std::vector<int> heap_pos(n, -1);
    int hsz = 0;

    auto sift_up = [&](int c) {
        while (c > 0) {
            int p = (c - 1) >> 1;
            if (heap_d[p] <= heap_d[c]) break;
            std::swap(heap_d[p], heap_d[c]);
            std::swap(heap_j[p], heap_j[c]);
            heap_pos[heap_j[p]] = p;
            heap_pos[heap_j[c]] = c;
            c = p;
        }
    };
    auto sift_down = [&](int i) {
        while (true) {
            int l = i * 2 + 1, r = l + 1, s = i;
            if (l < hsz && heap_d[l] < heap_d[s]) s = l;
            if (r < hsz && heap_d[r] < heap_d[s]) s = r;
            if (s == i) break;
            std::swap(heap_d[i], heap_d[s]);
            std::swap(heap_j[i], heap_j[s]);
            heap_pos[heap_j[i]] = i;
            heap_pos[heap_j[s]] = s;
            i = s;
        }
    };
    auto heap_push = [&](int j, double d) {
        int pos = heap_pos[j];
        if (pos == -1) {
            pos = hsz++;
            heap_d[pos] = d;
            heap_j[pos] = j;
            heap_pos[j] = pos;
            sift_up(pos);
        } else if (d < heap_d[pos]) {
            heap_d[pos] = d;
            sift_up(pos);
        }
    };
    auto heap_pop = [&]() -> int {
        int j = heap_j[0];
        heap_pos[j] = -1;
        --hsz;
        if (hsz > 0) {
            heap_d[0] = heap_d[hsz];
            heap_j[0] = heap_j[hsz];
            heap_pos[heap_j[0]] = 0;
            sift_down(0);
        }
        return j;
    };

    for (int i = 0; i < n; ++i) col_of_row[i] = -1;

    // COLUMN REDUCTION: assign each column to its cheapest free row
    for (int j = n - 1; j >= 0; --j) {
        double min_val = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double val = cost[(size_t)i * n + j];
            if (val < min_val) {
                min_val = val;
                imin = i;
            }
        }
        v[j] = min_val;
        if (col_of_row[imin] == -1) {
            col_of_row[imin] = j;
            row_of_col[j] = imin;
        }
    }

    // REDUCTION TRANSFER
    std::vector<int> free_tmp;
    for (int i = 0; i < n; ++i) {
        if (col_of_row[i] == -1) free_tmp.push_back(i);
        else u[i] = cost[(size_t)i * n + col_of_row[i]] - v[col_of_row[i]];
    }
    for (int i : free_tmp) {
        double min_val = INF;
        int jmin = -1;
        double second = INF;
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < min_val) {
                second = min_val;
                min_val = red;
                jmin = j;
            } else if (red < second) {
                second = red;
            }
        }
        u[i] = min_val;
        // transfer if the column's current row has an alternative
        if (row_of_col[jmin] == -1) {
            col_of_row[i] = jmin;
            row_of_col[jmin] = i;
        } else {
            int i2 = row_of_col[jmin];
            // if column jmin's reduced cost for i is strictly better, reassign
            // v update to make this a zero
            v[jmin] -= (second - min_val);
            u[i] = second;
            // unassign previous
            col_of_row[i2] = -1;
            col_of_row[i] = jmin;
            row_of_col[jmin] = i;
            u[i2] = cost[(size_t)i2 * n + jmin] - v[jmin];
        }
    }
    free_rows.clear();
    for (int i = 0; i < n; ++i) if (col_of_row[i] == -1) free_rows.push_back(i);

    // AUGMENT
    for (int f : free_rows) {
        hsz = 0;
        for (int j = 0; j < n; ++j) {
            dist[j] = cost[(size_t)f * n + j] - u[f] - v[j];
            pred[j] = f;
            scanned[j] = 0;
            heap_pos[j] = -1;
        }
        for (int j = 0; j < n; ++j) heap_push(j, dist[j]);

        int sink = -1;
        while (hsz > 0) {
            int jmin = heap_pop();
            if (scanned[jmin]) continue;
            scanned[jmin] = 1;
            int i = row_of_col[jmin];
            if (i == -1) { sink = jmin; break; }
            double u_i = cost[(size_t)i * n + jmin] - v[jmin];
            double base = dist[jmin];
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j]) {
                    double val = base + row[j] - u_i - v[j];
                    if (val < dist[j]) {
                        dist[j] = val;
                        pred[j] = i;
                        heap_push(j, val);
                    }
                }
            }
        }
        double ds = dist[sink];
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - ds;
        int j = sink;
        while (true) {
            int i = pred[j];
            int prev = col_of_row[i];
            col_of_row[i] = j;
            row_of_col[j] = i;
            u[i] = cost[(size_t)i * n + j] - v[j];
            if (i == f) break;
            j = prev;
        }
    }
    return (int)free_rows.size();
}
