import numpy as np, time
from numba import njit

@njit(fastmath=True)
def gehrd(A, Q):
    """Reduce A (float32) to Hessenberg in place. Accumulate reflectors into Q (identity on entry)."""
    n = A.shape[0]
    for k in range(n-2):
        # householder to zero A[k+2:, k]
        scale = np.float32(0.0)
        for i in range(k+1, n):
            v = abs(A[i, k])
            if v > scale:
                scale = v
        if scale == 0.0:
            continue
        inv = np.float32(1.0)/scale
        ss = np.float32(0.0)
        for i in range(k+1, n):
            A[i, k] *= inv
            ss += A[i, k]*A[i, k]
        nrm = np.sqrt(ss)
        if A[k+1, k] >= 0.0:
            A[k+1, k] += nrm
        else:
            A[k+1, k] -= nrm
        dot = A[k+1, k]*A[k+1, k]
        for i in range(k+2, n):
            dot += A[i, k]*A[i, k]
        tau = np.float32(2.0)/dot
        # left: rows k+1: applied to cols k+1:
        for j in range(k+1, n):
            s = np.float32(0.0)
            for i in range(k+1, n):
                s += A[i, k]*A[i, j]
            s *= tau
            for i in range(k+1, n):
                A[i, j] -= s*A[i, k]
        # right: cols k+1: applied to rows 0:
        for i in range(n):
            s = np.float32(0.0)
            for j in range(k+1, n):
                s += A[j, k]*A[i, j]
            s *= tau
            for j in range(k+1, n):
                A[i, j] -= s*A[j, k]
        # accumulate into Q (Q <- Q * reflector), reflector acts on coords k+1:
        for i in range(n):
            s = np.float32(0.0)
            for j in range(k+1, n):
                s += Q[i, j]*A[j, k]
            s *= tau
            for j in range(k+1, n):
                Q[i, j] -= s*A[j, k]
        # restore subdiag
        A[k+1, k] = -scale*nrm if A[k+1, k] > 0 else scale*nrm
        for i in range(k+2, n):
            A[i, k] = 0.0

n=60
