A = rng.standard_normal((n,n)).astype(np.float32)
Q = np.eye(n, dtype=np.float32)
gehrd(A.copy(), Q.copy())
t0=time.perf_counter()
for _ in range(3):
    gehrd(A.copy(), Q.copy())
print("gehrd n=60", (time.perf_counter()-t0)/3)
