import numpy as np, time
from numba import njit

@njit(fastmath=True)
def gehrd64(A):
    """In-place Hessenberg reduction, float64. Returns tau vector."""
    n = A.shape[0]
    tau = np.zeros(n-1)
    for k in range(n-2):
        scale = 0.0
        for i in range(k+1, n):
            v = abs(A[i, k])
            if v > scale:
                scale = v
        if scale == 0.0:
            tau[k] = 0.0
            continue
        inv = 1.0/scale
        ss = 0.0
        for i in range(k+1, n):
            A[i, k] *= inv
            ss += A[i, k]*A[i, k]
        nrm = np.sqrt(ss)
        if A[k+1, k] >= 0.0:
            A[k+1, k] += nrm
        else:
            A[k+1, k] -= nrm
        dot = 0.0
        for i in range(k+1, n):
            dot += A[i, k]*A[i, k]
        tau[k] = 2.0/dot
        for j in range(k+1, n):
            s = 0.0
            for i in range(k+1, n):
                s += A[i, k]*A[i, j]
            s *= tau[k]
            for i in range(k+1, n):
                A[i, j] -= s*A[i, k]
        for i in range(n):
            s = 0.0
            for j in range(k+1, n):
                s += A[j, k]*A[i, j]
            s *= tau[k]
            for j in range(k+1, n):
                A[i, j] -= s*A[j, k]
        beta = -scale*nrm if A[k+1, k] > 0.0 else scale*nrm
        # store reflector vector in subdiag column, scaled so A[k+1,k]=1 convention? keep raw
        A[k+1, k] = beta
        # zero below (reflector info discarded except tau)
        for i in range(k+2, n):
            A[i, k] = 0.0
    return tau

rng = np.random.default_rng(0)
for n in [60, 100, 150]:
    A = rng.standard_normal((n,n))
    gehrd64(A.copy())
    t0=time.perf_counter()
    reps=4
    for _ in range(reps):
        gehrd64(A.copy())
    print(n, (time.perf_counter()-t0)/reps)
