#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>

/* OpenSSL low-level symbols */
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define THREADS 6

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t off;
    size_t len;
    const unsigned char *key;
    const unsigned char *nonce; /* 12 bytes */
    unsigned int counter0;      /* block counter at off */
} job_t;

static void *worker(void *arg) {
    job_t *j = (job_t *)arg;
    unsigned char ctr[16];
    memcpy(ctr, &j->counter0, 4); /* little endian host; we set bytes explicitly below */
    /* write counter little-endian explicitly */
    uint32_t c = j->counter0;
    ctr[0] = (unsigned char)(c);
    ctr[1] = (unsigned char)(c >> 8);
    ctr[2] = (unsigned char)(c >> 16);
    ctr[3] = (unsigned char)(c >> 24);
    memcpy(ctr + 4, j->nonce, 12);
    ChaCha20_ctr32(j->out + j->off, j->in + j->off, j->len,
                   (const unsigned int *)j->key, (const unsigned int *)ctr);
    return NULL;
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    int has_aad = 0;
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) {
        return NULL;
    }
    has_aad = (aad.buf != NULL);
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (has_aad) PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }

    size_t n = (size_t)pt.len;
    PyObject *out = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)n);
    if (!out) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (has_aad) PyBuffer_Release(&aad);
        return NULL;
    }
    unsigned char *obuf = (unsigned char *)PyBytes_AS_STRING(out);

    /* poly key = first 32 bytes of block 0 */
    unsigned char block0[64];
    unsigned char zeros[64] = {0};
    unsigned char ctr0[16];
    memset(ctr0, 0, 4);
    memcpy(ctr0 + 4, nonce.buf, 12);
    ChaCha20_ctr32(block0, zeros, 64, (const unsigned int *)key.buf, (const unsigned int *)ctr0);

    /* parallel chacha of plaintext, counter starts at 1 */
    if (n > 0) {
        int threads = (n >= (1u << 20)) ? THREADS : 1;
        size_t chunk = (n / threads) & ~(size_t)63;
        if (chunk == 0) threads = 1;
        if (threads == 1) {
            job_t j = {pt.buf, obuf, 0, n, key.buf, nonce.buf, 1};
            worker(&j);
        } else {
            pthread_t th[THREADS];
            job_t jobs[THREADS];
            for (int i = 0; i < threads; i++) {
                size_t off = (size_t)i * chunk;
                size_t len = (i == threads - 1) ? (n - off) : chunk;
                jobs[i] = (job_t){pt.buf, obuf, off, len, key.buf, nonce.buf,
                                  (unsigned int)(1 + off / 64)};
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
