#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);
size_t Poly1305_ctx_size(void);

#define MAX_THREADS 8

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t off;
    size_t len;
    const unsigned char *key;
    const unsigned char *nonce;
    unsigned int counter0;
    void *poly_ctx;          /* thread-local poly1305 context, or NULL */
    const unsigned char *poly_key;
} job_t;

static void *worker(void *arg) {
    job_t *j = (job_t *)arg;
    unsigned char ctr[16];
    uint32_t c = j->counter0;
    ctr[0] = (unsigned char)c;
    ctr[1] = (unsigned char)(c >> 8);
    ctr[2] = (unsigned char)(c >> 16);
    ctr[3] = (unsigned char)(c >> 24);
    memcpy(ctr + 4, j->nonce, 12);
    ChaCha20_ctr32(j->out + j->off, j->in + j->off, j->len,
                   (const unsigned int *)j->key, (const unsigned int *)ctr);
    if (j->poly_ctx) {
        Poly1305_Init(j->poly_ctx, j->poly_key);
        Poly1305_Update(j->poly_ctx, j->out + j->off, j->len);
    }
    return NULL;
}

/* Persistent thread pool. Workers block on a cond var. */
static int g_threads = 6;
static pthread_t g_th[MAX_THREADS];
static job_t g_jobs[MAX_THREADS];
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static pthread_cond_t g_done_cv = PTHREAD_COND_INITIALIZER;
static int g_gen = 0;          /* incremented to dispatch */
static int g_seen[MAX_THREADS];
static int g_finished = 0;
static int g_stop = 0;
static int g_inited = 0;

static void *pool_worker(void *arg) {
    long idx = (long)arg;
    int my_gen = 0;
    for (;;) {
        pthread_mutex_lock(&g_mu);
        while (g_gen == my_gen && !g_stop) pthread_cond_wait(&g_cv, &g_mu);
        if (g_stop) { pthread_mutex_unlock(&g_mu); return NULL; }
        my_gen = g_gen;
        pthread_mutex_unlock(&g_mu);
        worker(&g_jobs[idx]);
        pthread_mutex_lock(&g_mu);
        g_finished++;
        if (g_finished == g_threads) pthread_cond_signal(&g_done_cv);
        pthread_mutex_unlock(&g_mu);
    }
}

static void pool_init(void) {
    if (g_inited) return;
    for (long i = 0; i < g_threads; i++)
        pthread_create(&g_th[i], NULL, pool_worker, (void *)i);
    g_inited = 1;
}

static void pool_run(void) {
    pthread_mutex_lock(&g_mu);
    g_finished = 0;
    g_gen++;
    pthread_cond_broadcast(&g_cv);
    while (g_finished < g_threads) pthread_cond_wait(&g_done_cv, &g_mu);
    pthread_mutex_unlock(&g_mu);
}

static PyObject *chacha_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad))
        return NULL;
    int has_aad = (aad.buf != NULL);
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        if (has_aad) PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }
    size_t n = (size_t)pt.len;
    PyObject *out = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)n);
    if (!out) goto fail;
    unsigned char *obuf = (unsigned char *)PyBytes_AS_STRING(out);

    unsigned char block0[64];
    unsigned char zeros[64] = {0};
    unsigned char ctr0[16] = {0};
    memcpy(ctr0 + 4, nonce.buf, 12);
    ChaCha20_ctr32(block0, zeros, 64, (const unsigned int *)key.buf, (const unsigned int *)ctr0);

    size_t csz = Poly1305_ctx_size();
    static void *ctxs[MAX_THREADS];
    static int ctxs_ready = 0;
    if (!ctxs_ready) {
        for (int i = 0; i < MAX_THREADS; i++) ctxs[i] = malloc(csz);
        ctxs_ready = 1;
    }

    int threads = (n >= (1u << 20)) ? g_threads : 1;
    size_t chunk = threads > 1 ? ((n / threads) & ~(size_t)63) : n;
    if (chunk == 0) { threads = 1; chunk = n; }

    if (n == 0) {
        /* nothing */
    } else if (threads == 1) {
        job_t j = {pt.buf, obuf, 0, n, key.buf, nonce.buf, 1, ctxs[0], block0};
        worker(&j);
    } else {
        pool_init();
        for (int i = 0; i < threads; i++) {
            size_t off = (size_t)i * chunk;
            size_t len = (i == threads - 1) ? (n - off) : chunk;
            g_jobs[i] = (job_t){pt.buf, obuf, off, len, key.buf, nonce.buf,
                                (unsigned int)(1 + off / 64), ctxs[i], block0};
        }
        pool_run();
    }

    /* combine poly states: we used independent contexts over the same key, so
       we cannot just add them. Instead fall back: compute poly over whole ct
       in the main thread only when threads>1?  WAIT -- independent Poly1305
       contexts over chunks are NOT combinable trivially here because we used
       Poly1305_Init per chunk (each starts fresh accumulator). That is wrong
       for the final tag. Recompute single poly over the ciphertext. */
    void *ctx = ctxs[0];
    Poly1305_Init(ctx, block0);
    size_t aad_len = has_aad ? (size_t)aad.len : 0;
    unsigned char pad[16] = {0};
    if (aad_len) {
        Poly1305_Update(ctx, aad.buf, aad_len);
        size_t r = (16 - (aad_len & 15)) & 15;
        if (r) Poly1305_Update(ctx, pad, r);
    }
    if (n) {
        Poly1305_Update(ctx, obuf, n);
        size_t r = (16 - (n & 15)) & 15;
        if (r) Poly1305_Update(ctx, pad, r);
    }
    unsigned char lens[16];
    uint64_t al = aad_len, pl = n;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &pl, 8);
    Poly1305_Update(ctx, lens, 16);
    unsigned char tag[16];
    Poly1305_Final(ctx, tag);

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (has_aad) PyBuffer_Release(&aad);
    PyObject *tagobj = PyBytes_FromStringAndSize((const char *)tag, 16);
    PyObject *res = PyTuple_New(2);
    PyTuple_SET_ITEM(res, 0, out);
    PyTuple_SET_ITEM(res, 1, tagobj);
    return res;
fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (has_aad) PyBuffer_Release(&aad);
    return NULL;
}

