#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <dlfcn.h>
unsigned int OPENSSL_ia32cap_P[8] = {0}; /* force scalar */
void poly1305_init(void *ctx, const unsigned char key[32], void *func);
void poly1305_blocks(void *ctx, const unsigned char *inp, size_t len, unsigned int padbit);
void poly1305_emit(void *ctx, unsigned char mac[16], const unsigned int nonce[4]);

typedef unsigned __int128 u128;
#define MASK64 (~(uint64_t)0)

static void mulred(uint64_t h0, uint64_t h1, uint64_t h2,
                   uint64_t r0, uint64_t r1,
                   uint64_t *o0, uint64_t *o1, uint64_t *o2) {
    uint64_t s1 = r1 + (r1 >> 2);
    /* replicate the exact asm multiply-reduce */
    u128 p;
    uint64_t d0, c, r10, d1, r8, a, ah, rbx, rbp, rax;
    p = (u128)r1 * h0; d0 = (uint64_t)p; r10 = (uint64_t)(p >> 64);
    p = (u128)r0 * h0; d1 = (uint64_t)p; r8 = (uint64_t)(p >> 64);
    p = (u128)r0 * h1; a = (uint64_t)p; ah = (uint64_t)(p >> 64);
    { u128 s = (u128)d0 + a; d0 = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)r10 + ah + c; r10 = (uint64_t)s; }
    p = (u128)s1 * h1; a = (uint64_t)p; ah = (uint64_t)(p >> 64);
    { u128 s = (u128)d1 + a; d1 = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)r8 + ah + c; r8 = (uint64_t)s; }
    rbx = (uint64_t)((u128)s1 * h2);
    { u128 s = (u128)d0 + rbx; d0 = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)r10 + c; r10 = (uint64_t)s; }
    rbp = (uint64_t)((u128)r0 * h2);
    { u128 s = (u128)r8 + d0; rbx = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)r10 + rbp + c; r10 = (uint64_t)s; }
    rax = r10 & ~(uint64_t)3;
    rbp = r10 & 3;
    { u128 s = (u128)rax + (r10 >> 2); rax = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)d1 + rax; *o0 = (uint64_t)s; c = (uint64_t)(s >> 64); }
    { u128 s = (u128)rbx + c; *o1 = (uint64_t)s; c = (uint64_t)(s >> 64); }
    *o2 = rbp + c;
}

int main(){
    void *dl = dlopen("/usr/local/lib/libcrypto.dylib", RTLD_NOW);
    void (*PInit)(void*, const unsigned char*) = dlsym(dl, "Poly1305_Init");
    void (*PUpd)(void*, const unsigned char*, size_t) = dlsym(dl, "Poly1305_Update");
    void (*PFin)(void*, unsigned char*) = dlsym(dl, "Poly1305_Final");
    size_t (*PSz)(void) = dlsym(dl, "Poly1305_ctx_size");

    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i+1;
    uint64_t r0 = (*(uint64_t*)key) & 0x0ffffffc0fffffffULL;
    uint64_t r1 = (*(uint64_t*)(key+8)) & 0x0ffffffc0ffffffcULL;

