    unsigned char msg[16]; for(int i=0;i<16;i++) msg[i]=i*3+7;
    unsigned char ctx[256]; void *func[2];
    memset(ctx,0,sizeof(ctx)); poly1305_init(ctx, key, func);
    poly1305_blocks(ctx, msg, 16, 1);
    uint64_t o0,o1,o2;
    mulred(*(uint64_t*)msg, *(uint64_t*)(msg+8), 1, r0, r1, &o0,&o1,&o2);
    printf("one block match: %d\n", o0==*(uint64_t*)ctx && o1==*(uint64_t*)(ctx+8) && o2==*(uint32_t*)(ctx+16));

    /* Now the real test: 128-byte message, split in two 64-byte halves.
       hA = poly(first 64), hB = poly(second 64). Combined = hA * r^4 + hB. */
    unsigned char msg2[128]; for(int i=0;i<128;i++) msg2[i]=i*3+7;
    unsigned char ctxA[256], ctxB[256];
    memset(ctxA,0,sizeof(ctxA)); poly1305_init(ctxA, key, func);
    poly1305_blocks(ctxA, msg2, 64, 1);
    memset(ctxB,0,sizeof(ctxB)); poly1305_init(ctxB, key, func);
    poly1305_blocks(ctxB, msg2+64, 64, 1);

    /* compute r^4 by squaring r twice using mulred: start from (r0, r1, 0) */
    uint64_t p0=r0, p1=r1, p2=0;
    for (int i=0;i<2;i++){ /* square twice => r^4 */
        uint64_t a0=p0,a1=p1,a2=p2;
        /* r^2 = r * r. Use mulred(h=r, r=r). */
        mulred(a0,a1,a2, r0,r1, &p0,&p1,&p2);
        r0=p0; r1=p1; /* WRONG: r must stay fixed. redo properly below */
    }
    /* recompute properly */
    r0 = (*(uint64_t*)key) & 0x0ffffffc0fffffffULL;
    r1 = (*(uint64_t*)(key+8)) & 0x0ffffffc0ffffffcULL;
    uint64_t s0=r0, s1=r1, s2=0; /* r^1 */
    mulred(s0,s1,s2, r0,r1, &s0,&s1,&s2); /* r^2 */
    mulred(s0,s1,s2, r0,r1, &s0,&s1,&s2); /* r^3 */
    mulred(s0,s1,s2, r0,r1, &s0,&s1,&s2); /* r^4 */
