static fe fe_mul(fe a, fe b) {
    __uint128_t p00 = (__uint128_t)a.v0 * b.v0;
    __uint128_t p01 = (__uint128_t)a.v0 * b.v1;
    __uint128_t p10 = (__uint128_t)a.v1 * b.v0;
    __uint128_t p02 = (__uint128_t)a.v0 * b.v2;
    __uint128_t p11 = (__uint128_t)a.v1 * b.v1;
    __uint128_t p20 = (__uint128_t)a.v2 * b.v0;
    __uint128_t p12 = (__uint128_t)a.v1 * b.v2;
    __uint128_t p21 = (__uint128_t)a.v2 * b.v1;
    __uint128_t p22 = (__uint128_t)a.v2 * b.v2;

    __uint128_t acc = p00;
    uint64_t l0 = (uint64_t)acc; acc >>= 64;
    acc += p01 + p10;
    uint64_t l1 = (uint64_t)acc; acc >>= 64;
    acc += p02 + p11 + p20;
    uint64_t l2 = (uint64_t)acc; acc >>= 64;
    acc += p12 + p21;
    uint64_t l3 = (uint64_t)acc; acc >>= 64;
    acc += p22;
    uint64_t l4 = (uint64_t)acc;

    /* P >> 130 */
    __uint128_t hi = (__uint128_t)(l2 >> 2) + ((__uint128_t)l3 << 62) + ((__uint128_t)l4 << 126);
    uint64_t hv0 = (uint64_t)hi;
    uint64_t hv1 = (uint64_t)(hi >> 64);

    /* 5 * x_hi + x_lo */
    __uint128_t f0 = (__uint128_t)hv0 * 5 + l0;
    __uint128_t f1 = (__uint128_t)hv1 * 5 + l1 + (f0 >> 64);
    __uint128_t f2 = (l2 & 3ULL) + (f1 >> 64);
    uint64_t o0 = (uint64_t)f0;
    uint64_t o1 = (uint64_t)f1;
    uint64_t o2 = (uint64_t)f2;

    if (o2 >= 4) {
        uint64_t k = o2 >> 2;
        __uint128_t z0 = (__uint128_t)o0 + (__uint128_t)k * 5;
        o0 = (uint64_t)z0;
        __uint128_t z1 = (__uint128_t)o1 + (z0 >> 64);
        o1 = (uint64_t)z1;
        o2 = (o2 & 3ULL) + (uint64_t)(z1 >> 64);
    }
    /* subtract p if >= p: p = 2^130 - 5 => top==3 and low128 >= 2^128 - 5 */
    if (o2 == 3 && o1 == ~0ULL && o0 >= ~0ULL - 4) {
        __uint128_t z0 = (__uint128_t)o0 + 5;
        o0 = (uint64_t)z0;
        o1 = o1 + (uint64_t)(z0 >> 64);
        o2 = 0;
    }
    return (fe){o0, o1, o2};
}

static fe fe_add(fe a, fe b) {
    __uint128_t s0 = (__uint128_t)a.v0 + b.v0;
    __uint128_t s1 = (__uint128_t)a.v1 + b.v1 + (s0 >> 64);
    __uint128_t s2 = (__uint128_t)a.v2 + b.v2 + (s1 >> 64);
    uint64_t o0 = (uint64_t)s0, o1 = (uint64_t)s1, o2 = (uint64_t)s2;
    if (o2 >= 4) {
        uint64_t k = o2 >> 2;
        __uint128_t z0 = (__uint128_t)o0 + (__uint128_t)k * 5;
        o0 = (uint64_t)z0;
        __uint128_t z1 = (__uint128_t)o1 + (z0 >> 64);
        o1 = (uint64_t)z1;
        o2 = (o2 & 3ULL) + (uint64_t)(z1 >> 64);
    }
    if (o2 == 3 && o1 == ~0ULL && o0 >= ~0ULL - 4) {
        __uint128_t z0 = (__uint128_t)o0 + 5;
        o0 = (uint64_t)z0;
        o1 = o1 + (uint64_t)(z0 >> 64);
        o2 = 0;
    }
    return (fe){o0, o1, o2};
}

static fe fe_pow(fe r, uint64_t n) {
    fe result = (fe){1, 0, 0};
    fe base = r;
    while (n) {
        if (n & 1) result = fe_mul(result, base);
        base = fe_mul(base, base);
        n >>= 1;
    }
    return result;
}

/* canonical fully-reduced form of a scalar-context h, for comparison */
static fe canon(fe a) {
    fe one = (fe){1, 0, 0};
    return fe_mul(a, one);
}

static PyObject *selftest(PyObject *self, PyObject *args) {
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i * 7 + 3);
    uint64_t r0 = (*(uint64_t *)key) & 0x0ffffffc0fffffffULL;
    uint64_t r1 = (*(uint64_t *)(key + 8)) & 0x0ffffffc0ffffffcULL;
    fe r = (fe){r0, r1, 0};

    unsigned char ctx[256];
    void *func[2];
    unsigned char zeros[16] = {0};
    int mismatches = 0;

    /* test fe_mul against scalar poly1305 for random-ish h */
    for (int trial = 0; trial < 50; trial++) {
        fe h;
        h.v0 = 0x123456789abcdef0ULL * (trial + 1) + trial;
        h.v1 = 0xfedcba9876543210ULL * (trial + 3);
        h.v2 = trial % 4;
        memset(ctx, 0, sizeof(ctx));
        poly1305_init(ctx, key, func);
        memcpy(ctx, &h, 24);
        poly1305_blocks(ctx, zeros, 16, 0);
        fe got = canon(*(fe *)ctx);
        fe exp = fe_mul(h, r);
        if (got.v0 != exp.v0 || got.v1 != exp.v1 || got.v2 != exp.v2) {
            mismatches++;
            if (mismatches < 3) {
                printf("mul mismatch trial %d\n got %016llx %016llx %llx\n exp %016llx %016llx %llx\n",
                       trial, got.v0, got.v1, got.v2, exp.v0, exp.v1, exp.v2);
            }
        }
    }

    /* test combining: message of 8*16 = 128 bytes, split into 2 chunks of 64.
       h_total = h0 * r^4 + h1, compare emit to full. */
    unsigned char msg[256];
    for (int i = 0; i < 256; i++) msg[i] = (unsigned char)(i * 3 + 7);
    for (int chunks = 2; chunks <= 4; chunks++) {
        int blocks = 32; /* 512 bytes */
        int per = blocks / chunks;
        unsigned char ctxF[256];
        memset(ctxF, 0, sizeof(ctxF));
        poly1305_init(ctxF, key, func);
        poly1305_blocks(ctxF, msg, blocks * 16, 1);
        fe href = canon(*(fe *)ctxF);

        fe acc = (fe){0, 0, 0};
        for (int c = 0; c < chunks; c++) {
            unsigned char ctxc[256];
            memset(ctxc, 0, sizeof(ctxc));
            poly1305_init(ctxc, key, func);
            poly1305_blocks(ctxc, msg + c * per * 16, per * 16, 1);
            fe hk = *(fe *)ctxc;
            uint64_t after = (uint64_t)(blocks - (c + 1) * per);
            fe rp = fe_pow(r, after);
            acc = fe_add(acc, fe_mul(hk, rp));
        }
        if (acc.v0 != href.v0 || acc.v1 != href.v1 || acc.v2 != href.v2) {
            mismatches++;
            printf("combine mismatch chunks=%d\n acc %016llx %016llx %llx\n ref %016llx %016llx %llx\n",
                   chunks, acc.v0, acc.v1, acc.v2, href.v0, href.v1, href.v2);
        }
    }
    return PyLong_FromLong(mismatches);
}

