#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <dlfcn.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

unsigned int OPENSSL_ia32cap_P[8];
void poly1305_init(void *ctx, const unsigned char key[32], void *func);
void poly1305_blocks(void *ctx, const unsigned char *inp, size_t len, unsigned int padbit);
void poly1305_emit(void *ctx, unsigned char mac[16], const unsigned int nonce[4]);

#define MAX_THREADS 8
static int g_threads = 6;

typedef struct { uint64_t v0, v1, v2; } fe;

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t off;
    size_t len;
    const unsigned char *key;
    const unsigned char *nonce;
    unsigned int counter0;
    unsigned char poly_key[32];
    unsigned char poly_ctx[256];
} job_t;

static void *worker(void *arg) {
    job_t *j = (job_t *)arg;
    unsigned char ctr[16];
    uint32_t c = j->counter0;
    ctr[0] = (unsigned char)c; ctr[1] = (unsigned char)(c >> 8);
    ctr[2] = (unsigned char)(c >> 16); ctr[3] = (unsigned char)(c >> 24);
    memcpy(ctr + 4, j->nonce, 12);
    ChaCha20_ctr32(j->out + j->off, j->in + j->off, j->len,
                   (const unsigned int *)j->key, (const unsigned int *)ctr);
    void *func[2];
    memset(j->poly_ctx, 0, sizeof(j->poly_ctx));
    poly1305_init(j->poly_ctx, j->poly_key, func);
    poly1305_blocks(j->poly_ctx, j->out + j->off, j->len, 1);
    return NULL;
}

static pthread_t g_th[MAX_THREADS];
static job_t g_jobs[MAX_THREADS];
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static pthread_cond_t g_done_cv = PTHREAD_COND_INITIALIZER;
static int g_gen = 0, g_finished = 0, g_stop = 0, g_inited = 0;

static void *pool_worker(void *arg) {
    long idx = (long)arg;
    int my = 0;
    for (;;) {
        pthread_mutex_lock(&g_mu);
        while (g_gen == my && !g_stop) pthread_cond_wait(&g_cv, &g_mu);
        if (g_stop) { pthread_mutex_unlock(&g_mu); return NULL; }
        my = g_gen;
        pthread_mutex_unlock(&g_mu);
        worker(&g_jobs[idx]);
        pthread_mutex_lock(&g_mu);
        if (++g_finished == g_threads) pthread_cond_signal(&g_done_cv);
        pthread_mutex_unlock(&g_mu);
    }
}
static void pool_init(void) {
    if (g_inited) return;
    for (long i = 0; i < g_threads; i++) pthread_create(&g_th[i], NULL, pool_worker, (void *)i);
    g_inited = 1;
}
static void pool_run(void) {
    pthread_mutex_lock(&g_mu);
    g_finished = 0; g_gen++;
    pthread_cond_broadcast(&g_cv);
    while (g_finished < g_threads) pthread_cond_wait(&g_done_cv, &g_mu);
    pthread_mutex_unlock(&g_mu);
}

static fe fe_mul(fe a, fe b) {
    __uint128_t p00 = (__uint128_t)a.v0 * b.v0;
    __uint128_t p01 = (__uint128_t)a.v0 * b.v1;
    __uint128_t p10 = (__uint128_t)a.v1 * b.v0;
    __uint128_t p02 = (__uint128_t)a.v0 * b.v2;
    __uint128_t p11 = (__uint128_t)a.v1 * b.v1;
    __uint128_t p20 = (__uint128_t)a.v2 * b.v0;
    __uint128_t p12 = (__uint128_t)a.v1 * b.v2;
    __uint128_t p21 = (__uint128_t)a.v2 * b.v1;
    __uint128_t p22 = (__uint128_t)a.v2 * b.v2;
    __uint128_t acc = p00;
    uint64_t l0 = (uint64_t)acc; acc >>= 64;
    acc += p01 + p10;
    uint64_t l1 = (uint64_t)acc; acc >>= 64;
    acc += p02 + p11 + p20;
    uint64_t l2 = (uint64_t)acc; acc >>= 64;
    acc += p12 + p21;
    uint64_t l3 = (uint64_t)acc; acc >>= 64;
    acc += p22;
    uint64_t l4 = (uint64_t)acc;
    __uint128_t hi = (__uint128_t)(l2 >> 2) + ((__uint128_t)l3 << 62)
                     + ((__uint128_t)(l4 & 3ULL) << 126);
    uint64_t hi_top = l4 >> 2;
    uint64_t hv0 = (uint64_t)hi, hv1 = (uint64_t)(hi >> 64);
    __uint128_t f0 = (__uint128_t)hv0 * 5 + l0;
    __uint128_t f1 = (__uint128_t)hv1 * 5 + l1 + (uint64_t)(f0 >> 64);
    __uint128_t f2 = (l2 & 3ULL) + (uint64_t)(f1 >> 64) + (__uint128_t)hi_top * 5;
    uint64_t o0 = (uint64_t)f0, o1 = (uint64_t)f1, o2 = (uint64_t)f2;
    while (o2 > 3 || (o2 == 3 && (o1 > ~0ULL - 1 || (o1 == ~0ULL && o0 >= ~0ULL - 4)))) {
        __uint128_t z0 = (__uint128_t)o0 + 5;
        o0 = (uint64_t)z0;
        __uint128_t z1 = (__uint128_t)o1 + (z0 >> 64);
        o1 = (uint64_t)z1;
        o2 = o2 - 4 + (uint64_t)(z1 >> 64);
    }
    return (fe){o0, o1, o2};
}
static fe fe_add(fe a, fe b) {
    __uint128_t s0 = (__uint128_t)a.v0 + b.v0;
    __uint128_t s1 = (__uint128_t)a.v1 + b.v1 + (s0 >> 64);
    __uint128_t s2 = (__uint128_t)a.v2 + b.v2 + (s1 >> 64);
    uint64_t o0 = (uint64_t)s0, o1 = (uint64_t)s1, o2 = (uint64_t)s2;
    while (o2 > 3 || (o2 == 3 && (o1 > ~0ULL - 1 || (o1 == ~0ULL && o0 >= ~0ULL - 4)))) {
        __uint128_t z0 = (__uint128_t)o0 + 5;
        o0 = (uint64_t)z0;
        __uint128_t z1 = (__uint128_t)o1 + (z0 >> 64);
        o1 = (uint64_t)z1;
        o2 = o2 - 4 + (uint64_t)(z1 >> 64);
    }
    return (fe){o0, o1, o2};
}
static fe fe_pow(fe base, uint64_t n) {
    fe result = (fe){1, 0, 0};
    while (n) {
        if (n & 1) result = fe_mul(result, base);
        base = fe_mul(base, base);
        n >>= 1;
    }
    return result;
}

