    g_cap_loaded = 1;
}

static PyObject *chacha_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) return NULL;
    int has_aad = (aad.buf != NULL);
    if (key.len != 32 || nonce.len != 12) {
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        goto fail;
    }
    loadcap();
    size_t n = (size_t)pt.len;
    PyObject *out = PyBytes_FromStringAndSize(NULL, (Py_ssize_t)n);
    if (!out) goto fail;
    unsigned char *obuf = (unsigned char *)PyBytes_AS_STRING(out);

    unsigned char block0[64] = {0};
    unsigned char zeros[64] = {0};
    unsigned char ctr0[16] = {0};
    memcpy(ctr0 + 4, nonce.buf, 12);
    ChaCha20_ctr32(block0, zeros, 64, (const unsigned int *)key.buf, (const unsigned int *)ctr0);

    int threads = (n >= (1u << 20)) ? g_threads : 1;
    size_t chunk = (threads > 1) ? ((n / threads) & ~(size_t)63) : n;
    if (chunk == 0) { threads = 1; chunk = n; }
    size_t lens[MAX_THREADS];
    size_t offs[MAX_THREADS];
    if (n > 0 && threads > 1) {
        pool_init();
        for (int i = 0; i < threads; i++) {
            offs[i] = (size_t)i * chunk;
            lens[i] = (i == threads - 1) ? (n - offs[i]) : chunk;
            g_jobs[i].in = pt.buf; g_jobs[i].out = obuf;
            g_jobs[i].off = offs[i]; g_jobs[i].len = lens[i];
            g_jobs[i].key = key.buf; g_jobs[i].nonce = nonce.buf;
            g_jobs[i].counter0 = (unsigned int)(1 + offs[i] / 64);
            memcpy(g_jobs[i].poly_key, block0, 32);
        }
        pool_run();
    } else if (n > 0) {
        job_t j;
        memset(&j, 0, sizeof(j));
        j.in = pt.buf; j.out = obuf; j.off = 0; j.len = n;
        j.key = key.buf; j.nonce = nonce.buf; j.counter0 = 1;
        memcpy(j.poly_key, block0, 32);
        worker(&j);
        memcpy(g_jobs[0].poly_ctx, j.poly_ctx, 256);
        lens[0] = n; offs[0] = 0; threads = 1;
    }

    /* combine poly accumulators */
    uint64_t r0 = (*(uint64_t *)block0) & 0x0ffffffc0fffffffULL;
    uint64_t r1 = (*(uint64_t *)(block0 + 8)) & 0x0ffffffc0ffffffcULL;
    fe r = (fe){r0, r1, 0};
    fe acc = (fe){0, 0, 0};
    size_t total_blocks = n / 16;
    if (n > 0) {
        for (int i = 0; i < threads; i++) {
            fe hk = *(fe *)g_jobs[i].poly_ctx;
            uint64_t after = total_blocks - (offs[i] + lens[i]) / 16;
            acc = fe_add(acc, fe_mul(hk, fe_pow(r, after)));
