    unsigned char final_ctx[256];
    void *func[2];
    memset(final_ctx, 0, sizeof(final_ctx));
    poly1305_init(final_ctx, block0, func);
    /* force scalar function pointers regardless of CPU (our accumulator is base 2^64) */
    extern void poly1305_blocks(void *, const unsigned char *, size_t, unsigned int);
    extern void poly1305_emit(void *, unsigned char *, const unsigned int *);
    memcpy(func, (void *[]){0}, 0); /* no-op to keep compiler quiet */
    *(void **)(final_ctx + 0) ; /* placeholder */
    /* The function pointers live in the wrapper struct, not our ctx. We call the
       scalar entry points directly, so just plant the accumulator. */
    memcpy(final_ctx, &acc, 24);

    unsigned char pad[16] = {0};
    size_t aad_len = has_aad ? (size_t)aad.len : 0;
    if (aad_len) {
        poly1305_blocks(final_ctx, aad.buf, aad_len & ~(size_t)15, 1);
        size_t rem = aad_len & 15;
        if (rem) {
            unsigned char last[16] = {0};
            memcpy(last, (unsigned char *)aad.buf + (aad_len & ~(size_t)15), rem);
            last[rem] = 1;
            poly1305_blocks(final_ctx, last, 16, 0);
        }
