    size_t nrem = n & 15;
    if (nrem) {
        unsigned char last[16] = {0};
        memcpy(last, obuf + (n & ~(size_t)15), nrem);
        last[nrem] = 1;
        poly1305_blocks(final_ctx, last, 16, 0);
    }
    unsigned char lens[16];
    uint64_t al = aad_len, pl = n;
    memcpy(lens, &al, 8); memcpy(lens + 8, &pl, 8);
    poly1305_blocks(final_ctx, lens, 16, 1);

    unsigned char tag[16];
